window.POEM_DB=window.POEM_DB||{};POEM_DB["ming_049"]={"n":"郑善夫","dyn":"明","poems":[{"t":"病起步西禅","f":"七言律诗","c":["一春伏枕莺可怜，病起野池明白莲。","偶尔梳头出城郭，便应看竹到西禅。","天晴求食鸟双下，日午闭门僧独眠。","明发螺江有行役，红尘白雁异风烟。"]},{"t":"不寐","f":"五言律诗","c":["客思苦不寐，惊心豺虎喧。","羽书秋后捷，鬼哭夜深魂。","岁月消残燹，风烟失故园。","彭城有弟妹，絺绤念温存。"]},{"t":"夜入鲁北鄙","f":"五言律诗","c":["不见黄花面，凄其白雁前。","清渠接淮泗，衰草入幽燕。","月露犹团夜，兵戎更积年。","归途不可极，赍梦岁寒天。"]},{"t":"对湖二首 其二","f":"五言律诗","c":["远水明如镜，平林渺欲迷。","天多足鸿雁，沙暖定凫鹥。","秋事关身世，湖声避鼓鼙。","老渔吾愧汝，曼衍听天倪。"]},{"t":"闻开化用兵寄思道","f":"五言律诗","c":["旧是桃源地，如何丧乱滋。","荷殳连老少，流血满潢池。","蜀道奔惟汝，荆州仗有谁。","尊翁在垂白，莫遣怨流离。"]},{"t":"腊","f":"五言律诗","c":["南州不待律，腊后暖相催。","久客惜残岁，他时闻落梅。","家家斗酒会，处处短笳哀。","却忆江西北，渔樵戍未回。"]},{"t":"宿象山西坞二首 其一","f":"五言律诗","c":["乱木藏幽鸟，清商集古城。","暝烟分野意，山鬼习人声。","未把桐川钓，聊为颍水耕。","岩栖备寂寞，傥得遇初平。"]},{"t":"古剑行赠仇将军北征","f":"古风","c":["将军手提三尺冰。","乃是鬼国之铁大齿之珍，沧溟水枯淬不成。","莫邪断发跃冶死，而后龟文漫理流天晶。","霜锋闪烁鸊鹈凝，万金吴钩拖赪缨。","北斗七宿土花发，青天宝匣回机衡。","斩蛟断犀俱细事，此物自是苍龙精。","江翻河仄罔象急，提出白曜摇东溟。","飞芒杀白帝，喉下不可婴。","丰城古狱谁识女，斗牛之墟元气升。","沙塞秋高尘压城，黄龙白狼不肯庭。","山甫无人武安死，战马西向徘徊鸣。","安西都护君好行，此物应世世当平。","丈夫叱咤鞭风霆，国难不赴非俊英。","剑乎剑乎吾与女同死生。"]},{"t":"赠道夫四首 其一","f":"五言古诗","c":["华辀戒昧旦，之子赴北阙。","丛林无繁条，天气正十月。","中逵判绸缪，岂不念鹣蟨。","赠子金琅玕，呐呐心结愲。","京观多缁尘，终风永夕发。","修坂无逸轨，知者备失蹶。","故家亦有欢，浮荣亦有歇。","志士无间居，国忧固臲卼。","持子东门行，微言不堪说。"]},{"t":"赠道夫四首 其三","f":"五言古诗","c":["颓风吹岊水，饮子白玉杯。","意长酒力微，日暮倚徘徊。","十年绨袍恋，岁杪起离哀。","咎愆孰与陈，游衍孰与偕。","故国不可居，鲁生行凿坯。","金台何崒嵂，首山亦崔嵬。","茂子竹柏心，馀阴及枯荄。"]},{"t":"赠道夫四首 其四","f":"五言古诗","c":["富贵苦相迫，师徒多遁巡。","况当强盛时，谁能分沈沦。","之子仗剑出，举足生烟云。","河淮漫浩浩，中有要路津。","岂忘风波恐，壮士念委身。","陈霜冱修途，落月经柍桭。","良友志异域，此意难重陈。","欲扳时无何，欲往道无因。","愿为双意而，飞飞出城闉。"]},{"t":"沧洲夏夕","f":"五言律诗","c":["失意对蒲柳，沧洲昨夜风。","野云依暮笛，客况近秋空。","司马多年病，虞卿薄暮穷。","此生随造物，行止合飘蓬。"]},{"t":"秋晚直南省二首 其一","f":"五言律诗","c":["南宫秋晚直，更鼓不胜残。","鸿雁夜仍度，风霜天正寒。","宫车延北望，越客滞南冠。","三辅胡尘里，闻鸡未敢安。"]},{"t":"秋晚直南省二首 其二","f":"五言律诗","c":["清宵梦不彻，鸦啼深树间。","羯胡同汉月，陵寝在燕山。","青草乘时长，黄斿何日还。","因风候边使，咫尺见天颜。"]},{"t":"漫兴","f":"五言律诗","c":["日月随人事，溪山共客情。","水清鱼避影，松静鹤留声。","枌梓怡前辈，文章达后生。","时闻扣牛角，犹愧似要名。"]},{"t":"哭张士孚","f":"五言律诗","c":["同会今何在，斯人天下无。","盛时看谏草，何日奠生刍。","狐鼠私相庆，衣冠势益孤。","空馀青史上，遗简载名儒。"]},{"t":"对月怀闽中诸子","f":"五言律诗","c":["潞河今夜月，却望晋安城。","少谷堂犹在，东峰花正明。","旅愁存世故，乡梦逐人情。","展转怀诸子，风沙吾独行。"]},{"t":"黄岩黄宗贤为余筑室羽山招与共栖未果守官郁郁辄有东路之思奈故乡多难欲归不可行当赴其招矣记兴二首 其一","f":"五言律诗","c":["不分委沟壑，上林安一枝。","官随年少后，拙负故人知。","彝鼎终难就，箪瓢定不辞。","故园方苦乱，去采羽山芝。"]},{"t":"游金山寺","f":"五言律诗","c":["地控恒沙界，峰回沧海波。","潮声永夜壮，云气秣陵多。","龙窟存光怪，鲛宫湛绮罗。","黄斿蔽江左，何日返天戈。"]},{"t":"吊刘蕡祠","f":"五言律诗","c":["自昔悲歌地，刘生有墓祠。","秪馀经世志，况值讳言时。","去国英雄尽，还山事业迟。","黄金旧堂北，搔首动遐思。"]},{"t":"闻道","f":"五言律诗","c":["闻道汉天子，身封镇国公。","家初营上谷，臣得贺离宫。","铁券传何急，将军气尽雄。","郊牛凡五卜，车驾想河东。"]},{"t":"汪希周料兵淮楚","f":"七言律诗","c":["白马清秋出上京，勾陈光照亚夫营。","中原天子亲提剑，南国楼船远募兵。","消息秪愁千里草，逋逃新恨九江城。","汉家历数元无极，吴楚猖狂终自平。"]},{"t":"长安","f":"七言律诗","c":["渔阳上谷古幽州，王业千年易水流。","胡骑远窥青海月，秦城长建白龙斿。","总愁关塞生多垒，未道萧墙隐百忧。","日短时艰衰病早，几回簪笏梦沧洲。"]},{"t":"送惟可还三衢","f":"七言律诗","c":["昔年相逢胥水秋，今日重在闽山陬。","中间丧乱真怜汝，南鄙音尘不散忧。","别后山阳频弄笛，花时荆楚一登楼。","旄头尚直天西北，何地巾车各自由。"]},{"t":"顺门晓直","f":"七言律诗","c":["城上清钟散御墀，曙鸦声动万年枝。","天回阁道星辰迥，云捧乾清岁月迟。","内省尚承东阙旨，从官稀见早朝仪。","羁孤愁断周南目，仙仗新传到具茨。"]},{"t":"九日与倪宗正祝鸣和登观星台","f":"七言律诗","c":["秋尽繁阴苦不开，散愁无计一登台。","日边阊阖红云动，塞上风沙白鸟来。","秦分正当秋气盛，雁门未见玉音回。","百年与尔同羁旅，九日徒歌黄竹哀。"]},{"t":"寿日成礼奉天门","f":"七言律诗","c":["初日鸦啼宫树林，奉天高殿气骎骎。","衣冠况值千秋节，犬马真悬万国心。","白羽书来兵未解，黄河水落岁将阴。","龙斿凤辇关山道，边事辛勤风雪深。"]},{"t":"泰陵","f":"七言律诗","c":["千林松桧郁相回，永夜风生瀚海哀。","万国昔曾瞻气象，五云空复护崔嵬。","古来凤鸟长难至，天上龙髯定不回。","苦忆焚香赐第日，报恩真愧济时才。"]},{"t":"上妙高台","f":"七言律诗","c":["云海冥冥望不回，鲸波东蹴巨灵开。","中天楼阁虚无里，南国风烟江汉来。","世短动经多事日，愁长况上望京台。","白门金鼓维扬卒，落日空传黄竹哀。"]},{"t":"武夷曲次晦翁棹歌十首 其一","f":"七言绝句","c":["幔亭彩幄会仙灵，紫雾濛濛薄太清。","奏罢人间可哀曲，凤笙龙管杳无声。"]},{"t":"武夷曲次晦翁棹歌十首 其四","f":"七言绝句","c":["藏里黄棺壑上船，春风秋雨自年年。","觉来天地终归尽，炼得丹成亦可怜。"]},{"t":"竹枝词二首 其一","f":"七言绝句","c":["西涧西边东涧东，千山不断万山通。","谢豹见春啼出血，王孙上树捷如风。"]},{"t":"竹枝词二首 其二","f":"七言绝句","c":["梨岭遥于枫岭遥，小关高比大关高。","佣夫过岭如平地，一岁来回二百遭。"]},{"t":"送人之郁林二首 其一","f":"七言绝句","c":["苍梧之峰云万盘，下控牂牁连百蛮。","莫道蛮方非近地，日南南是汉关山。"]},{"t":"送人之郁林二首 其二","f":"七言绝句","c":["郁林东下对扶桑，黑雾沉山日晕黄。","鹧鸪啼上桄榔树，一寸乡心万里长。"]},{"t":"羽猎谣三首 其一","f":"七言绝句","c":["君王自拥鹔鹴裘，猎骑翩翩尽贵游。","归来锡宴传封拜，狗监鸡坊十二侯。"]},{"t":"羽猎谣三首 其二","f":"七言绝句","c":["羽林十万是亲军，渔阳铁骑天下闻。","厩马长留太白垒，胡天惊散犬羊群。"]},{"t":"羽猎谣三首 其三","f":"七言绝句","c":["今年天子又行边，敕报旄头照酒泉。","乘舆自领骠姚部，内使宣颁九府钱。"]},{"t":"即事","f":"五言古诗","c":["赤县山河在，黄龙沙塞长。","秪忧胡部落，不着舜衣裳。","骠骑年年没，单于世世强。","仆姑寒射月，觱篥夜含霜。","宝毂犹深入，金槊或转伤。","前车未为远，神武有英皇。"]},{"t":"闻西江乱","f":"五言律诗","c":["乍发洪都使，风传消息回。","荆吴得剧孟，江汉尚深哀。","画角连城动，黄衫自将来。","万方思系虏，宁乏亚夫才。"]},{"t":"南望湖二首 其一","f":"七言绝句","c":["南望诸湖波映空，扬舲东逐芰荷风。","垂杨乱覆茅檐绿，好看鱼梁山照中。"]},{"t":"钱塘映江楼冥坐观潮","f":"五言律诗","c":["钱王此开济，旋入宋山河。","潮汐秋来壮，雷霆水上多。","尚传江有怒，翻恨海无波。","飒飒攒陵树，悲风日夜过。"]},{"t":"宿归云庵","f":"五言律诗","c":["泽国变元气，名山留晚芳。","云藏伏虎寺，花近挂瓢堂。","鹅鹳飞腾远，渔樵言笑长。","沉冥达者事，散地即慈航。"]},{"t":"新昌县晓行","f":"五言律诗","c":["暝发新昌县，晨临赤土隈。","秋花随地有，渚雁与云来。","杂树炊烟出，前泾山照回。","忽闻歌伐木，行路兴悠哉。"]},{"t":"寒食与木虚登屴崱峰遂饯公衡","f":"七言律诗","c":["绝顶天风云乱飞，海门高浪近春衣。","霸图王气东南尽，尧韭秦花天汉稀。","此地赏心惟汝共，万方愁目欲何依。","要知寒食山中意，萍叶江湖几是非。"]},{"t":"柴门二首 其一","f":"五言绝句","c":["凉月光不了，照我芳桂丛。","白凫如人长，来往柴门东。"]},{"t":"柴门二首 其二","f":"五言绝句","c":["家住白湖阳，习见风波事。","苕荻何苍苍，乱我兰与芷。"]},{"t":"寄戴仲鹖延平","f":"五言古诗","c":["嗟尔投荒在，十年归鬓新。","豹文淹瘴疠，龙节渐风云。","往事收残泪，清时录远臣。","别深鱼雁阔，迹久凤麟驯。","余亦丰城物，思君剑水滨。","客衣浑自浣，不染洛阳尘。"]},{"t":"天末忆方思道","f":"五言律诗","c":["远怜方比部，经岁断来书。","何日垂嘉树，青青拂敝庐。","累憎鸿雁响，三见柳条疏。","幽独疲孤梦，松斋月正虚。"]},{"t":"侠客行","f":"古风","c":["万里金微道，防秋世不同。","秦城时借寇，汉女岁和戎。","落日吹《杨柳》，沙场恨未穷。","莫收张掖北，复失酒泉东。","天子遑推毂，将军誓挂弓。","黄金装雁辔，白璧饰蛇?。","霸气天山雪，边声瀚海风。","死生惟义激，部曲总骁雄。","羌笛回青草，燕歌感白虹。","营开月晕破，战胜贺兰空。","直捣阏氏北，横行沙塞中。","始知魏绛怯，岂说贰师功。","洗甲蒲昌海，扬兵苜蓿峰。","驰归大宛马，一一渥洼龙。","赐邑连京洛，图形列上公。","男儿雪国耻，不在藁街封。"]},{"t":"秋日病怀","f":"七言律诗","c":["南州木落岁萧萧，蓟野风烟万里遥。","病后客心惟药物，秋来人意满云霄。","平沙雁带三湘雨，横浦帆归八月潮。","摇落应悲楚公子，不将旧业付渔樵。"]},{"t":"送杨明府入觐","f":"五言律诗","c":["双阙玄霄上，三山沧海边。","云逵望凫舄，明府似神仙。","曲报离城调，琴希清庙弦。","烦君告天子，百姓尚颠连。"]},{"t":"复叹三首 其一","f":"古风","c":["我生四十无闻时已暮，三年角巾守烟雾。","空村落日门不开，独抱鹑衾哭穷路。","麒麟趾折龙马杳，世俗那得知其故。","呜呼兴衰用舍总在天，中夜击剑心茫然。"]},{"t":"复叹三首 其二","f":"古风","c":["忆昔金闺困天梏，乞身还山思维谷。","频年藜藿口不充，况复呻吟卧床褥。","生子当如孙仲谋，豚犬区区但口腹。","于乎天时人事两不值，我生安命而已矣。"]},{"t":"复叹三首 其三","f":"古风","c":["归来来归愁复愁，洁己不及沧溟流。","苦逐狝猴逐山雪，眼中萧萧谁故物。","天涯良友半槁死，我身虽在空皮骨。","于乎青山伐木鸟嘤嘤，胡为使我无友生。"]},{"t":"病中哭伯固二首 其一","f":"五言律诗","c":["我眼双枯尽，那堪更哭君。","平生犹铁石，灵爽定风云。","葵藿虽同志，凰麟不恋群。","吾徒向凋谢，谁黻太平文。"]},{"t":"不寐","f":"五言律诗","c":["反侧终难寐，寒天候不明。","经旬淹厉气，永夜厌滩声。","万事呻吟外，他乡儿女情。","还闻丧良友，展转泪交横。"]},{"t":"哭遂初","f":"五言律诗","c":["良友看馀几，今年报女亡。","江山有赪谷，风雨泣秋堂。","元气能无损，星文定不光。","连宵激孤志，洒涕向钱塘。"]},{"t":"忧","f":"七言律诗","c":["拟将新句咏销忧，咏罢重增双涕流。","柱下朱郎成永别，江东黄尉竟何求。","青袍事业悲三试，画省风烟感四休。","摇落江山客途里，石门修竹梦林丘。"]},{"t":"黄山杂诗十首 其一","f":"五言律诗","c":["黄山如岱岳，萝山若梁甫。","曾颠遏行云，屼屼自太古。","咸池荡初景，昧旦河已曙。","我梦天都行，笑折扶桑树。"]},{"t":"黄山杂诗十首 其四","f":"古风","c":["黄山奠南服，??分楚望。","连峰标天枢，结秀极地藏。","金鸡时一鸣，高鸟不能上。","眷兹俯沧海，穷岁梦波浪。"]},{"t":"黄山杂诗十首 其五","f":"五言律诗","c":["蓝田有嘉植，种玉世莫比。","灵气纷璀璨，熠熠寰区里。","玞碧奴视之，琳琅乃支子。","不遇后车载，终伏磻溪水。"]},{"t":"黄山杂诗十首 其七","f":"五言律诗","c":["园庐春欲至，岁事此伊始。","采芳入层云，散发不及理。","蚕眠桑柘繁，土膏农务起。","龙斗未敢闻，巢父正洗耳。"]},{"t":"至日长陵陪祀","f":"七言律诗","c":["长陵西接黄花镇，白雪苍岩夜色遥。","阴殿衮龙犹在目，往时松柏已干霄。","总闻一怒风尘起，想见千官迁次朝。","怅极两京兴废事，小山何意起渔樵。"]},{"t":"汎太湖望洞庭","f":"楚辞体","c":["太湖风兮白波，瞻望洞庭兮森云萝。","撷杜蘅兮水中，吊范蠡兮山阿。","目盈盈兮不极，美人远兮柰何。","渺予怀兮夕阳，听不可兮吴歌。"]},{"t":"凤山辞","f":"楚辞体","c":["夫唯山之效美兮，纷众万之淑祥。","有振振之令鸟兮，绚采采之文章。","涓高梧以营室兮，口卒瘏而周皇。","殷九苞之未诞兮，轩远翥而求凰。","陆海邈其伏阴兮，屏尔类以自臧。","大网结于中野兮，二苞格而鸣冈。","徙阿阁于戾止兮，披晨曦之耿光。","嘅禄运之倏穷兮，翳冲漠而遥翔。","奇气宕于六天兮，毛衣委于故邦。","群鸱倨以自迈，众息下其如僵。","苟灵光之弗泯，虽捐性其奚伤。","谇曰：予悲夫云和之曲卒不续兮，顾此鸟之永遗。","岂四灵之不有兮，世盖溷之以蝘蜓与螽斯。"]},{"t":"古战场","f":"古风","c":["朝发汾河，暮经白沟。","茫然战场，四时为秋。","黄云阨关，壮士不忧。","拔剑斫地，战骨无收。","风沙冥冥，髑髅啸歌。","鸟飞不下，客行奈何。","世无凰麟，龙虎斗争。","谁哉弄丸，四海解兵。"]},{"t":"菖歜二章赠孙太初山人","f":"古风","c":["菖歜葱葱，在彼涧滨。","岁茁九花，世人不纫。","秘之颍谷，以俟云君。","念彼菉葹，苍苍广津。","菖歜青青，在彼原隰。","岁茹九节，可以绝粒。","华滋寂寥，尔乃独立。","世无神皇，凤衰麟泣。"]},{"t":"野田黄雀行","f":"古风","c":["翼翼黄雀，集彼榛柯。","上有鸷鸟，下有虞罗。","低飞不可，高飞奈何。","曷不去此，野田有禾。","鹏雏摇摇，隼则制之。","兔罝纤纤，鸿则罹之。","龙潜在渊，可以全身。","壤蠖不屈，何以引伸。","朱凤威垂，稠羽是依。","鸱枭化之，矰弋安施。"]},{"t":"梁之石操上杨国老","f":"楚辞体","c":["梁之山兮，岳岳其砥。","石之磐磐，兴云及雨。","肤合之施，其谁弗被。","立天之中，君子不匮。","天常西亏，地亦东溃。","我不尔奠，曷其有位。","大皇时行，大浸时滋。","怀贞用敦，君予以几。"]},{"t":"梦井歌二章","f":"古风","c":["井之京京，其出渊渊。","汔至不繘，谓我叵泉。","甃如幕如，我梦乘如。","寤怀载且，维以永戏。","井之渊渊，爰是用汲。","王明王明，受此戬福。","渫而不食，于井何伤。","君子之履，不迁其方。"]},{"t":"白泉二章赠汪希周","f":"古风","c":["湔湔流泉，行彼地中。","灿为星宿，丽尔云空。","万殊之母，直遂涵弘。","贲以正本，蒙以养功。","君子果行，丕显其逢。","湔湔流泉，㶁㶁滥觞。","积为江汉，博大以刚。","彼王者明，受福无疆。","神龙所都，厥澍载滂。","君子利用，何往弗臧。"]},{"t":"飞龙引","f":"五言古诗","c":["采铜铸宝鼎，炼作九还丹。","服食寿长生，长生千万年。","白日跨飞龙，宸游上九天。","如何鼎湖路，一去无时还。","君子贵返终，仙术谅非难。","方士费论说，彼心讵能安。","秦皇与汉武，黄土高巑岏。"]},{"t":"游莆中麦斜岩 其一","f":"五言古诗","c":["陵坡回燠风，楸枰净如沐。","戒言寻浩渺，聊以散沈郁。","况兹二月半，芳草萋以绿。","青霞媚遥天，乌巾入殊俗。","嵚崎麦斜岩，幽人有高足。","怀贤招艾轩，探真小樵谷。","世缘夙已断，碧岭不可辱。","君看南昌尉，去去从所欲。"]},{"t":"游莆中麦斜岩 其二","f":"五言古诗","c":["麦斜何崭崭，兹游惬心魂。","石洞入窈窕，不说桃花源。","白云走平地，崇冈亦崩奔。","松篁翳重阴，境幽判寒暄。","天关手可摩，始觉所历尊。","赤城去不远，玉禾行当蕃。","相期马子微，于此采灵根。"]},{"t":"登云居山二首 其一","f":"五言古诗","c":["贪清不自爱，历历疏远目。","缅怀云居胜，驾言陟层曲。","樛枓遁斧斤，岐径积朴樕。","云栈纷当心，不敢轻落足。","扪枯骤战兢，披荆逾匍匐。","尪羸无奈何，况复迷浚谷。","虽无夔莘警，讵测蜒蚿伏。","少焉青霞深，转思白日速。","山海信伟观，何以慰彳亍。","我行孰驱迫，自致穷途哭。","伯阳不出门，世路了如烛。","愿昭篯子诫，或免华山辱。"]},{"t":"登云居山二首 其二","f":"五言古诗","c":["搜奇头欲改，禹穴未得傍。","忽慕麦斜岩，玄境足佳况。","连峰削芙容，石门天下壮。","筼筜复修纤，天声落屏嶂。","云居独奇绝，遐思愈飞飏。","以兹发高踪，力欲排云上。","百息径崄艰，一眺极沆漭。","鹓鸾税仙骖，芝荪洗凡状。","试按山海图，一一皆不妄。","虽然羸瘵成，已过平生望。","应悲蜉居子，兀兀坐盆盎。","吾将从卢敖，直与云露抗。","西凌昆崙风，东薄沧海浪。","前期邈悠悠，拊膺以惆怅。"]},{"t":"下何岭","f":"五言古诗","c":["云居不可升，塞型眇天上。","讽然下何岭，歘若坠青嶂。","数日愁险艰，及此爱平旷。","林墟相维亘，川原亦排荡。","春容丽华滋，百草不相放。","踌躇谷鸟喧，坐失青藜杖。","山中胜事繁，林叟重揖让。","岂无山水癖，筋力故莫彊。","栗里在人境，君子有末尚。"]},{"t":"溪上","f":"五言古诗","c":["南行遵溪浒，流景何楚楚。","溪毛绣藻蘩，游鱼聚相喣。","锦石亦参错，绿发明可数。","小者如卧羊，大者如伏虎。","飞湍所磨荡，兀兀自太古。","丛薄交深春，不但蔚榛楛。","兹游倦登陟，到此一延伫。","况有令主人，意气不为忤。","担囊轻百里，一一适我所。","春花未终极，岂即怀故土。","锦江非不佳，人情薄如楮。","西游杜陵老，安得免愁苦。"]},{"t":"复晴趋仙邑","f":"五言古诗","c":["晴光荡游目，一雨山逾碧。","翛然戒晨征，乃尔骋双屐。","修林静宿氛，故术没行迹。","仆夫重远路，贱子有奇癖。","南循抵仙城，北放兰阪陌。","波岭行有需，朋曹意安极。","我生无漫游，允得就三益。"]},{"t":"古意三首 其一","f":"五言绝句","c":["蓬门霜雪繁，玉颜苦禁当。","稍识春风面，春风转断肠。"]},{"t":"古意三首 其二","f":"古风","c":["蚕盛不理妆，露采陌上桑。","但知织作?，不觉年貌伤。"]},{"t":"古意三首 其三","f":"五言绝句","c":["宝镜皎如月，价值千黄金。","偏照可怜色，不照可怜心。"]},{"t":"丼泉子","f":"五言古诗","c":["客有罗浮君，羽衣行翩翩。","长揖谢世事，鍊性三十春。","沆瀣不满口，貌如藐姑神。","问道广成子，空同高嶙峋。","挂瓢椅树枝，振舄天风门。","朅来吊延陵，晤言东海滨。","示我紫尸术，挺身入层云。","誓将结瑶华，引手长相亲。"]},{"t":"子夜吴歌九解赠殷近夫","f":"五言古诗","c":["郎今落海滨，侬亦可怜身。","不见昌阳草，何曾生要津。","侬身不下堂，郎居隔江水。","虽则隔江水，思心日万里。","昔别于何时，十载参与商。","岂是无所见，狼嘴夜夜张。","夜夜抚素琴，恻恻生怨慕。","枯桐在膝上，梧子在何处。","融融四五月，婉婉采莲女。","海上无芙渠，谁则识莲子。","低头摘荷叶，举头看月光。","归来觅剪刀，为欢制衣裳。","终日对海棠，终夜不成寐。","何以不成寐，花开侬独自。","登楼看双星，蜘蛛在楼角。","绵绵腹中丝，求匹不能得。","欢去一何久，欢来一何晏。","来时何所赠，双双云锦段。"]},{"t":"吴中吟二首 其一","f":"五言律诗","c":["出自吴东门，遥望姑胥台。","望久无所见，回风惨蒿莱。","图王志未就，神木生劫灰。","三复春秋传，英雄使人哀。"]},{"t":"吴中吟二首 其二","f":"古风","c":["越女进馆娃，楚囚落天涯。","二物不并立，海水漂鸱夷。","湛卢南入郢，神物竟先知。","吴宫八百年，旦夕游鹿麋。","缅晤丧亡主，岂尽庸以?。"]},{"t":"冬日同顾九和殷近夫孙太初顾与成汎太湖","f":"五言古诗","c":["震泽夫何如，岁晏意自好。","天风吹玄冥，雪浪入浩溔。","鼋鼍浮山岳，白日摇晴昊。","洞庭渺林屋，流水隔烦恼。","昔有绿毛翁，于此采玄草。","风云白石床，鬼物为持保。","闻兹长道念，携舻事幽讨。","平生竹溪逸，矧是同怀抱。","相从扪绿云，坐听启鸿宝。","终当吸沆瀣，去去游亭纛。"]},{"t":"江上送殷二秀才","f":"五言古诗","c":["觏子在逆旅，失子在岁晏。","一似南飞鸿，一似西归燕。","繁露戾修林，终风捷如箭。","过翼趋所期，殊方卒相见。","物情异冷煖，人事阻华面。","迟余玉门春，子复穴梁殿。"]},{"t":"元日","f":"五言古诗","c":["东君御征辕，玄冥迅回车。","温风倏尔至，古梅茁其葩。","桃户新受符，蓼盘香团芽。","感此念故里，兼之怀年华。","炙蛎洽弟兄，问岁话桑麻。","二期走逋旅，簪绂生叹嗟。","坐兹失初服，五内长负痾。","兔窟有穴狐，凰木亦栖鸦。","悟机贵在蚤，勿令负云霞。"]},{"t":"放舟荆溪寻张公洞不果归至滆湖起步长桥望烟景放歌","f":"五言古诗","c":["日晷于东驰，羁人复北征。","鼓舠下荆溪，言访张道陵。","缘薄扼事艰，意短回修程。","稠年戒襟素，履兹荒志诚。","坐令紫霞居，远隔于青冥。","所赖滆湖好，烟景疏天声。","躞蹀骋瞻眺，稍慰沧洲情。","青镜不肯私，金精几时营。","寓形若流电，空怀紫金经。"]},{"t":"河上送鲍使君","f":"五言古诗","c":["柔风协河洲，回飙被泗渎。","贤轺指玉衡，过门不停轴。","结交何所将，解我双英瑴。","岂无锦绣段，感彼并朽藗。","希君复自爱，勿使輶出椟。"]},{"t":"贫女吟八解","f":"五言古诗","c":["南阳有贫女，抱瓮立水澳。","趾短泥泞修，挽衣以彳亍。","自言良家息，沦踬类草木。","亦知奉壸范，谁与周㷀独。","㷀独谁与周，室中无储遗。","闭户理机杼，苦乐中自知。","扬声度昏旦，秕糟转无时。","岂不爱绮罗，乃有杼轴悲。","杼轴曷足悲，感往思维谷。","三年喧格斗，肉骨不可赎。","非无好里闾，处子有约束。","失时当告谁，甘此守饘粥。","东邻有嫠妇，宵旦当户哭。","良人淹戍边，存否不可卜。","近闻边衅起，百万化鱼肉。","生离云有期，死别竟何续。","西邻亦送女，夫婿轻薄儿。","朝捷忘归矢，暮挟青楼姬。","床头合欢被，桁上嫁时衣。","悠悠百年思，采菲生怨咨。","南村有弃妇，曩亦诫雍肃。","夫君心不同，入闼转见逐。","白头且勿唱，绿发顿空谷。","榆蒲悴高秋，却怨飘风速。","北里多豪华，服御纨与绮。","张幕集权贵，炮熊炙文鲤。","妙舞杂燕赵，徵歌遍梁楚。","岂无良蹇修，妾心自不尔。","凤凰栖梧桐，下食青琅玕。","鸱鸢嚇腐鼠，但识彼所欢。","人情竞刀锥，岂识达士贤。","庭槐鸣周周，微音向谁宣。"]},{"t":"义鸠篇","f":"五言古诗","c":["端居肃元府，永惟玄化机。","神理罔有忒，众万讵能违。","翔植纷总总，气感率有知。","无论大圣狂，咎休固其宜。","荆茂于义音，乌驯以孝思。","细德亦鼓物，而况凤与麒。","戒言彼狡童，胡自决德基。","达人上内植，履祥复何疑。"]},{"t":"赠黄肇三首 其一","f":"五言律诗","c":["终风劲柔条，游子返故乡。","兄嫂糁藜羹，慈母缝衣裳。","离觥载恓恻，平旦天一方。","来忘楚塞远，去觉闽山长。"]},{"t":"赠黄肇三首 其二","f":"五言古诗","c":["来如秋空鹗，去似春泥蠖。","春泥何淤沮，百足进复却。","人情乡邦好，归客何萧索。","室堂雍婉娈，殊方信不恶。","旋飙掠樯乌，骨肉临当坼。"]},{"t":"赠黄肇三首 其三","f":"五言律诗","c":["上林未揖让，广莫进疠瘴。","大江不可踰，坡陁莽翻荡。","入门报所亲，何以慰惆怅。","庭萱蕤有永，塞雁宛相望。"]},{"t":"夏日阙庭见鹤","f":"五言古诗","c":["景风薄梁殿，铜云递玄虚。","侵星不栉发，入直承明庐。","朅来双白鹤，跄跄下彤除。","竦身舞飞容，扬音结长吁。","物情含所因，悲鸣胡为乎。","曰余览幽经，腼尔情不舒。","霜毛丽藻质，岂受泥水污。","内饫土木气，外有金精敷。","盗泉非吾愿，腐鼠安足图。","缅惟玄圃骖，乃是青田雏。","言兹非世畜，何以羁此都。","误入燕雀网，遂被樊笼拘。","委质太液池，昂藏狎鸥凫。","崇朝受饼饵，向夕听传呼。","以兹抱懊惋，宁复竞盈馀。","冉冉积年岁，翼翼向盆盂。","岂无四海心，所惜六翮疏。","顾惟鹰犬坊，岂乏耳目娱。","矜春有雪衣，绝地复的卢。","终当返真性，去去翔天衢。","一举历五岳，再举遍九区。","翛然逐凤凰，下来瑞唐虞。","此意良不极，流光倏于徂。","麟伤古亦然，聊自遣烦纾。"]},{"t":"夏日叹","f":"五言古诗","c":["长嬴何苍凉，大火不烘爆。","烛龙西北死，踆乌东南蹙。","迟迟凌曾桑，忽忽下蒙谷。","钧天不敷华，群阴岂全伏。","金星似火赤，未旰即动角。","应感阴沴盛，转讶日晷促。","羲和职业废，寒暑事反覆。","麦秋犹寒衣，絺绤未即录。","雄风来蓬蓬，惨怛蜚大屋。","扬雾清昼昏，愈觉白日速。","迅雷不发荣，虺虺振坤轴。","三时无雨泽，何以升五谷。","蝝螣复不仁，延祸到朴樕。","近闻河内外，数载茹草木。","更兼豺虎繁，死者十五六。","诸公乐安稳，群倖厌梁肉。","万姓亦何罪，坐使蒙螫毒。","以兹和气乖，无怪边衅踧。","天人象已显，岩庙计须熟。","缅思弘治化，历历在耳目。","燮理得所司，气侯有攸属。","八风率顺序，五纬不愆毂。","廿年宣重光，万国昭玉烛。","平路生广庭，箑脯出荒服。","所以覆帱下，老不闻杀戮。","中遭屡更变，美意尚可掬。","勖哉柱石翁，弘治是龟卜。","狂夫不解事，岂敢糜廪禄。","仓皇杞人忧，凯切麦丘祝。","但愿丽大明，末光普曾曲。"]},{"t":"题九峰书院","f":"五言古诗","c":["圆象序兴没，大道蔑消沈。","濂伊冥契后，作者纷林林。","石鼓未榛莽，嵩阳亦嵚崟。","九峰复何如，夫子重幽寻。","结架云霞交，讨求松竹阴。","探真破众眩，集虚嗣希音。","川注理有托，物化情乃任。","锵锵广陵散，写之龙唇琴。","闭阁缀道论，永为后贤琛。","曰余早送误，捷径坐滞淫。","窃睐无穷门，浩荡纠寸心。","眷言抠裳衣，毕志遵所钦。"]},{"t":"赠潘子四首 其一","f":"五言古诗","c":["俚子习巴唱，佳人奏阳春。","怀仁出湘浦，信美乃寡伦。","心期不自媚，持以奉明君。","上弦协凤吹，下弦泣鬼神。","边地霜霰繁，刚风凛以辛。","但恐变商徵，指诘不得伸。","踌躇广庑下，此意难重陈。"]},{"t":"赠潘子四首 其二","f":"五言古诗","c":["大道久湮闭，王英改波澜。","时流习玄默，危言伏祸患。","君子守贞亮，所贵殉世艰。","严霜被广域，朱葳骇前观。","嘉卉亦摧颓，而况莩与菅。","茂子竹柏意，慰我樗栎颜。","春华谅峭茜，表之在岁寒。"]},{"t":"赠潘子四首 其三","f":"五言古诗","c":["念昔与子别，繁霜结崇榕。","犹怀乌石镳，复转并州蓬。","昔也辰避参，今兹燕离鸿。","群生固无极，百龄会有穷。","平时所交友，昏昼谁则同。","兰苕向披靡，玄曜岂恒中。","子其保光惠，远行慰㤝㤝。"]},{"t":"赠潘子四首 其四","f":"五言古诗","c":["浮金肃丛薄，黄落栖广墟。","念子事孤往，烦忧结不舒。","斥鴳足蓬蒿，凤凰则高梧。","谊雅苟不易，岂必均所趋。","志士贵努力，丈夫行弃繻。"]},{"t":"东海有一士","f":"五言古诗","c":["东海有一士，被服云锦裳。","饥餐炎洲霞，渴吸瑶池浆。","鹤驭何翩翩，九垓一相羊。","朝发岗䍚野，夕憩沈默乡。","眷言与汗漫，抗臂穷洪荒。","九州虽云大，视之如室堂。","纷纷尺蠖徒，看彼鸿鹄翔。"]},{"t":"黄伯固","f":"五言古诗","c":["黄郎遁世士，抱影处空谷。","撷芳上木末，采藻立水澳。","妙善难可邻，岁暮守幽独。","怀姝匪自媚，出门重结束。","风云一抚念，故术草丰蓐。","鄙夫附丘阿，达者从所欲。","康乐营石门，知章疏剡曲。","存道苟不贰，岂贻山灵辱。"]},{"t":"秋夜迟王员外时行","f":"五言古诗","c":["凉风升寒节，切切充重帏。","坚冰戒时至，鸿雁明其几。","春滋净不处，秋隼方高飞。","鉴物沈幽志，谁能不怀归。","素月临丘榛，灼灼澄圆晖。","圆晖岂不爱，零露沾我衣。","迟我同怀子，濡滞尚安之。","呼琴为子鸣，调苦使心违。","不恨岁载徂，但恨知音稀。","盈缩本恒理，伤哉生别离。"]},{"t":"初离京邑留别诸同志四首 其一","f":"五言古诗","c":["陈车遵城闉，振策导广路。","仰盻孤云征，俯见流波溯。","感念平生欢，岂以杯酒故。","群居不自觉，相失增怨慕。","川河引舟楫，陵陆旷烟雾。","重觏难可寻，努力敷襟素。"]},{"t":"初离京邑留别诸同志四首 其二","f":"五言古诗","c":["浮萍恋故波，离鸟思故林。","故林既得期，俦侣无遗音。","与子共朝夕，奚堪更商参。","山河日以邈，霜霰日以深。","鸿麟无时至，安能诉幽襟。","晤好谅有时，迅节忽载阴。","愿言敦明德，白首慰离心。"]},{"t":"初离京邑留别诸同志四首 其三","f":"五言古诗","c":["驰车太行坂，北首入楚泽。","迷途不早悟，困顿安所适。","爵服载忧患，趋者何充斥。","流俗日向靡，胡为重濡迹。","京尘复何长，不见所缁白。","凡骀御文舆，赤骥且辟易。","谁能违众好，共整东山屐。"]},{"t":"初离京邑留别诸同志四首 其四","f":"五言古诗","c":["长歌逾蓟门，凝眸眺崇京。","陵阙何崔嵬，马行令心怦。","虽云返乡域，不获偕良朋。","劳鹘无劲翮，断鸿有离声。","幽期莫可并，沉虑独拊膺。"]},{"t":"见蜚雁","f":"五言古诗","c":["凉风动沙碛，朔雁至纷纷。","为避阴山雪，翻冲楚泽云。","嗷嗷清作籁，总总字成文。","意适稻梁得，心惊弋弹闻。","时县出塞梦，肯妒下鞲勋。","远愧青田鹤，高飞绝世氛。"]},{"t":"谒留侯祠","f":"五言古诗","c":["吾慕张子房，乃是紫霞客。","志士有苦心，麟趾暂驱策。","功隳博浪沙，折节下黄石。","谈笑用汉祖，毕志任所适。","神山逝朱凤，鸷鸟空累百。"]},{"t":"大雪行三茆山中","f":"五言古诗","c":["解束悟服食，营虑结山水。","比闻三峰秀，赍欢一来此。","同云布坤维，六花漫不止。","升危滞遐踪，寓目杀高志。","真源不可往，罔蜮兼泥滓。","居凡殊所厌，还丹亦难恃。","太虚本宅无，彭殇同已矣。","安得庄生达，相与析玄理。"]},{"t":"游烟霞洞天","f":"五言古诗","c":["今我忽不乐，驾言结游驷。","遥望南山木，郁郁有真意。","崖瀑垂素幢，谷风击繁吹。","洞幽无别踪，白云蔼而至。","狨啼修术暗，猱閧樛枝坠。","山精绿罗衣，见客宛自媚。","形遗物不违，真存道匪贰。","鉴兹浃心想，去与众俱弃。"]},{"t":"赠何仲默","f":"五言古诗","c":["何子生知姿，弱齿咏凤皇。","垂帷破坟籍，一目能十行。","雅调走鲍谢，雄才抗班扬。","黄钟一彻虚，丝管空铿锵。","陆沉金马门，卒岁泣麟伤。","贾生亦逢时，杜甫终为郎。","古来圣哲士，位细非所妨。","屼屼大复山，后贤永相望。"]},{"t":"赠近夫","f":"古风","c":["石川山东晶，童稚只自树。","昔探庄老窟，终蹈宣尼矩。","学术通天人，声华照区宇。","中年?宦籍，志岂屑轩组。","挂冠四五载，逊迹谢官府。","近因避虎豺，复出图三釜。","海邑方用兵，庶务纷蚊聚。","才闻借寇恂，已见思何武。","吾观江河流，喧豗恶足数。"]},{"t":"发越州","f":"五言古诗","c":["生无冠组分，碌碌守迍邅。","越南十二月，尽室复远迁。","故国眇天末，扁舟薄言旋。","闽中地气暖，可免丝与绵。","旧业虽荒芜，尚有一顷田。","他乡困饥寒，胡为重留连。","且闻江海熟，已不忧荒年。","此州固信美，旅寓岂其然。","盘餐未易遘，薪水亦费钱。","虽得山水玩，顾非贫士便。","素癖厌人事，况乃居市廛。","毅然舍此去，飘飖御风烟。","夜泊桐江云，放歌渔父篇。","朝登富春山，钓台两高悬。","如云迫迟暮，顿觉忘忧煎。","行复经武夷，真诠落吾缘。","引手向紫霞，高招控鹤仙。","沆瀣亦可饱，安能逐鸱鸢。","局局禹迹里，里情向谁宣。"]},{"t":"严陵滩","f":"五言古诗","c":["咄咄严子陵，竟不能下尔。","迢迢富春山，潣潣桐江水。","渺渺穷居士，皇皇汉天子。","当年布衣交，一旦君臣礼。","渭川罢钓纶，莘野释耒耜。","上贤尊天瑞，所愿赞天纪。","但非鱼水会，往往委泥滓。","明王久不作，吾道长已矣。"]},{"t":"忆李御史云","f":"五言古诗","c":["忆昔在吴会，与子共昕夕。","剧谈例百壶，醉咤沧溟窄。","晨光倏不处，人事转凄恻。","予复苦羁旅，子已作逐客。","鄱阳波浪深，南岳瘴雾塞。","鸿冥天万里，帛书经岁得。","谁知消息来，竟作幽明隔。","冥契既永逝，今我何萧摵。","曩时青莲花，持抱化为石。","回首灵源山，云际且屏迹。"]},{"t":"故太傅于公谦","f":"五言古诗","c":["太傅出南方，眉宇天人表。","曩在英庙朝，谠论多了了。","三边正统末，兵戈日俶扰。","先皇巡朔方，敌骑伏潢沼。","黄云阨塞垣，仙仗迷周道。","法驾一蒙尘，作意索金宝。","京城既摇动，和议杂纷纠。","公时赞戎机，决策截澜倒。","告庙定储君，誓众守隍堡。","耀兵向阴山，直欲举征讨。","居庸扼咽喉，铁马岂得捣。","坐令敌计穷，食尽师遂老。","翠华果全归，黄屋免再造。","虽重获罪戾，社稷功非小。","功高反杀身，于古亦常有。","固由天威赫，实为青蝇挠。","天日终辉辉，即见是非瞭。","神衷启后圣，殊锡达幽眇。","忆昔靖康乱，谋国何草草。","堂堂宋诸良，唯唯遵和好。","甘心拜仇敌，所以至绝岛。","直书在史氏，公节须皦皦。"]},{"t":"赠方豪","f":"五言古诗","c":["昆山天下士，抗怀薄秋旻。","作诗接元白，开口奔鬼神。","狂来放厥词，妙得造化真。","习尚罕时好，结交必古人。","三年策仕版，八口还忧贫。","民俗日向浇，真欲回其淳。","尸名况疾恶，所以谗柄新。","邹阳固得谴，郑侨终见亲。","迷途堕老洫，谁辨玉与珉。","君看裳陵山，万古当嶙峋。"]},{"t":"须溪除日","f":"五言古诗","c":["兹夕乃何夕，忽忽岁云徂。","南征历寒温，犹滞天一隅。","去年阖闾城，今年姑蔑墟。","风尘久未厌，岂得念故都。","怀中两女儿，旦夕如长凫。","出门初学语，今能效屠苏。","团栾岂慰意，恻恻悲隙驹。","比邻数知旧，别后还有无。","爵服既不情，铅汞亦我诬。","九野天浩荡，奄奄正愁予。"]},{"t":"赠周用宾归江郎五首 其一","f":"五言古诗","c":["岧岧三神山，郁郁山上木。","丛株糁古雪，云际守幽独。","附枝中梁桷，匠石岂不欲。","寓形万仞冈，沆瀣空中浴。","其名曰冥灵，千春葆芳躅。","桂树亦葳蕤，乃有斧斤辱。"]},{"t":"赠周用宾归江郎五首 其二","f":"五言古诗","c":["衢阳何所有，江郎兀南陲。","云霞幻奇态，万古天为低。","飞鸟莫可上，人迹将焉为。","上有珠贝宫，神物光陆离。","吾将游其樊，薄言采玄芝。"]},{"t":"赠周用宾归江郎五首 其三","f":"五言古诗","c":["翩翩黄鹄鸟，顿足珠树林。","误入燕雀网，稻梁非宿心。","羽毛日摧颓，逝节已载阴。","终焉摩青天，高梧结珍禽。","秋风下木叶，各奏世外音。","凡鸟空嘈嘈，角鹰扇祸淫。","玄阴一解散，求友意何深。","风翮或相及，无忘寄幽襟。"]},{"t":"赠周用宾归江郎五首 其四","f":"五言古诗","c":["昔我归山中，敬访江郎石。","相逢草莽间，意气两测识。","电露无恒期，烟霞有真色。","黄泥天鸡没，感子何所适。","葛洪以丹砂，玄圣终沙碛。","通潜自天行，达者固无窒。","赠子白云篇，心知讵宜默。"]},{"t":"赠周用宾归江郎五首 其五","f":"五言古诗","c":["繁霜袭广野，怛怛失众芳。","送子不及远，岁晏令心伤。","结交岂在故，所贵旦暮遇。","曰余罹天韬，尚尔界觉路。","青山何逶迤，行子有所之。","异域雪霰盛，勿使白鹤疑。"]},{"t":"读李质庵稿","f":"五言古诗","c":["雅音失其传，作者随风移。","于楚有屈宋，汉则河梁词。","曹刘气轩轩，逸文振哀悲。","两晋一精工，六朝遂陵迟。","角然尚色泽，古风不成吹。","卢王号词伯，秪用绮丽为。","千年取正印，乃有陈拾遗。","或不尽反朴，朝代兼天资。","所以王李辈，向道识所期。","大哉杜少陵，苦心良在斯。","远游四十载，而况经险巇。","放之黄钟鸣，敛之珠玉辉。","幽之鬼神泣，明之雷雨垂。","变幻时百出，与古乃同归。","律诗自唐起，所尚句字奇。","末流亦叫噪，古意漫莫知。","历兹六十纪，识路良独稀。","凤鸟空中鸣，众禽反见嗤。","夜寒理危弦，恻恻赏心违。"]},{"t":"赠吾谨五首 其一","f":"五言古诗","c":["朅来潜元子，偃息苍云根。","怀姝三十祀，为亢遵世屯。","甸候翔虎貙，凤鸟乃孤鶱。","微荣曷足贵，所贵至道尊。","糠籺铸尧舜，水虎伏玄门。","岂同曲辕栎，遁天得长存。"]},{"t":"赠吾谨五首 其二","f":"五言古诗","c":["采兰荒江陬，繁芳被罗襦。","采采不自媚，征途爰有需。","征途何遥遥，波岭争洄纾。","宵旦判辰参，卒岁焉可图。","南州瘴雾塞，狨蹄下城隅。","永言守沉晦，去去宁君躯。"]},{"t":"赠吾谨五首 其三","f":"五言古诗","c":["南服有佳人，遗身在远道。","上衣云锦灿，下裳花萼绕。","容华耀朝曦，岁晏结芳草。","独行谁与娱，抱影心正捣。","岂无合欢被，附托苦不早。","楚璞思一献，和氏莫复保。","世无良蹇修，雌守以终老。"]},{"t":"赠吾谨五首 其四","f":"五言古诗","c":["麟为希旷祯，何以至鲁藩。","大道久丧世，麟趾在人间。","仲冬钜野风，犺獍乃高蹲。","合围不孑遗，灵物罹其樊。","虞人折尔足，眩尔貂与貆。","岂但子锄商，鱼视乃漫漫。","大鹏息南溟，培风会高抟。","纷纷枋榆鴳，安知九霄翰。"]},{"t":"赠吾谨五首 其五","f":"五言古诗","c":["京洛贵游子，结驷康庄衢。","前麾拥楚舞，后骖杂吴歈。","结交尽侯门，意气陵上都。","玉食豺虎侧，闇者适所趋。","宁知穷巷士，仄仄顿空庐。","冬裘不掩胫，夕粟无斗储。","阨抑曷足悲，主者顾乘除。","神奇化臭腐，荣盛可久居。","子云草玄地，千载名不渝。"]},{"t":"双剑篇赠毛汝厉","f":"五言古诗","c":["双剑在昆吾，淬砺良独劳。","年岁既已久，况兹以鹈膏。","丰城古狱下，闪闪星文高。","云逵一见收，结佩事游遨。","被以黄金鞘，系以赤玉绦。","霜锋按月窟，万里风雷号。","一剑乃弃置，埋照同铅刀。","岂不爱光霁，乖誃异所遭。","有时匣中吼，魑魅皆遁逃。","神物卒当合，世人那得操。","君看延平津，纠纠双龙交。"]},{"t":"岊江送汝厉二首 其一","f":"五言古诗","c":["漂漂海上萍，卒卒梁间燕。","与子结同心，何意异乡县。","游团散景光，谭讨猥深眷。","眷兹朱旻际，乃有此暌判。","川途何渺默，年运复流转。","岂无缱绻心，王事不可缓。","君当翔要津，我且守迍贱。","膏煎以自明，璞辱以自衒。","愿言沉光辉，勿使闇者见。"]},{"t":"岊江送汝厉二首 其二","f":"五言古诗","c":["西北日晼晼，宫观凝寒烟。","行子暮何之，驾言北之燕。","前骖结良驷，后徒控华旃。","中舆歌响发，楚声一何繁。","一阕远别离，再阕行路难。","蓟门无清尘，易水有急湍。","旷士怀明义，天步故多艰。","贱子甘自营，沦晦亦所欢。","乖期在昧旦，且复叙凉暄。","容辉无时及，表之英琅玕。"]},{"t":"南山一株松","f":"五言古诗","c":["南山一株松，衣被何婵嫣。","上焉绝云气，下者抵流泉。","季秋零露冱，百草乃弃捐。","修条抗回风，况结霜霰缘。","附托一得所，斤斧那得前。","所以保容华，阅岁及百千。","纷纷蜉居子，岂知有大年。"]},{"t":"答毛汝厉侍御","f":"五言古诗","c":["仲夏夜向短，忽忽不得寐。","所思眇天未，鸿雁冉而至。","佳人隔湘波，遗我云锦字。","开缄珠贝光，亹亹见深意。","绸缪梅剑言，噫譩胶漆地。","时危先金甲，儒服久沦弊。","感子情义重，难以笔舌记。","念昔在京师，邂逅意交质。","文章讵足传，偏爱无妒忌。","逢人说项斯，益见君子谊。","我生岂土木，啧啧赏风味。","顷来趣南方，骢马金络辔。","侁侁表干臣，赫赫天子使。","始识豸绣衣，已褫魑魅气。","如何驾鼓车，乃用此骐骥。","所幸日亲炙，慰我色憔悴。","公门数十寻，不见所深邃。","俯心下微贱，此辈一腾沸。","平生诗百篇，缮写入箧笥。","自愧交游间，何敢复当是。","鄙夫昧逢迎，动辄得詈戾。","遽意遁樵渔，横逆莽复炽。","非子善解排，何以控轩轾。","凝情外形骸，奋舌略荣利。","岂无英乂者，与我独投契。","朱炎射北林，樯乌荡离思。","恻恻芋原屺，悠悠岊江涘。","楼船忽复解，我马何当系。","江山一搔首，天地双挥泪。","君才万夫敌，伟矣瑚琏器。","富贵何可言，勋名会多事。","九域悲风尘，三垂更烽燧。","疏瓜莫华滋，短狐暗窥伺。","先帝在天灵，仗尔济颠踬。","桓桓裴晋公，彪炳于史氏。","王通虽铲采，恋阙心尚閟。","太平十二策，寂寥昔曾试。","持危良独难，避色信所致。","古今贤达士，用舍各行志。","赠子猛虎篇，高歌发欲竖。"]},{"t":"少谷山杂兴","f":"五言古诗","c":["輶车入城府，不染市道尘。","买山水部巷，石壁争嶙峋。","嘉果自四时，橘柚及枣榛。","树木更茷骪，梅竹逾精神。","茆亭覆石上，风月为主宾。","芸轩矮且陋，著书掩柴门。","褦襶非我朋，心知远见亲。","神閒多暇日，棋局见本真。","虽居赤县会，每结青山云。","鳞鳞十万家，刀锥忘夕昕。","兹山岂遥远，烟容自津津。","四郊愿宁谧，永作草茅臣。"]},{"t":"远离别","f":"五言古诗","c":["近别不顾家，朝往仍暮还。","远别不顾家，出门宁计年。","出门复入门，儿女相牵攀。","鸿鹄怀四方，岂受燕雀怜。","凉风动沙碛，剑歌惨不欢。","拔剑莫割水，怅此离别难。","同胞遍海岱，所贵天纲全。","孔圣欲居夷，老聃行度关。","意气苟相安，岂在华夷间。","远别即当别，怀土非上贤。"]},{"t":"白雀诗","f":"五言古诗","c":["有鸟曰嘉宾，结意公院深。","族类分总总，中有三珍禽。","毛羽白胜雪，哕哕吐奇音。","卑尊与贱贵，食宿明素心。","虞罗得之喜，言是世所琛。","饲以香稻粒，娇爱轻黄金。","置以白玉樊，鸷鸟不敢侵。","行将贡明主，上林逝骎骎。","小鸣天地白，大鸣彻古今。","化国汇振德，修能无滞淫。","类此蓬室士，怀美遵丘林。","一朝被爵命，照耀岩峦阴。","永言复自爱，野田有遗吟。"]},{"t":"威凤篇","f":"五言古诗","c":["景风布南服，晨曦射丹台。","威凤何契阔，千载一徘徊。","声响世不传，箫韶昔所谐。","虞庭既寂寞，岐下亦蒿莱。","孔雀与野鸟，朝代纷疑猜。","今时夫何如，天未鸣喈喈。","乃有抟牛䖟，附托凌太阶。","此曲不可竟，九土方喧豗。"]},{"t":"短歌行","f":"五言古诗","c":["跨马出郭门，马疾不俟鞭。","长跽挽君马，听我歌一言。","凉风戒芳树，白露凄寒蝉。","君子有所思，远游及幽燕。","在家人所爱，去家人所怜。","朝饔不及飧，岂得恋膝前。","下有黄口儿，上有沧浪天。","今时何清廉，尽室难远迁。","但见被云锦，麻枲无弃捐。","独行多辛苦，加餐以延年。"]},{"t":"寄惟可","f":"五言古诗","c":["褰裳采杜若，江水何瀰瀰。","借问采何为，将以遗君子。","人心无终极，天涯岂伊迩。","迅节易载阴，往事更佌俿。","时危生计拙，何以托疲薾。","桂枝有晚芳，芙蓉在秋水。","非无岁寒姿，亦逐江草萎。","栎社神所祥，永言葆玄理。"]},{"t":"寄顾九和侍讲","f":"五言古诗","c":["昔在吴子国，对君启心怀。","朝游太湖水，暮宿姑胥台。","狂吟各写志，醉倒黄金罍。","张衡赋四愁，王粲兴七哀。","同心而同调，一啸卑九垓。","翩翩海鹤举，飒飒天风来。","烟波忽相失，各在天一涯。","君为九霄翰，我似穷途埃。","音书阻岁年，泬㵳陇间梅。","亦有芳菲草，念子思悠哉。","迟暮不我顾，零落同蒿莱。"]},{"t":"送李道夫赴阙兼怀仲默","f":"五言古诗","c":["强敌且搆患，我友之朔方。","朔方万馀里，金门郁煌煌。","下有避世士，大隐而诞章。","十年风尘深，寂寞中省郎。","食禄侏儒下，修身思何长。","我有薜荔裳，因子远寄将。","一以存苦节，一以昭不忘。"]},{"t":"岁暮怀京华诸友","f":"五言古诗","c":["忧思苦不彻，岁暮登危岑。","关山百二重，江水渺且深。","水深亦有涉，山阻亦有临。","念我诸同袍，一息断风音。","君为天上凫，我为水中鱼。","飞潜自情性，安能识盈虚。","遥望北斗星，不见北斗城。","参辰俱在天，牛女亦分明。","同域而相避，何况异天地。"]},{"t":"游子篇","f":"五言古诗","c":["眷彼不周风，喟然思九夷。","九夷限波岭，游子逝何之。","驰车越幽蓟，天路逾险巇。","齐州岂不恋，严威剥人肌。","襜褕可禦冬，所欢不予贻。","在贱贵所忽，在远迩所遗。","子去华衣马，敦我忼慨词。"]},{"t":"赠道夫四首 其二","f":"五言古诗","c":["大道未底夷，回飙无时起。","君子思致身，小人亦踶踶。","结绥晨出门，长道从兹始。","马周一布衣，埋迹殊无似。","常何出片言，玄纁转跕躧。","一旦白板扉，光彩连州里。","拙哉孟浩然，非无圣天子。","平生得意句，濩落入泥滓。","咄咄归南山，悠悠谢朝市。","显晦无贤愚，自古靡不尔。","兰苕言永怀，忽逐春华萎。"]},{"t":"拟古","f":"五言古诗","c":["勋名不可图，叹彼时运乖。","佳人处幽谷，心思日如摧。","未旰柴门闭，盛年不克谐。","岂无合欢意，蹇修孰与媒。","霜闺云被寒，玉颜暗中颓。","翘首孤飞雁，雍雍令心哀。"]},{"t":"宿石竹岩","f":"五言古诗","c":["寝痾坐情累，削迹离故家。","届兹仲如月，气候清且嘉。","迢迢紫云洞，渺渺天一涯。","寻壑滞瀑流，攀岑悟灵芽。","千峰递生态，百草互吐葩。","周览荡节物，况乃凌紫霞。","神仙彷佛遇，导我营丹砂。","丹砂未易营，缁鬓早已华。","神理寓隐颐，时变增感嗟。","至人有逸念，存形非所多。"]},{"t":"王右军","f":"五言律诗","c":["右军鸾凤姿，初龀寓隆想。","沉睡乃真觉，坦卧亦疏朗。","临池洒妙翰，抗意风云上。","笼鹅事偶然，草经有攸往。"]},{"t":"草堂大风雨彻夜怀田家","f":"五言古诗","c":["旱魃自首夏，今兹山吐云。","翛然草堂前，彷佛气候新。","迅雷殷霹雳，积阳乃沉沦。","振风䬃而至，涷雨犹倾盆。","中夜想抱被，寒燠忽尔分。","回思前几宵，始得一爽神。","平明窥少谷，生意复津津。","乃有枣与榴，落地纷成囷。","缅惟收敛毕，农务仍苦辛。","造物讵可测，且幸苏劳筋。","阴阳未顺序，吾忧尚无垠。"]},{"t":"出自郭北门行","f":"五言古诗","c":["出自郭北门，松柏何缤缤。","白日不到地，野草悲阳春。","仰观苦雾繁，俯盼白骨新。","白骨火不化，髑髅夜相宾。","飙风啸有恨，大暮难再晨。","昔为嚣市子，今作广野尘。","昔竞刀锥微，今托鸱鸢亲。","玄运乃如此，彼苍岂遗仁。","蒙庄达生死，缅邈烦恼津。"]},{"t":"孚斋","f":"五言古诗","c":["成心绣鞶帨，偾骄不可拘。","脊脊广运中，吾道其何如。","罝罘乱薮泽，太素成蘧除。","畸人乘莽眇，焦火蹈若无。","汎然涉九渊，木舟一何虚。","得一合众万，瞻阕生明疏。","至情通喘耎，而况孚豚鱼。","斋居霁烦想，兹理守弗渝。","说巽苟不亏，化邦扩所馀。","眷言永登假，去与天为徒。"]},{"t":"游建州陶园和渊明拟古八首 其一","f":"五言古诗","c":["南服翔燠风，杪秋犹春和。","水乾坐濡滞，木舟载悲歌。","名园占原隰，节物逝已多。","峥嵘甘菊丛，绰约芙蓉花。","流景瞻应接，腼尔怀阴何。"]},{"t":"游建州陶园和渊明拟古八首 其二","f":"五言古诗","c":["少小秉末尚，担簦远行游。","如闻赤县外，更复有八州。","车辙苦未厌，光景倏若流。","归来守纯气，蘧然见丹丘。","乃知不出门，偃仰六合周。","王风久寂寞，吾行将奚求。"]},{"t":"游建州陶园和渊明拟古八首 其三","f":"五言古诗","c":["四序递兴没，万有乘始终。","景阳未停轨，积阴已肃戎。","何意松柏条，蔚然乃独雄。","糜糜田间草，淅淅草上风。","凛秋一披拂，姣好会有穷。","迟尔采脂苓，服食青山中。"]},{"t":"游建州陶园和渊明拟古八首 其四","f":"五言古诗","c":["群山积莽苍，莽苍当座隅。","万木忻适所，境幽郁以舒。","细雾宿阴洞，丛菉亭广庐。","东山抱远志，栗里赋閒居。","浮荣曷足縻，三径不可芜。","岁华日向晚，吾道乃晏如。"]},{"t":"游建州陶园和渊明拟古八首 其五","f":"五言古诗","c":["东南有一士，名节贞自完。","葆光归田园，散发懒不冠。","白鱼入羞馔，取色慈母颜。","幽居藏市廛，白日以闭关。","客从远方至，情话忧绝端。","酒酣命僮仆，取琴为之弹。","希声入窈眇，忽下双紫鸾。","眷言履昭旷，相期逾岁寒。"]},{"t":"游建州陶园和渊明拟古八首 其六","f":"五言古诗","c":["秋登黄华山，恍然见大荒。","前有乐天居，后有归来堂。","堂居厂云鸟，回池亦淼茫。","主人端逸念，莳菊翳坻场。","天寒菊未华，逸念齐嵩邙。","桴汎通永夕，万象争低昂。","情景苟不亏，余何动迷方。","缅惟无穷门，引领情内伤。"]},{"t":"游建州陶园和渊明拟古八首 其七","f":"五言古诗","c":["我行复中野，怛怛自今兹。","蹭蹬勿重陈，所伤命与时。","非无青霞质，素衣向已缁。","侧闻雍门弹，慰此中忧疑。","忧疑卒未解，至音已无辞。","古风落冥冥，大道不可思。","王乔非予愿，詹尹亦我欺。","江花莽消息，游子暮何之。","相逢东园公，遗我考槃诗。"]},{"t":"游建州陶园和渊明拟古八首 其八","f":"五言古诗","c":["楚江有杜蘅，叶短不堪采。","越山有舜华，秀色昏旦改。","不如撷芙蓉，远意薄云海。","美人隔秋波，秋容澹相待。","悠悠鹖冠子，遁世岂有悔。"]},{"t":"北雁步云词","f":"五言古诗","c":["昔我梦翼飞，去与王子亲。","双双鸾凤箫，吹破缑山云。","翻身大火坑，洗髓明河津。","芔然驭白鹿，下宴瑶池春。","枉驾雁宕阴，玄冥闭天阍。","醉扫千文石，万劫留至文。","只今灵峰洞，元气犹氤氲。","悲歌草木偃，坐啸天地闻。","归来铲光彩，大隐金马门。","君看东方生，至人伏垢氛。","讵罗不了道，一壑空云云。"]},{"t":"业书楼","f":"五言古诗","c":["台南有高楼，下瞰澄江水。","飞甍冒流云，疏棂一何美。","重帏无长物，三车拥图史。","中有伟丈夫，云是百世士。","连翻十二经，呾尔荡其滓。","翻罢三叹息，回首鸿濛里。","乃知无物初，万轴皆糠秕。","青藜宵到门，欲语馀一指。","目击道自存，我爱温伯子。"]},{"t":"北山诗二首 其一","f":"五言古诗","c":["朝发委羽阳，暮赴紫霄期。","南游岁向晚，恋此溪山奇。","终风豁初霁，阴谷雪已晞。","振策陟曾曲，薾然见茅茨。","疏凿信未伦，情景殊匪亏。","新松会多翠，远江亦不迷。","素月明当中，坐久生灵台。","少焉寒威重，尚觉阳气微。","良朋矢为好，兹生幸未衰。","本性苟可遂，毁车去何疑。"]},{"t":"北山诗二首 其二","f":"五言古诗","c":["东行寓游踪，逸轨迷西还。","矧兹玄冥月，翳翳风景昏。","非无儿女怀，所适山海观。","阳崖冒远陂，阴壑注奔湍。","步云青峰顶，搜括穷其源。","前有空明洞，茑径回岩峦。","驾言采玉华，将以遗所欢。","翛然云霰集，置身虚无间。","大道出死生，静者见腑肝。","愿招柱下史，去入无穷门。"]},{"t":"燕集玉辉堂","f":"古风","c":["窈窈岩壑姿，迢迢契幽赜。","缅怀天台胜，遂寄山水癖。","赤城淹岁晏，所恋有三益。","壮阴屈微阳，关山雪盈尺。","虽嗟轨路阻，稍喜缁尘息。","巾峰入草堂，天葩进瘆?。","美人罗公车，求友意何极。","文筵丽奇态，流觥乐无斁。","鹿鸣纷谐和，造适非丝革。","退念蒹与葭，兹幸附圭璧。","睹空悟气机，体有见真色。","吾道未榛芜，辴然露胸臆。"]},{"t":"送何仲默游关中六首 其一","f":"五言古诗","c":["跨马出蓟门，马行不旋顾。","丈夫重高勋，狭径有矩步。","狭径非所遵，将子恐岁暮。","多财乃善贾，长袖乃善舞。","巍巍西昆丘，矫首以延伫。"]},{"t":"送何仲默游关中六首 其二","f":"五言古诗","c":["延伫如奈何，离居生怨惜。","输心风雨夕，执手衢路侧。","神交无古今，长道有羽翮。","晤言念弥久，去去结松柏。","女萝乘飘风，眷此中乖绝。"]},{"t":"送何仲默游关中六首 其三","f":"五言古诗","c":["弱齿逃篇翰，中逵谢华藻。","深文用情性，鞶帨日已扫。","箫韶奏虞庭，凤凰出琼岛。","至音动天地，和者一何寡。","永言承德辉，别尔乃草草。"]},{"t":"送何仲默游关中六首 其四","f":"五言古诗","c":["登高望咸都，送子过易水。","朔风何萧萧，黄鹄逝未已。","肴函列百牢，泾渭亘千里。","西当太白窟，代有隐君子。","长孺用高义，壶遂且远举。","古道存遗编，眷尔托经始。"]},{"t":"送何仲默游关中六首 其五","f":"五言古诗","c":["崦嵫下西日，翳翳风景昏。","虎豹扼九关，广利那复闻。","重华不可晤，圣智乃沈沦。","鸱鸢日连类，鹓雏遁其群。","矢言引高步，行止遵时屯。"]},{"t":"送何仲默游关中六首 其六","f":"五言古诗","c":["杪秋行终南，箭括高刺天。","黄河从天下，列宿相勾连。","何意紫极北，狼嘴张其躔。","南开蚕丛山，北俯邙与廛。","广野阒无人，草生郁芊芊。","尘飞苦无象，谷变会有然。","行哉殖元气，皇图寿万年。"]},{"t":"武穆吟三首 其一","f":"五言古诗","c":["南瞻岳王坟，拊心讼宣和。","四海既无虞，乐事一何多。","师师入帝侧，金兵乃星罗。","旧时张谏议，天阍语非讹。","但见户括金，不见士荷戈。","回首靖康末，志士悲如何。"]},{"t":"武穆吟三首 其二","f":"五言古诗","c":["太尉出世姿，用兵自神武。","怀中左氏传，羞与绛灌伍。","燕云唾手得，甲卒尽熊虎。","北开玄冥天，南靖朱光土。","国耻犹未雪，百胜曷足数。","誓将与诸君，痛饮黄龙府。","不观颍昌旗，气已吞边部。"]},{"t":"武穆吟三首 其三","f":"五言古诗","c":["英雄无奈何，气数乘人事。","宋德但末光，椒房生梦寐。","北狩不可返，上天有成意。","壮士自苦心，奸臣自长计。","蜡书晨到门，将星夜堕地。","平生四字符，竟落气数里。","桓桓蜀武侯，杀身志乃已。"]},{"t":"佳人篇","f":"五言古诗","c":["青青壖畔蕉，粲粲空谷女。","头上金错钗，宛宛鸾凤舞。","腰间碧玉佩，娟娟下兰庑。","言采草中英，不践草上露。","新制齐纨扇，自障复自顾。","非无合欢被，防身密如堵。","飘风吹杨花，夫君渺何许。","长恐时易沉，裁悲以延伫。"]},{"t":"赠吕爱员外","f":"五言古诗","c":["秋云会崇台，观子意弥远。","新知何草草，半饟迭酬劝。","同生不尽欢，异世乃增恋。","真交重意气，岂必日缱绻。","丛菊有远芳，女萝有深蔓。","大道沦沧溟，相期汎波澜。"]},{"t":"芳树篇二首 其一","f":"五言古诗","c":["芳树生广除，苍苍正轮囷。","芳树不自芳，拂拂千紫宸。","朔风吹树巅，素雪舒其神。","今日曷不乐，公堂有嘉宾。","把酒对兰楹，欢来不能陈。","微言托哀竹，惠心款以伸。"]},{"t":"芳树篇二首 其二","f":"五言古诗","c":["吾皇嗣历服，神武古绝伦。","拔剑下大荒，裔夷率来臣。","大食献宝刀，大宛献麒麟。","单于独犯顺，戎衣不及晨。","军声动地起，旦日至西秦。","分金赐五侯，卫霍不爱身。","万国拜稽首，三祝何谆谆。","但令修文德，王度永无愆。"]},{"t":"早起赴思道索饭","f":"五言古诗","c":["晨朝不举火，去扣故人门。","坐见相忘意，终衔一饭恩。","酝谋苏轼妇，蔬摘长卿园。","童稚能看客，文章不讳言。","粗豪吾岂敢，道谊尔应存。","陶令时独往，杜陵岁七奔。","从来略温饱，以此信乾坤。","万事羁孤极，元凭好弟昆。"]},{"t":"苏蕙娘织锦七解","f":"五言古诗","c":["扶风苏蕙娘，织锦不下堂。","朝朝理机杼，字字回肝肠。","织就远寄将，夫婿在襄阳。","夫婿别有欢，置妾长门旁。","新爱正纠结，旧恩一时忘。","仰看天上星，环转如车轮。","经纬自有度，卑尊岂无伦。","凭妾手中梭，愬妾心上棼。","纵横八百字，反覆合成言。","妾心方悔悟，君心傥回旋。","苍蝇点素缟，嫉妒无愧好。","忆昔君别妾，人事何草草。","君逐阳台云，一去断音耗。","妾似芙蓉花，芳妍向谁道。","朝云歌未已，陇水鸣不止。","愿作青陵台，同生复同死。","琉璃易破折，纨扇轻一掷。","生前参避辰，死后致魂魄。","白头且莫宣，红颜多弃捐。","安得窦连波，解妾回文篇。"]},{"t":"赠汪希周","f":"五言古诗","c":["朔风吹岁花，之子意嵂屼。","矧兹日初度，乃值履长月。","宾筵击朱弦，调急新商发。","君才当雄飞，一举偃溟渤。","培风向天池，九万岂天阏。","终焉到彼岸，去去忘其筏。","北辰久未安，欃枪耀双阙。","眷尔弧矢志，翻身射星孛。","大业犹次且，誓言共黄发。"]},{"t":"妾薄命","f":"五言古诗","c":["翩翩并命鸟，步步相谐悦。","中道忽分散，鸣诉哀以切。","有生谅同欢，有死愿同穴。","众雏羽翼短，讵忍两诀绝。","兰芳不如桂，荼苦不如檗。","妾身未能亡，恶此中衰歇。","双星下洞房，流景何光洁。","照见君衣裳，不见君颜色。","重泉眷有期，海水亦有竭。","巍巍苍梧山，竹泪无时灭。"]},{"t":"燕歌","f":"五言古诗","c":["云鸿下雀罗，越客变燕歌。","燕歌声激烈，越客悲奈何。","长歌剑斫地，短歌发直竖。","朔风吹易水，四座俱陨泪。","少年羞睚眦，壮士重意气。","拔剑杀仇家，生死无顾忌。","猛虎欲攫人，不择愚与贤。","食胆中自知，岂避猛虎前。","出门远孤征，雄剑终夜鸣。","窜身脱芦下，亡命入幽并。","幽并多豪侠，结交踰平生。","杯酒接然诺，信义何分明。","白日高渐离，筑声怆以怦。","田光为君起，片语谋立成。","荆卿独忼慨，舞阳乃辅行。","上马报仇去，土花照青冥。","秦庭事一就，干载扬令名。"]},{"t":"游侠篇","f":"五言古诗","c":["长安逢少年，意气何昂昂。","鸣鞭六陵坂，先驱势正强。","戒途列万骑，一一羽林郎。","铙吹动地来，飒沓若云翔。","面前五花骢，宝絷金丝缰。","腰间双龙剑，吴钩饰英璜。","弄儿十四五，藉绮凝素光。","行行且游猎，游猎及上阳。","张弧向大漠，忽坠双飞鸧。","持归平乐宴，象筵欢未央。","借问此何谁，云是汉金张。","六年起卒伍，一日倾侯王。","文人天帝子，出入乘金阊。","扬声重纶綍，流燄烁朝堂。","逆鳞不可婴，太阿手所将。","乃知朱门贵，溢恩胡可量。"]},{"t":"沱水三章 其一","f":"五言古诗","c":["仙人骑白豻，远在苍梧山。","我欲往从之，沱水深以澜。","沱水深可厉，苍梧郁巑岏。"]},{"t":"沱水三章 其二","f":"五言绝句","c":["云门何皇皇，远在洞庭岸。","我非沱上凫，日夜汎波澜。"]},{"t":"沱水三章 其三","f":"五言绝句","c":["言采蘼芜草，思心倏如摧。","不见王孙归，但见章华台。"]},{"t":"同心结三章送林德敷赴齐东 其一","f":"五言律诗","c":["文旗出郭门，念子赴齐东。","揽衣起踯躅，叹息不得同。","凤麟久增逝，爰居亦避风。","冥运方险艰，去去随短蓬。"]},{"t":"同心结三章送林德敷赴齐东 其二","f":"五言律诗","c":["短蓬逐晨风，转徙无滞淫。","我其鸿与燕，乖坼一何深。","云台志莫就，奄忽昔与今。","平生广陵散，写此岁暮心。"]},{"t":"同心结三章送林德敷赴齐东 其三","f":"五言律诗","c":["岁暮心匪夷，哀弦久断绝。","与子不殊调，胡忍相诀别。","临淄锦绮场，子去守饥渴。","愿保金石志，慰我肠百结。"]},{"t":"五子二首 其一","f":"五言古诗","c":["曹王振大雅，抗怀逐游龙。","江马亦决骤，连翩乘上风。","汪生何慷慨，接响苍云中。","京洛五凤翔，矫然下梧桐。","和鸣正以则，至音激黄宫。","叔世竞蝉聒，置尔荆棘丛。","上林逝若脱，遐趾随断蓬。","素丝易以染，姣女难为容。","行矣敛华饰，达人有深衷。"]},{"t":"五子二首 其二","f":"五言古诗","c":["太山五株松，冬夏恒苍苍。","凉风旦夕劲，声闻一何长。","声闻曷足贵，所贵蒙雪霜。","东封翳隆爵，俛首以徬徨。","何言帡幪勋，乃见斤斧伤。","苍颜日摧颓，卒岁增慨慷。","但令本根固，繁条会有强。","依依女萝草，永言附遗芳。"]},{"t":"安期生","f":"五言古诗","c":["人言千岁公，昔在阜乡亭。","卖药青海上，徒闻千岁名。","双留赤玉舄，珍重报秦庭。","东指蓬莱顶，风波连紫冥。","河津不可渡，谁识安期生。"]},{"t":"我昔远行迈","f":"五言古诗","c":["我昔远行迈，飘飖度溟渤。","洪波浩漫漫，东下遍穷发。","蓬山彷佛见，鳌足互兴没。","回瞻赤霞城，照耀金银阙。","道逢五行仙，姣好若冰雪。","璘璘白鹤车，翩翩逐云月。","导我探鱼肠，乃得餐玉诀。","入山采黄芽，和之以璚屑。","服食引奇龄，秘诀不敢泄。","敛衽入怀抱，三载字未灭。","归来历故都，不复见物色。","回首望徽音，徽音已断绝。","桃花源不昧，去矣忘其筏。"]},{"t":"兰陵赠王诞敷使君","f":"五言古诗","c":["何处见君子，兰陵西上门。","坐看苍翠色，蔚蔚照熊幡。","尔本蜀中彦，才如横海鲲。","余方闽地隐，梦逐故山猿。","郁彼风云志，潸然廊庙言。","并收弘治籍，惟恋孝陵恩。","汉主亲戎阵，书生俎豆存。","迢迢去住意，一与醉芳樽。"]},{"t":"游张公洞二首 其一","f":"五言古诗","c":["阮籍怀广途，卢敖历四极。","尚惭壤虫隘，或哭周道阨。","伊余抱末衷，乃溯二子迹。","北游费岁年，东归眷幽赜。","岂不念穷路，黄鹄有羽翮。","阳羡山水区，西奠洞庭侧。","岩扉靡杂卉，菌芝类盈尺。","昔有摄生者，于此炼金液。","空筌夙所慕，灵洞杳莫测。","寒泉滴不散，千岁成璆碧。","中有科斗书，漫灭不可识。","朅来事冥探，宛若藐姑射。","岂伊耳目娱，但恐霜露迫。","缅思缟凤吹，傥值紫髯客。","修观竟十二，累果及八百。","深功谅难期，所志未忍息。","永服先圣训，至诚裂金石。"]},{"t":"游张公洞二首 其二","f":"五言古诗","c":["乘槎阳羡湖，延览铜官山。","山气何氤氲，飞崖郁而盘。","西南有乳窟，窈窕青云关。","倏忽启灵秘，传闻赤符间。","七日混沌死，鬼凿永不刊。","神窍通十洲，清浅呈琅玕。","玄阴伏其下，六月冰雪寒。","仙鼠与石燕，倒挂风雷坛。","仙人度羽去，尚留九成丹。","爰有好事者，里粮澹忘还。","冥搜了无得，怅然回波澜。","余亦采芝徒，九载勤登攀。","九载在旦夕，皓发凌朱颜。","尚子既毕娶，坡翁复营田。","至人贵遗形，细故恶足牵。"]},{"t":"与原侍御郑地曹游虎丘","f":"五言古诗","c":["祝融气已深，行云丽晴晖。","霜台早见招，骢马来騑騑。","升高目不极，望远神欲飞。","南风起木末，吹我芰荷衣。","把酒白莲池，长谈暮忘归。","白日无却顾，浮云纷是非。","麟凤在羁靮，心事殊多违。","何当晤生公，参破区中机。"]},{"t":"汎舟五曲谒武夷精舍","f":"五言古诗","c":["朝汎碧浪溪，夕宿隐屏下。","洄湍激九折，淜洑以东注。","丹厓写灵奇，怪者莫可悟。","岂伊神理秘，谅有鬼物护。","仙术非荒唐，宣圣有矩步。","㴑流无穷门，直以夫子故。","依违尚友心，謇謇恐迟暮。","终当据昭旷，眷此结桂树。"]},{"t":"龙溪","f":"五言古诗","c":["志士乐岩栖，岩前幽鸟啼。","长风吹瀑布，飞过白龙溪。","抵道桃花发，花源处处迷。"]},{"t":"古愁二解","f":"五言律诗","c":["出门采棠花，风吹陇山木。","陇山未可行，荆棘伤我足。","陇山高以临，陇水阻而深。","不畏伤我足，但恐伤人心。"]},{"t":"偶书","f":"五言古诗","c":["神龙栖九渊，志在天汉表。","终始养神德，用九仍初九。","安能逐蛙蠙，泥蟠东西沼。"]},{"t":"志士篇","f":"五言古诗","c":["河伯誇秋水，未知东海深。","众人尚雷同，安识志士心。","志士有苦心，心苦道自舒。","上山思采玉，入海贵探珠。","至宝非外假，真诠岂予诬。","独行何凉凉，阔遵溯周衢。","虽无凌风翰，眷此适国都。","升天而游雾，惕哉子大夫。"]},{"t":"杨白华","f":"五言古诗","c":["袅袅长杨树，青青垂白花。","杨花揽不住，春色若为斜。","如何宫畔草，萋郁遍天涯。"]},{"t":"边人曲","f":"五言古诗","c":["结发事远征，能知边塞情。","长骑汗血马，调戏郅支营。","大小七十战，金鼓夜自鸣。","稽首两贤王，大开受降城。","匈奴不可敌，剑声讵能平。","终生独忼慨，抗言请长缨。"]},{"t":"渡峡","f":"五言古诗","c":["凛秋行日夜，短别去故里。","眷此有所思，陟山复临水。","重峡亘天堑，下足顿逸轨。","回飙激伏澜，绝流渡濛汜。","西崦积瞑色，翳翳敛夕靡。","所忧风波集，击楫志未已。","至人乘虚无，君子虑终始。","蹈险乃真见，履顺有灭趾。","矢言涉大川，勿负横江耻。"]},{"t":"游石竺岩","f":"五言古诗","c":["少抱烟霞资，雅志向林壑。","出门混世尘，中逵反堕落。","闻道岂不早，优游岁将迫。","言就巫咸问，敬访何氏宅。","石竺敞灵界，紫云冒岩箔。","匪梦复匪幻，乃见鹤上客。","长跪诉悃诚，曰予动迷错。","授我灵光剑，斩断妖魔色。","朅来无穷门，灏灏见天德。","接手浮丘老，感恩讵云薄。","乘云凌高丘，永与世寰隔。"]},{"t":"题集山书院","f":"五言古诗","c":["大江贯蕲黄，中有硕士居。","抱璧重一掷，探元破群愚。","偃卧大集阳，悠然见苍梧。","鲁峰七十二，芙蓉峻而都。","所恋得依托，宁能去园庐。","众山止其巅，百川求其潴。","不观洞庭阔，但恐周道纡。","白鹿有筌蹄，衡岳空笱篘。","玄玄入疑始，吾与尔为徒。"]},{"t":"黄山杂诗十首 其二","f":"五言律诗","c":["燠风熙自南，淑景变物色。","引领望岩阜，光宠遍林薄。","抚兹盛农节，耦耕及南陌。","虽匪康庄衢，良用歌帝德。"]},{"t":"黄山杂诗十首 其三","f":"五言律诗","c":["经始朗上原，秬菽长如茨。","岩霏散丛薄，谷风回春姿。","童伴歌以嬉，苦乐中自知。","宁生声慷慨，乃作霸王师。"]},{"t":"黄山杂诗十首 其六","f":"五言律诗","c":["回溪下钓缗，溪水见我志。","绪风扬伏波，波伏风不起。","中有双文鱼，筛筛不受饵。","履兹钓鲸鲵，掊击东溟水。"]},{"t":"黄山杂诗十首 其八","f":"五言律诗","c":["朱滩流湍水，壑龙无时吟。","水流木叶下，宛转岁序阴。","岁序倏以改，丹砂仍费寻。","蓬阁傥可求，去矣极高深。"]},{"t":"黄山杂诗十首 其九","f":"五言律诗","c":["崇峦互经亘，灵氛厂玄盖。","天风散鼓钟，旦夕发清籁。","日晏紫芝茁，山静幽鸟萃。","真机秘心赏，要在达者会。"]},{"t":"黄山杂诗十首 其十","f":"五言律诗","c":["停云扃重关，萝风陨天声。","遐搆名山阳，允谐真隐情。","诗书豁俗韵，岩丘湛性灵。","郁彼漆园篇，聊用得吾生。"]},{"t":"谒紫阳精舍","f":"五言古诗","c":["奇游历四穷，兹山负灵胜。","翠川玉篆绕，丹巘璚花并。","浮桴临星源，仙踪焕云柄。","图经宛不爽，神理杳莫竟。","缅讶开物初，岂无稽天浸。","怀山谷就变，赴坎槎交迸。","迹奇易赞扬，岁深改观听。","朅来幔亭宴，渺渺论神圣。","谅同武陵源，去为嬴民病。","梵蜕昔所诽，真函此须正。","所以紫阳翁，不履黄庭径。","远瞩悟气机，内照见真性。","永持哲士诫，修身俟元命。"]},{"t":"雪晴登阖闾城","f":"五言古诗","c":["屯车阖闾城，北风吹我缨。","残雪辉远山，牛羊缩郊坰。","四望靖氛祲，何以烽火明。","荆豫复梗化，巴渝未休兵。","东方乱新定，讵可言太平。","淮蔡连齐梁，繁华转凋零。","新鬼夜群啸，贪攘日相乘。","阛阓少人烟，狐兔行其庭。","向来膏腴地，眼见白草生。","白草何田田，不足饱蝗螟。","县吏尚夏楚，馀民死诛征。","我生夫何为，罹此百忧并。","拔剑出故里，捧心向明廷。","八月过沛水，长路愁榛荆。","宵雨恻野哭，晨风起鸡声。","空日积悲愤，岂不怀志诚。","承乏下三吴，伏枕惟独醒。","遭逢想马周，■然惭匡衡。","客从北方来，因之问神京。","狸鼪宣慢慆，凤麟多自屏。","荃蕙委厥美，艾榝朝盈盈。","语罢各掩涕，使我心逾怦。","捐佩遗故人，答我非众馨。","媒拙终受诒，好修谁共成。","吴侬亦有谣，辛酸不忍听。","东门有瓜场，予亦将归耕。","迟迟俗士驾，望望灵修情。"]},{"t":"子夜歌三首 其一","f":"五言绝句","c":["梅花在岭南，侬欢在山东。","梅花欢所爱，不得附冥鸿。"]},{"t":"子夜歌三首 其二","f":"五言绝句","c":["客从海上来，遗我双鲛绡。","鲛绡是何物，留此比璚瑶。"]},{"t":"子夜歌三首 其三","f":"五言绝句","c":["山有并命鸟，关关感人心。","中夜有所思，澄江不如深。"]},{"t":"岁晏行","f":"五言古诗","c":["终风薄旅衣，游子行天涯。","天涯行不息，岁晏有远悲。","出入盗贼间，进退昧所之。","休驾入彭城，身在犹惊疑。","问舍得所安，聊慰儿女嗤。","故人皆鲍叔，眷我情委蛇。","论文具鸡黍，旬日以为期。","驾言东问津，相送洪水湄。","中原且多难，伊人复生离。","握手写肝胆，我舟行且维。","感此绨袍恩，有心终酬知。","但恐丧乱后，会晤无定时。","努力将奈何，惟有长相思。"]},{"t":"湖上","f":"五言古诗","c":["太湖何潋滟，岁晏亦自好。","长风西南吹，天水共皓皓。","遥峰七十二，恍恍红云岛。","洞天在空濛，流水隔烦恼。","昔有绿毛翁，于此采玄草。","至今白石床，风云为持保。","闻兹生古心，携舻事幽讨。","良朋既同调，远客亦倾倒。","鼓桡乘鼋鼍，凌波撷蘋藻。","汎汎景将入，默默意未了。","方壶不可问，沧海恨无早。","归循去时路，木尽乾坤老。"]},{"t":"罗浮四百峰赠湛甘泉编修还岭南","f":"五言古诗","c":["罗浮四百峰，屴崱连青旻。","中有甘泉子，头戴玉台巾。","伏火烧丹砂，趺坐三千春。","下悯世溷浊，飞舄京华尘。","西历太行山，北渡长淮津。","疮痍满道路，此意长谆谆。","回思葛稚川，眷言慰所亲。","倾盖姑苏阳，探春五湖滨。","更欲折梅花，持以遗远人。","相从不可得，独步采江蘋。"]},{"t":"游天平侯思道不至","f":"五言古诗","c":["晓起发吴门，遥望天平山。","秋风吹松涛，入我衫袖寒。","白云无朝暮，好鸟声关关。","良朋期不来，独游心无欢。","驾言问名泉，高兴犹未阑。","山僧导我入，桂树聊跻攀。","我眼日已饱，我身殊未閒。","平生抱丘壑，三十驱尘凡。","尚恐豺虎剧，不敢缘其端。","愿从华阳君，五岳时往还。"]},{"t":"居杭旬月迟王员外不克先赴闽州","f":"古风","c":["昔我违京师，秋月始生魄。","今我离越鄙，冻雪迷广莫。","良晤无久期，达节守驹隙。","与子同?波，复作中路拆。","上天黑猿啸，下水白蜃斥。","如何临岁晚，乃尔事行役。","寒日下荒芜，云林正萧槭。","樯乌旦暮转，遂有川涂隔。","悠悠泬寥天，切切风雨夕。","神交谅不爽，万里日亲炙。"]},{"t":"梦戴寅仲二首 其一","f":"五言古诗","c":["之子不可作，壶公无春姿。","毗陵江水深，游魂归未归。","风波闄汝东，虎豹咆汝西。","北走限冰雪，南征多蝮蛇。","年少死道路，斯人更流离。","何以入我梦，明我长相思。","万壑真淼茫，三泉苦隇䧅。","天高猿鹤冷，尚有钟山疑。"]},{"t":"梦戴寅仲二首 其二","f":"五言古诗","c":["交游满江汉，谁复更如子。","读书京华尘，相看忍羁旅。","诉心风雨夕，潦草各别去。","云胡大宛种，一蹶千里路。","朝陟洞庭山，山远不可处。","暮航太湖水，水阔不可渡。","精灵复何为，白璧已黄土。","落月哀杜鹃，切切复延伫。"]},{"t":"寄思道二首 其一","f":"五言古诗","c":["中岁倦六籍，出门事远游。","远游于何之，五岳还三洲。","一雁云中鸣，诉诉如有求。","芒鞋岁月晏，得垒东海头。","谈文竟晨夕，亦足销吾忧。","相期每自励，志决天河流。","阨运当奈何，捷径不可由。","凤鸟化枭鸱，累乎行当休。","南湖烟水阔，去去狎白鸥。","失得勿复道，上溯多前修。"]},{"t":"寄思道二首 其二","f":"五言古诗","c":["阑云翳日景，埃风起拔木。","我前驼白狐，我后举黄鹄。","我生值巇崄，行止不可卜。","椒兰掷道傍，菉薋以为馥。","楚璞胡为尔，和氏刖其足。","祗修防二兵，古道何时复。","将子田商阴，商阴有黄角。"]},{"t":"虎丘与近夫太初同游","f":"五言古诗","c":["余幼寡好尚，所求在岩峦。","青鞋白接䍦，濩落三吴间。","良朋偶云集，结我以岁寒。","殷郎自东海，孙子自函关。","霜月明枫江，驾言虎丘山。","归云拥绝阁，下视空尘寰。","腾身慕黄鹤，延年愁金丹。","愿言事支遁，孟浪烟霞端。"]},{"t":"悼志","f":"五言古诗","c":["豺狼立道周，行旅限东西。","我生理酸楚，岁暮犹麻衣。","尽室出故里，生涯多差池。","莱妻对我啼，稚子日受饥。","形容饱风雪，摧折非平时。","世事就浇凉，吾道将安之。","三韩在何处，黄金不可为。","焉能有羽翰，飘去从安期。"]},{"t":"役役","f":"五言古诗","c":["役役不自息，旦夕白发新。","众非纷往来，谁能超世尘。","早年失所依，迷误三十春。","读书不闻道，空负见在身。","伯夷北之海，宣父西问津。","行藏各有以，予将希其伦。","青袍岂心事，白云终我邻。","罢官亦何难，去去完吾真。"]},{"t":"陪王中丞夜游治平期到上方不果","f":"五言古诗","c":["湖上兴不极，复治东山具。","执策入治平，繁霜湿衣屦。","山僧不好客，高卧阖庭户。","清商动木末，静听不知处。","遥看上方胜，子夜发襟素。","情长事乃违，咫尺不得据。","月落空归来，寒猿挂深树。"]},{"t":"吊古战场","f":"五言古诗","c":["昧爽发汾水，崇朝经白沟。","茫茫古战场，四时天为秋。","断魄化腐草，精灵化寒飕。","英雄不可招，世事如东流。","惟有战士骨，万古无人收。","依依野草黄，恻恻行人愁。","行人愁未已，四海方戈矛。"]},{"t":"谒李延平书院","f":"五言古诗","c":["绿槐夹青山，中有古书屋。","行舟剑水濆，弭棹叩芳躅。","长风薄衣巾，六月无三伏。","先生万古心，一旦付云谷。","通来四百年，民用如菽粟。","溪山发幽想，吾志尚鸿鹄。","下有清泠泉，一饮成三斛。"]},{"t":"石湖夜泊怀近夫思道二同志","f":"五言古诗","c":["移舟石湖路，敬访石湖水。","湖光上衣白，夜景正如洗。","疏星散明珠，淡月在湖底。","趋桥纳微风，沿浔搴芳芷。","美人不可作，吾道沧波耳。","岁晚谁与期，棠陵石川子。"]},{"t":"阳山与方思道同游书事","f":"五言古诗","c":["晨光淑初夏，野意招游踪。","策马阳山行，所亲远来从。","下马结桂枝，道穿白龙宫。","藉彼宫里草，乘彼桂下风。","渴饮丹井泉，泉甘思虑空。","希君遗人世，相将寻赤松。"]},{"t":"虎丘怀古","f":"五言古诗","c":["巀巀虎丘山，盘盘阖闾坟。","坟头阅古迹，剑池三千春。","蛟龙水中藏，白日嘘烟云。","图王事已空，万骨成灰尘。","湛卢南入楚，神物焉能驯。","不必卖薪女，王气已湮沦。"]},{"t":"冬日与顾九和殷近夫孙太初顾与成游太湖","f":"五言古诗","c":["漫漫五湖景，役役百年客。","霜容舍广墟，申椒不胜摘。","葭管复气候，岁序莽消息。","群山一何苍，远水一何白。","燕台既迢递，玄圃又悬隔。","终当吸沆瀣，去去结松柏。"]},{"t":"秋日寻友清溪用韵","f":"五言古诗","c":["深秋足爽气，莲社有雅集。","我从西丘来，蒲龛暂栖戢。","清溪在城市，八月违暑湿。","褰裳涉溪水，水芳迟余挹。","庭菊未吐华，亦有翠可拾。","悠然发遐想，西风鸣雁急。"]},{"t":"虎丘与思道同赋","f":"五言古诗","c":["西郊下木叶，商意殊不恶。","舟舆滞虎阜，言觅方外乐。","招㩦心所欢，日暮倚高阁。","沙弥事简澹，菜饭谢杯勺。","云霞阁外留，野兴忻有托。","相期无奈何，岁晏与俱作。"]},{"t":"感兴二首 其一","f":"五言古诗","c":["仰观北斗星，遥望北斗城。","天上故历历，地下何溟溟。","中原万馀里，数载风尘惊。","忧悲直愬天，聊以舒我情。","情长天更远，矫首看鸿冥。"]},{"t":"感兴二首 其二","f":"五言古诗","c":["天河白如银，隔水处牛女。","咫尺不相从，乌桥渺何许。","年年只一夕，仓卒修云雨。","金鸡催早发，回车不得住。","含啼理支机，尚悔当年事。","亦胜参与商，睽离永终古。"]},{"t":"题白云泉亭子","f":"五言古诗","c":["白云在亭上，清泉在亭下。","我本山中人，来结亭前树。","云泉甘且冽，予心永终慕。","尘机久未息，禅机当早晤。","芬华随高秋，淹留岁云暮。"]},{"t":"盈盈丹棘花寿张母","f":"五言古诗","c":["盈盈丹棘花，岁寒丽奇姿。","树之高堂背，日有春风吹。","物贞本则固，凝霜不能欺。","佩兹曰宜男，采采心自怡。","驾言赠佳人，金光以为期。"]},{"t":"和思道","f":"五言律诗","c":["取友天下半，今得方子焉。","为官不受羁，修身将到仙。","叶县王子乔，勾漏葛稚川。","明年适百粤，期子罗浮巅。"]},{"t":"菖歜二章赠郑于汉 其一","f":"五言律诗","c":["菖歜何葱葱，乃在涧之滨。","岁晚开九花，世人不得纫。","秘之嵩山阴，以俟九疑君。","念彼蒹葭草，芊芊弥广津。"]},{"t":"菖歜二章赠郑于汉 其二","f":"五言律诗","c":["菖歜何青青，乃在山之隰。","岁久生九节，茹之可绝粒。","华滋谢秋风，怜尔固独立。","吾将舍芝苓，薄言采芳苙。"]},{"t":"天台二章为应节妇赋 其一","f":"五言律诗","c":["天台有方竹，历历山之岖。","奇姿夺春色，标节方不渝。","天寒冰雪繁，清阴固自如。","南方有佳人，贞心与之俱。"]},{"t":"天台二章为应节妇赋 其二","f":"五言律诗","c":["天台有方石，光洁宛如几。","大者何嵓嵓，小者尽齿齿。","不是雕琢力，岂无神鬼庇。","南方有佳人，贞心与之比。"]},{"t":"朔州行","f":"七言古诗","c":["朔州城头凝黑云，朔州城下边人魂。","健儿悍骄好杀戮，少壮战死今无存。","悲风南下吹觱篥，马逸饮血太白窟。","不见铙歌入塞门，但见人骨白崒嵂。","近来衣冠苦出粟，岂说千朝养精卒。","班生介子不应募，愿弄悲笳令归去。"]},{"t":"雨","f":"古风","c":["黄埃䓇䓇二麦死，幽天五月无雷雨。","秪疑青竹修大雩，忽见黄头泽下土。","少男风生鸟鸣渚，苍龙行天翠蛟舞。","儿童拍手歌?蜴，徵敛从兹脱箠楚。","乃者盗贼连三霜，以致逆气成旱荒。","老稚大半委沟壑，丁壮岂免从豺狼。","况尔犁锄铸为兵，纵有废地无复耕。","东家鬻儿西鬻女，骨肉之怨何时平。","只今一雨民稍宽，柳叶榆钱尚得飧。","莫令边陲又金革，公赋从容私始得。"]},{"t":"林员外东瓯斗城图引","f":"古风","c":["连山苍苍若星宿，大江孤屿象云搆。","我行东南未见此，云是东瓯斗城子。","巽吉仁王柄东指，松坛华盖魁堪拟。","西山岧峣作领袖，就中陈迹无不有。","前有王将军，后有谢太守。","白云春草芜没久，墨池岁岁生芳茆。","自有王谢经行处，至今景物无尘垢。","绍兴以来产俊英，周刘郑薛次第兴。","咸淳之上二百载，醇正无过王龟龄。","要皆山川所毓秀，亦自守者善造就。","林侯风流士，直驾王谢后。","宾御尽才藻，形胜布篆籀。","功成北首谁与娱，但写江山入画图。","行边似防百怪出，耳畔长闻海波入。","驻鹤亭，吹笙台。","更有雁荡四百峰崔巍，千年陵谷辞劫灰。","我生胡为处溷浊，明日黄冠归去来。"]},{"t":"小岷山歌","f":"古风","c":["君不闻小岷之山连胃娄，雄视西川十二州。","青天万古走蜒蜿，峰回嶂转无时休。","剑门峨眉名失势，白帝鸟鼠俯之如浮沤。","上有许由瓢，世人不得用，直挂月户三千秋。","蒙泉泻天奔龙湫，巴溪湲湲学字流。","淜腾入汶江，万里沧溟收。","山中老桂色不滓，芝草琅玕烂成绮。","洞口长回声利车，盘石但坐烟霞侣。","宋有苏长公，隋有刘仙子。","探芝斲桂树，长镵乱云里。","小岷山，巉嶒不可攀。","刘苏以后人迹复不到，乃有曾东石，架屋读易于其间。","平生负此沧海志，少年访道青城山。","上飧青城绝璧之流霞，下弄岷峨阴壑之潺湲。","黄熊苍兕不敢迫，猿狖叫啸情自欢。","空谷无人行，兰草复翻翻。","朅来游人世，十载愁朱颜。","吁嗟乎青山信美，蒙泉亦可以洗君耳。","君胡为乎城市，许由之瓢欲何俟。","终南有捷径，北山有俗轨。","玄猿独鹤煖眼冷眼遥看尔，红尘白马有何益。","柴桑不负陶彭泽，归来乎曾东石。"]},{"t":"天津同王刘二子较射西营因赋长歌","f":"古风","c":["病夫平生沧海情，南征喜得王时行。","天津桥边秋气清，邀我醉游刘伯耕。","投壶叫白意未已，乃复较射城西营。","刘君膂力信莫当，控弦运肘固所长。","王郎生长在南方，亦能左挽五石强。","调弓坐使猛兽伏，矫矢岂有飞禽翔。","当场角胜不相降，神臂拍张人堵墙。","伶人考鼓舆台走，白日冉冉回精光。","锋翎冲撞气益扬，观者颜色歘沮伤。","熊渠以上合比数，拔胜之辈斯寻常。","病夫虽然力不足，见尔谁能分碌碌。","腾身即把忘归接，引手转被繁弱挶。","沉思重自咎，百罚敢辞辱。","忽忆先皇时，此技何曾录。","承平却作凶器比，丧乱始识文事局。","乾坤比年氛䘲厚，幽豫青徐虎狼吼。","专城将军习逃走，遂令死者十八九。","至今楚蜀犹未夷，六军虽众能者谁。","辕门衣冠更宽博，教场藜苋成町畦。","吁嚱王刘学孔子，反有馀力从事此。","幸须为国收多垒。","吾闻兹艺德之辅，匪直区区为阅武。","君不见矍相圃，公罔之裘扬觯语。","卫昌蒙羿巧弗取，射乎射乎吾愧汝。"]},{"t":"汶上对月闻笛作商调哀切命船人度曲为和因赋醉歌","f":"七言古诗","c":["焉耆八月高风起，鸿雁群飞渡淮水。","月下清砧愁远人，天涯芳草思公子。","王郎哀时最萧瑟，万里迢迢向南国。","呼我上船设冰鲙，仰天颂酒开胸臆。","关山茫茫何处边，但见急管哀中天。","冯夷听曲波面出，杨柳乱落西风前。","酒酣月落歌未已，陇思江情嗒然起。","未挂姓名玉策上，愿添海水金樽里。","人生合欢那可测，有似大海翻萍叶。","回首亲朋各别离，岂无江汉通舟楫。","流光过鸟不复驻，达官好爵身之蠹。","况乃豺狼横地轴，何限骅骝窘天步。","竹林诸贤皆酒徒，嗣宗只愿步兵廚。","古来贤达一澌尽，醉乡之托今何如。"]},{"t":"忆弟","f":"七言律诗","c":["去年苏台送汝归，布被独卧愁依依。","畬田力薄霜雪厚，怜汝受冻仍啼饥。","北有鸿雁南鲤鱼，但见风尘不见书。","深林大道防豺虎，万里看云涕如雨。"]},{"t":"猛虎行","f":"七言古诗","c":["玄阴冥冥天欲雨，苍兕嘷风劈林莽。","磨牙下山天为愁，白日杀人如捕鼠。","我忽闻言仗剑出，弯弓却射白石入。","吁嗟凤麟无时来，故使此辈为民菑。","不然驱汝渡河去，河北苍生非草莱。"]},{"t":"钟吾行","f":"七言古诗","c":["皑霜凛凛颓杨柳，钟吾驿前白狐走。","山东虎穴已尽除，淮北人烟亦何有。","自从天狼犯东斗，杀掠如山如拉朽。","四溟兵气寂不扬，纵有城隍谁则守。","黄河无梁苇可渡，曷不去此甘为虏。","就中一室三十口，那得孤儿应门户。","投生避死谁不知，钟吾令长实主之。"]},{"t":"桃源行","f":"七言古诗","c":["黄河水尽蛟龙驯，桃源沙飞愁杀人。","东方乱后再反覆，忆昔过此增烦辛。","扁舟困顿不得携，贼壕只在河东西。","路官邑子微服走，大屋高门狨獍啼。","到今事定还是非，请问流民归未归。"]},{"t":"行淮北战场","f":"古风","c":["我君渡淮水，仓卒见贼垒。","一声金鼓鸣，马跃昏风起。","三千义兵坐倒戟，一日同赴黄河死。","嗟尔渔樵人，何曾识蒐狩。","但闻鹤唳胆已落，乃使执盾从敌后。","边头将军故缩，手要取金印大如斗。","淮阴寡妻啼向天，遗恨东行刘太守。"]},{"t":"游子","f":"七言律诗","c":["桐江水清石可数，游子思归作渔父。","空谷春深记薜萝，长途日暝忧豺虎。","入林何曾见赤雀，结舌讵可赋鹦鹉。","皇天反正谁则知，有客哀伤重延伫。"]},{"t":"去年行","f":"古风","c":["去年狼山北风?，斗间坐见狼星殒。","南下旌旗若震电，东奔盗贼如齑粉。","皇天厌乱欲大诛，尔辈曷早为身图。","好趁天兵未临女，即销锋镝作农夫。"]},{"t":"兵马行","f":"七言古诗","c":["越南诸州复召募，滚滚尽赴桃源戍。","钲鼓声填沧海鼍，旌旗色闪扶桑树。","欃枪耀芒犯女斗，虎豺也更能咆吼。","部伍存亡不可知，捣衣愁杀闺中妇。","天寒野营雪嵯峨，指堕未易亲干戈。","几时奏凯标铜柱，愿得将军似伏波。"]},{"t":"百忧行","f":"七言古诗","c":["自我结束出门时，正值世路多艰危。","匪才被蒙主司录，壮图恐负平生期。","刑臣干纪作厉阶，此辈乘势为狐狸。","朝中衣冠死桎梏，意外括索空茅茨。","君门万里不可测，虎豹九关那得窥。","所以流殃遍海岱，使我积愤齐峨嵋。","一时安化起作孽，敢睨神器宁无词。","山东铁骑皆王臣，亦忍弄兵于潢池。","高祖社稷岂易改，孝宗惠爱无孑遗。","所赖天子开神聪，大加显诛不复疑。","继是诸贤出补葺，至今万姓犹疮痍。","朔方三边屡入境，桂林群獠长劳师。","意者蛮貊本梗化，虽在平世亦若斯。","荆巴乃是荒服内，五载恃险夫何为。","要之三将爱生事，民瘼肯与朝廷知。","遂令赤子化魑魅，乳臭小儿尽绯衣。","况闻村落吏捉人，比并只为供军需。","去年华林覆大众，今年桃源杀偏裨。","乃者狼兵岂得已，所过惨于熊与罴。","四方郡邑所召募，纪律不一皆逃归。","以此公私厌金革，庙议复欲为羁縻。","安得一下罪己诏，民得粒食莫为非。"]},{"t":"岁晏行","f":"七言律诗","c":["乌龙山头鸦乱飞，客子迫岁忧蒸藜。","桃源馀孽几反覆，玉山一路方涂泥。","黄云阨关鼯狖啼，前有戈鋋后鼓鼙。","十年通籍何辛苦，犹自飘蓬负老妻。"]},{"t":"皋鱼子","f":"古风","c":["陟阿丘以风，白杨摇摇朝暮中。","乌栖白杨树，飞过阿丘宫。","皋鱼子，抱树啼。","为我问终风，何事无已时。","父母不得养，儿心亡绝期。","儿心有绝期，木华落尽风不吹。"]},{"t":"今辰行送张敬中","f":"七言古诗","c":["今辰何辰秋复暮，黄花欲吐且未吐。","越王台上风不回，谢女江边叶如诉。","征途遥遥不肯住，岁晏天涯向何处。","冀北能无属目云，闽南会见伤心树。","忆昨奏赋大明宫，绨袍布被昕夕同。","于时公壮我尚少，许身奚啻登夔龙。","黄尘白日两相蒙，世事变覆真太匆。","十年风波苦汎梗，一旦鬓发成飘蓬。","皂鹘飞来意怠杳，龙媒跛足眠芳草。","勋业空嗟明镜中，巾鞋早向荒山道。","公今走马黄金台，黄金安得如山堆。","自信材官少贫贱，岂有志士久尘埃。","石田豆苗半枯死，余独忧勤弄烟水。","刘向何心厌簪绂，管宁薄命甘泥滓。","他日西方相忆无，北鱼南雁徒为尔。"]},{"t":"大水歌二首 其一","f":"古风","c":["闽州五月雨不歇，剑南诸溪水俱发。","溪边树木缠风雷，郭外人家走鱼鳖。","野老惟忧禾黍歇，尾闾不见波涛泄。","君莫恨去年前年雨水绝，越王台下江流竭。","行人道上思饮冰，古井盐花白于雪。"]},{"t":"大水歌二首 其二","f":"古风","c":["玄阴冥冥噎不通，五月六月皆天风。","雷霆啸海乌兔急，田野尽在波涛中。","南山豆苗沙压死，东畬禾头半生耳。","志士宁辞沟壑填，农夫自此生事已。","君不见无诸城外鬻幼男，今岁诛求岂但三。"]},{"t":"独树篇","f":"古风","c":["豫章之山盘盘乎巀嶪而倚天，石璧万仞荒㫚嘘云烟。","上有独树风雷缠。","轮囷偃亚黛色古百围，窍穴号吸謞宎飘风传。","孤根入地几百尺，云是蘧仙手植距今三千年。","内注沆瀣华，外荡日月光。","枝翻浪涌，子堕金香。","自是灵株䬃飞动，天鸡海鹄空多梦。","白日影倒彭蠡阴，黄昏声压香炉重。","千峰远意含太和，万木岂敢争嵯峨。","霹雳空中下矢石，洞庭无地浩然风波。","兹木结踞其如何。","大厦长年急梁栋，心猜目眩今犹多。","君不闻上古有大椿，万六千岁为秋春。","精英幻化那可测，至今世有青牛君。","兹木无乃是，不然何以有此垂天之苍云。","山樊古柏相葱菁，早晚移根天帝庭。","修条思在雪霜外，肯与众木分光荣。","柤梨楸桑亦蓊郁，掊击拆泄岂辞辱。","商丘之樗，曲辕之栎。","非不巨且齿，拳曲轴解徒为尔。","吁嗟乎豫章独树何神哉，安得长梯倚天畔，上采附枝下柱明堂摧。"]},{"t":"君莫疑行送道宗赴阙","f":"古风","c":["长歌一曲杨柳枝，短歌一曲青云词。","近前劝君君莫疑。","男儿不作儿女态，所贵国士当酬知。","与君俱非年少时，桑弧蓬矢何当遗。","腰间环佩光陆离，取媚泉石非其宜。","留侯只掉三寸舌，黄石将略真王师。","宁戚车下鸣声悲，风尘漫漫缁短衣。","五羖大夫百里奚，世主不识终涂泥。","英雄所耻比草木，且复俛首就絷羁。","故国万世尤神奇，安能郁郁久居兹。","子云寂寞空守雌，屈身伸道非君谁。","君知鸿鹄合高飞，一翥万里无天涯。","短枋香稻藏罘罝，弋人慕君君不知。","阆风玄圃便栖止，慎勿下饮淤塘陂。","于乎慎勿下饮淤塘陂。"]},{"t":"衡山高赠周公仪方伯","f":"楚辞体","c":["吾闻天高不可升，南岳上应天玑衡。","绝地七千五百丈，祝融之峰最巉嶒。","乾坤开辟自古纲维平。","三山西圮六鳌死，然后阳门反户东南倾。","巑空遏日乃有此巨镇，俨如天王神武虎臣矫矫来千城。","离宫富炎德，桂树常冬荣。","若非昆崙西起占枢纽，泰山之外谁当南岳之纵横。","芙蓉石廪势腾掷，雷泓风穴声硼?。","七十二青莲，一一凌紫清。","行云肤寸合，呼吸遍四溟。","鸿雁高飞不能过，嗟尔鹤上人胡为抗行云而上征。","回风潇潇吹古雪，倒翰七泽流三星。","潇湘如系沦洞庭，君山萍漂一点青。","累臣帝子不可以招而返兮，但见苍梧惨澹鼓瑟悲湘灵。","吾闻地有五岳犹天五行，衡山万古合峥嵘。","日南天阙傥或折尾闾，汎溢地道何由成。","吁嗟乎祝融驭无极，朱鸟来有凭。","夫何为乎绛天芒熛，炎海波涛惊。","天生豪杰须尔用，五岳四渎备尔形。","弥纶藩翰岂比块然者，不然天将谁使之清，地将谁使之宁。","周夫子，崇高遍博要如此，平生意气吾与尔。"]},{"t":"岁暮集林中丞宅","f":"七言律诗","c":["中丞华堂集众宾，金杯玉盘兴未了。","尊前羯鼓催落梅，醉后佳人媚芳草。","洛波二龙卧已深，睢阳五老归应早。","座上狂生感岁华，铜龙咽月霜天晓。"]},{"t":"涵江寄伯固","f":"七言律诗","c":["囊山十里涵江市，不见涵江见溪水。","溪边柴门占青竹，市上高楼夹苍梓。","市南故人黄省郎，后峰自垒对茅堂。","一旦相思辄命驾，岂无消息到君傍。"]},{"t":"麦斜行","f":"七言古诗","c":["今我不乐游麦斜，石田璚草摇春华。","洞门玲珑骇初见，细路窈窕行未涯。","是日春光正骀荡，黄鹂布谷声相向。","远树葱菁色已齐，古木诘屈神犹壮。","岩下山翁供酒餔，赏心岂复忧行廚。","云端傥遇林樵谷，为尔分张石室书。"]},{"t":"再题望夫石","f":"古风","c":["登彼关山，望君来归。","朝朝暮暮，君不来归。","襁中儿女大，日久无完衣。","泉水滔滔不入山，男儿出门良独难。","今时畏途相戒蛇豕，相残欃枪苦未灭。","君身无时还，君身亮自惜。","妾身无羽翮，思心从君安可得。","晨兴望君，暮化为石。"]},{"t":"芝谷歌","f":"七言古诗","c":["商于黄公人不识，独卧空山候秋石。","紫芝风香吹满谷，渚兰汀芷无颜色。","儿童对客歌白云，此曲人间那得闻。"]},{"t":"玄明宫行","f":"古风","c":["君不见玄明宫中积金碧，云是权珰结真宅。","贝阙凭陵上帝居，彤台照耀长安陌。","雕龙铸虎歘飞动，至今赤日风云黑。","崖壑天开朔漠摇，鲸鲵日吼沧溟仄。","探奇秪见灵怪集，矫首翻诧星辰迫。","西国只园应渺茫，六朝萧寺空千百。","白龙胡为作鱼泣，想尔当年势辉赫。","土木经营动四方，珍奇联络来重译。","分明造化出其手，左挥右霍何不得。","欲将燕市作蓬山，便有神人为驱石。","奸雄到死竟不悟，骄奢之末无终极。","气数相乘可自由，李猫赵鹿空回头。","君不见大市街头权倖路，古来齑粉谁曾收。"]},{"t":"雪山歌和薛君采方思道","f":"古风","c":["君不见南宫少谷老麻鞋布褐色枯槁。","万事都归混沌里，一生但结江山好。","未即乘牛函谷关，尚须跨马长安道。","长安岁暮雪满城，甃雪便筑山峥嵘。","岩㟼踞地虎豹急，星躔斗转山河明。","玉女峰前瑶作台，夸娥一夜轻移来。","袍笏真当米芾拜，诗篇数荷邹阳裁。","阶墀把玩已两月，皓气遥遥正相得。","尘土谁分冰雪姿，市朝聊寄烟霞癖。","未妨颓阘旋补葺，时见消融势尤岌。","啸月长闻白鹤回，含风岂恨青阳及。","青阳青阳谩相放，金石瑱填本波浪。","适来天地入虚无，何事么么论消长。"]},{"t":"鞠歌赠思道","f":"古风","c":["垂桑弓，挂蓬矢，旦夕如长凫，谁将哺尔乌。","来啄粟飞入网罗，将尔含哺向滹沱。","河水㶁㶁，黄沙淫淫。","琴弦自有心，翻奏山水音。","流响入明堂，锡尔龙凤章。","但得龙凤章，不愿尚书郎。","持归报尔父母，父母之恩安可毕。","歌黄钟，鼓朱瑟，高堂沉沉射红日。"]},{"t":"东漈柴门歌陈执之侍御席上与思道同赋","f":"七言古诗","c":["瀛海之滨龙门高，万峰回合相腾逃。","歘忽云气随六鳌，沙蟠石走地不毛。","八水东飞漈其下，青天白日风雷号。","蛟龙窟宅掀夜涛，深不可测安可挠。","天吴海若长周遭，丰隆雨师尔所操。","上天下天直顷刻，沾洒后土如流膏。","东海仙人骑赤鲤，翱翔尽决三千水。","下悯浊世意未已，六龙鞭策风云里。","神功一敛容一指，太虚不动民安止。","柴门萧萧水之涘，但见金波堕潭底。","世人不识柱下史，曾进当年圮桥履。","余也青云一畸士，袖中三尺龙之子。","只今濩落甘泥滓，乾坤不交国士耻。","有往必复自此始，惟愿为云逐君起。"]},{"t":"思道屋为暑雨所破为作破屋歌","f":"七言古诗","c":["南州暑月气正溽，伏雨衣裯尽如漉。","朱方转东热更酷，渴想宫冰与夏屋。","不应天气反北行，苦寒之地炎蒸沃。","长安敝庐淫雨里，上漏下湿宁安宿。","方子新颓笼鹤亭，郑生亦失穷猿木。","郎官俸薄食指繁，原宪终辞九百斛。","伏金未伏火未流，虞书历象今难读。","安居美食古所贱，陋巷箪瓢分须足。","洛阳杜鹃湿不归，愿得羲和宅旸谷。"]},{"t":"徐瑞卿给事所藏仲姬墨竹引","f":"古风","c":["田郎掉臂登我坛，手持一轴青琅玕。","云是仲姬真迹留世间，徐卿得之岁应寒。","烟波淋漓洒不乾，蜩腹蛇跗古所难。","风梢露叶仅尺许，远势翻在青云端。","燕山六月雨不止，暑气如焚汗如洗。","那知此君入我侧，便有秋声落吾耳。","偪侧未枕洞庭流，虚无更忆潇湘水。","君不见洋州文学士，渭川千亩不盈咫。","笔锋取自心眼底，但见鹰鹯随兔起。","又不见前时萧恊律，能工水墨古无匹。","疏寒不作筠粉态，瘦劲独得箫韶质。","萧郎丹青久绝笔，洋州袜材谁祖述。","胜国诸贤各擅场，只数仲姬入其室。","至大由来二百春，墨痕缣素看犹新。","得非尤物自有鬼神护，无乃好事者摸拟希其伦。","于乎貌物非物人非人，天地亦到么么津。","徐卿画本且莫论，眼前万事谁伪真。"]},{"t":"南唐后主画竹引","f":"古风","c":["君不见彭城彭奴元姓李，早入徐家称帝子。","又不见九华山下齐丘生，晚入南唐作谋士。","同时契合风尘里，草昧君臣若鱼水。","淮北初收格斗尘，宫中漫得丹青理。","升元阁上写墨竹，翠葆萧森凤毛起。","手书珍重表恩殊，御墨淋漓湿桑梓。","世代相催犹梦幻，金陵画饼宁复尔。","帝王从古多好手，人物绚素无不有。","前有殷武丁，物色惟传傅岩叟。","后有宋道君，鹰犬骅骝歘飞走。","丹青意气稍或别，治乱兴亡一回首。","彭奴彭奴听我歌，淇水才贤本众多。","但惜九华山，不似傅岩阿。","吁嗟乎竹花零乱岁蹉跎，凤凰不来将柰何。"]},{"t":"白纻歌二首 其一","f":"古风","c":["白纻歌，白纻舞，吴趋青童越素女。","翩翩绮縠鸾凤举，流宫转徵清激楚。","玳筵璚膏君莫忘，卿云灿灿世将昌。","赤日时下舒以长，令君黄耇乐无疆。"]},{"t":"白纻歌二首 其二","f":"七言律诗","c":["兰陵白纻色胜银，裁缝舞袖当上春。","调筝考瑟宴嘉宾，送意尊前未敢亲。","东方将明乐不违，主人欢笑客忘归。","钟鼓齐发且复希，矫视云端双鹤飞。"]},{"t":"太乙山歌","f":"古风","c":["吾闻终南太乙峰，乃在于天都陆海之中。","巨灵赑屃与天通。","丹梯直驾太白窟，金精反射蓬莱宫。","西南尔是华夷关，日月平视如跳丸。","但见黄河涓涓下霄汉，齐州九点翻波澜。","鳌掣鲸掀势何劲，三星不度龙沙瞑。","华岳崚嶒徒自雄，渼陂盆盎虚相映。","山中之人夐自奇，骖鸾翳鹄凌云逵。","袖中剑器拨时危，林猿皋鹤且莫疑。","君不见卫叔卿，白鹿云车谒天子。","问之不答意何长，兴亡已落纹楸里。","留侯谈笑用汉帝，功成麟凤谁能系。","孙登长啸苏门山，声似黄钟动天地。","达人修身俟世至，得薪用光始有济。","才多识寡嵇叔夜，尔曹宁免今之世。","吁嗟乎终南太乙长崔嵬，虎视龙兴安在哉。","霸王贤达俱尘埃。","峰头傥结三花树，从尔黄冠归去来。"]},{"t":"题吕纪画鹤","f":"七言古诗","c":["国朝画禽谁最精，四明吕纪推独步。","貌出青田一片影，天机物色生毫素。","霜翎藻质何翩翩，月下苍虬欲上天。","半夜狂风吹碧落，扬声直彻广寒边。","凤凰不来猿鹤悲，似怜独立羽毛稀。","若遇辽东丁道士，联襟接翼与同飞。"]},{"t":"画山水引","f":"七言律诗","c":["天风盘松翠蛟吼，白浪浮山苍兕走。","月落未落光射空，道人梦在沧洲东。","云冠雪氅乌皮几，皓首相从只黄绮。","我亦天台采药师，为君更话蓬莱水。"]},{"t":"一樗散人歌","f":"古风","c":["君不闻漆园傲吏称上仙，商丘之樗人共怜。","栋梁绳墨秪须论，散木不有全天年。","林夫子，一代贤，扬辉饰智君不然。","有才耻与短世用，沧溟卧处，洪波无边。","手握青玉芝，畅歌云和篇。","奇气不可秘，吾尝得君于三狼之紫烟。","拜君床下称竖子，大儿小儿安足传。","酌君酒，捋君髯。","乾坤尽纳芥子里，大道之下圣蒙融晦俱茫然。","掌中樗树大莫拟，附枝屈铁龙夜起。"]},{"t":"长歌行","f":"古风","c":["南湖谷老谁识尔，被褐裹头卧桑梓。","早时读易编屡绝，直道如弦仕三已。","郎官十年穷不休，八口羞称折腰米。","虞廷咎夔苦梦寐，前代君臣若鱼水。","老骥伏枥志千里，绨袍百结吾不耻。","鲁生甘守白茅屋，张良还从赤松子。","洛阳少年抱区区，汉室规模叔孙礼。","嗟哉往事谁向语，惠施无人予期死。","凤凰楼下党锢成，浊流岂但十一士。","君不见申屠蟠，灭迹烟霞里。","又不见郭林宗，涉世终泥滓。","沧江日落归去来，东山草堂安在哉。","迟清亭子风拔颓，贫贱如此令心哀。","殷王中兴图逸才，孰为霖雨为盐梅。","终日畚锸歌徘徊，于乎终日畚锸歌徘徊。"]},{"t":"题赵子昂林木","f":"古风","c":["元朝学士宋家子，手得丹青古莫比。","笔端点染入精妙，心上经纶乃如此。","唐之毕宏宋郭熙，林木山水那兼美。","一匹缣素动数旬，工夫细腻世绝伦。","未论意象补造化，已觉气势生风云。","眼中蛟龙相盘拿，风云变态何诧嗟。","草间莫着王孙足，王孙芳草今天涯。","君不见马远区区念宋家，残山剩水胡为耶。"]},{"t":"远如期","f":"古风","c":["远如期，黄道亨。","圣人继天，麟趾来臻。","麟何以来，时将太平。","黄河千年而一清，四序遵轨转玉衡。","日之方中破幽冥。","美人来騑，乐我民生。","琴瑟不调，弦当改更。","远如期，把君熊轼饮君兕觥。","美人哉，治载成。","行哉乎，愿我皇帝寿万年，匪荒宁。"]},{"t":"傅木虚报与诸君问余疾苦不至口述嘲之","f":"古风","c":["善夫卧病将月馀，死复不死苏未苏。","晨昏咆躁向天呼，药物丘积恨未除。","昨日傅生来报予，言拉诸子过吾庐。","闻之顿觉眉头舒，唤取庖人饬宾廚。","奚儿举网更捉鱼，肴核已具音全虚。","病夫延颈直到晡，柴门不见君子车。","裘羊径草今何如。","呜呼自古友道胜妻孥，生死不二方丈夫。","疾病望尔来相扶。"]},{"t":"岊江楼观涨送马子莘北征","f":"古风","c":["霖雨五日风不回，百川流沫连山来。","洪涛拍天浩荡而崔嵬，驱沙走石龙门开。","白日不到地，沧江一何哀。","三山反在八水下，一苇阻绝天之涯。","与君起登江上台，节物感我旷士怀。","六龙行天太阴死，妖蛟孽虺胡为哉。","蜗皇功亏禹德衰，吾恐地轴今将颓。","短歌微吟为君起，丈夫壮年要为者何事。","请君起长楫，共击三千水。"]},{"t":"苦节行","f":"古风","c":["下南四郡三郡兵，闽盗此日真纵横。","安溪莆口备惨毒，杀气上冒天为腥。","六师不发无战情，贼过一程移一程。","兵骄将怯往必败，疆场之事谁曾经。","官军畏贼远护送，民兵不教将何用。","坐遣群羊啖虎口，万姓何辜死无讼。","前王少女不就虏，抽身抱石沉江水。","詹家少妇贼杀姑，骂贼不屈同姑死。","我歌苦节行，泪下哽咽悲不止。","吾辈堂堂七尺躯，况作男儿把天纪。","清风岭，曹娥渚，长使志士哀千古。","吁嗟乎詹家少妇前王女。"]},{"t":"伤哉行","f":"古风","c":["伤哉乎尚阳之南广业之里，千数茅茨变贼垒。","杀人成丘山，旬月不见官军至。","我思八闽十七卫，太祖以来食尽多少官仓米。","一朝缓急不得分寸力，恶用饲尔民膏髓。","膻风吹尘污诗礼，安能一沃沧溟水。","伤哉乎坝头山新渡岭，妇女不行刃加颈。","新渡岭坝头山，黄金满意妇女还。","可怜蛾眉七十二，竟无一下清风滩。","死生在前良独难。","伤哉乎前王寡妻独死房帷间，令人苦忆大古时。","上有尧舜下皋夔，契敷五教张四维。","稷播百谷民忘饥。","九州分理十二牧，天子端拱而无为。","四凶既诛戮，六合歌雍熙。","耕且让畔行让路，重门暴客从何来。","嗟彼盗贼岂无民彝，犁锄化兵谁使之。","伤哉乎圣王不作吾已而。"]},{"t":"东归行送殷先辈","f":"七言古诗","c":["阑风吹江江捲素，云脚如霾暗前路。","陶河捉抺应有求，络纬追秋不知处。","江南江北气萧骚，十家九家闻叫号。","严城白日森长戟，粤客中区折大刀。","道傍寡妇向人诉，自从乱后多愁苦。","夫主从戎去不还，大儿又在军前死。","小儿九岁娇且痴，母子投生中道离。","向来丧乱饥寒在，到处蟊螟耕织稀。","吴门一杯天为悲，送客那堪此道归。","尘烟海内还消息，兵革沧洲有是非。","东土酸风射客眸，蘋蘩为我荐髑髅。","战场断骨今收未，古道腥魂招得不。","请君勿田太山侧，山樊豺虎多如织。","请君勿钓东海滨，天吴九首飞杀人。","请君莫叩函谷关，只今长夜正漫漫。","为君生计谋不得，一夕筹心鬓毛白。"]},{"t":"题官竹","f":"楚辞体","c":["黄河之水非淇澳，亦有籦笼挺平陆。","彭城官舍清如簇，磥砢纷披成绿玉。","使君公馀开鼎餗，清声入坐可无肉。","酒酣戏我题官竹。","座中才子谢水曹，对客跳跃先挥毫。","诗成夺我宫锦袍，行辈大叫称诗豪。","我怜此竹绝短小，忽有感遇难成骚。","点与语曰：汝之生也不似彗帚排青苍，安能截作笙箫来凤凰。","又不似由衙大如斗，恶用于汝为柱梁。","惟应托根官舍傍，且有标节储雪霜。","中虚不肯容蝼蚁，作德君子多比方。","噫！","华滋烂死兮汝得孤存，劫火满山兮汝独不焚。","子猷云：何可一日无此君。","吾欲移汝归昆崙。"]},{"t":"玉华山歌赠盛太史端明","f":"七言古诗","c":["玉华两峰天下雄，力障碧海东巃嵷。","峰头偃蹇千尺松，停霜冒雪苍苔封。","松根飞瀑声淙淙，流入韩江豢虬龙。","徵君结屋浩渺中，开窗下瞰冯夷宫。","角巾一幅双鬓髼，玉华相对为主翁。","酒酣击筑咏古迹，韩山越埒啼猿狨。","小桃溪春深浅红，有时鹤驭来偓僼。","月明小艇西复东，富贵于我如飘风。","鸿鹄高飞不可笼，罗网缯缴难为功。","去年阙下见一鹄，今年天际冥孤鸿。","嗟予羁的未解脱，驽蹄捷径愁㤝㤝。","亦有灵源似玉华，茅茨倾倒登罴熊。","安得脱身若鸿鹄，万仞峰顶时相从。"]},{"t":"秋夜过虎丘与方思道坐白莲池石各赋一首","f":"古风","c":["夜入虎丘山，露坐白莲池。","秋月淡淡开涟漪，秋风袅袅吹葛衣。","月中歌声遏云起，双翮忽欲乘风飞。","憨憨泉，甘如饴，一饮数斗疗我饥。","可中亭上鸣参差，希音嘹亮明者谁。","方思道，郑继之，二人瞰世同一机。","今时莫道无钟期。","吁嗟乎太行之路多崄巇，烟尘障天咫尺迷。","壮志于我夫何为，五斗米，焉足糜。","南山有蕨藜，北山有紫芝。","归乎归剑池，蛟龙久不起。","生公法石至今疑，来日大难知不知。","愿言将子颠冥于武夷。"]},{"t":"遗太白山人方舄歌","f":"古风","c":["道人昔年屠赤虬，虬革中作云锦裘。","授之素女制方舄，精比南海之轻绡。","鹖冠鹤氅言好逑，未有售者微其俦。","余知尤物终非世所畜，化作双凫飞去从王乔。","低五岳，小六州，游汗漫，三千秋。","更欲乘风观十洲，掉头太白山悠悠。","饥餐聚窟霞，渴饮清海沤。","赤霄九万去一息，戾止岂负樊笼忧。","汉网恢恢羽猎愁，双凫双凫何处求。","我亦从今理风翼，觅汝于昆崙顶上之椒丘。"]},{"t":"登七十二峰阁歌","f":"古风","c":["吾闻太湖东注三千水，乾坤纳纳几万里。","东西洞庭天际起，七十二峰如聚蚁，青天白日飞雪雨。","兵尘惨惨满人间，故国何处愁路难。","五湖多风不可渡，入山魑魅相依附。","若为化作鸿冥冥，南向峰头结烟雾。","终焉身重飞不得，展转湖边倚高阁。","湖昏阁静百感集，怅望毛公谢乌鹊，嵩高西去寻灵药。"]},{"t":"题望夫石","f":"七言古诗","c":["自君之出西玉门，寒砧夜夜驱离魂。","楼兰未灭君不归，泪眼一注穷昆崙。","自纺自绩孰与存，眼青直到天地昏。","城中少年生情性，一曲离鸾岂堪听。","妾身自是蓝田璧，宁向峰头化为石。","海水屡见成丘山，犹望夫君生入关。","呱呱小儿尚在手，白衣苍狗无不有。","谁家去夫䞉出丑，世上妇人多姓柳。"]},{"t":"黄茅冈和东坡二首 其一","f":"七言古诗","c":["云龙山下黄茅冈，秋风破帽聊相羊。","徐州太守遗石床，烟花十万皆微茫。","白龙帝乡千里长，有客好事遥相望，高歌不乏太守狂。"]},{"t":"黄茅冈和东坡二首 其二","f":"七言古诗","c":["我醉倚歌千仞冈，一声叱起万石羊。","寒笳数声咽胡床，四山烽火何茫茫。","道路阻绝烟尘长，京华咫尺不可望，小子年来学佯狂。"]},{"t":"东征","f":"古风","c":["大风从西来，行子向东去。","黄尘十丈强，没尽伤心树。","匹马追风不受鞭，长安回首思悠然。","城头笳鼓晚来急，村村寡妇当檐泣。"]},{"t":"鹧鸪行","f":"古风","c":["行人行人子细听，鹧鸪近前语分明。","山有长蛇兼罔两，水若可涉霜涛惊。","哥哥欲行须暂停。","君不见赤雉四顾不出山，虞人关弓射雉还。","君不见大鹏抟风九万里，六月一息图南徙。"]},{"t":"早发临安","f":"七言律诗","c":["东阁冬月西关西，仲冬雨雪水复微。","去年今年风色恶，大有小有人烟稀。","于潜诸县讨大贼，军旅之后多蟊螣。","意外征求莫大繁，今日苍生合苏息。"]},{"t":"大游篇赠高宗吕","f":"古风","c":["登山须骑五色羊，涉水须泛无倪航。","一身之小四海远，红光瞥影明煌煌。","年少离居历寒暑，孤凤冥鸿自高举。","东封碣石入罗浮，十洲山水犹能数。","世人未断区中缘，顽腹无肠万愁贮。","炎趋声利赴火蛾，恋食痴鸦嚇腐鼠。","吁嗟乎吾求此辈无其曹，翛然六合解天韬。","上乘灏气怀宇高，丹山碧水相周遭。","仰天大笑秋萧骚，九州热客从滔滔，高生高生纵游遨。"]},{"t":"石梁行","f":"七言古诗","c":["阴厓谽谺气溟濛，山木惨切悲回风。","石梁驾天蟠彩虹，飞流下捣龙光宫。","上仙之都弱水东，彼岸可度天之功。","十年寻仙志未已，台岳欣逢羡门子。","愿君启我元命秘，荷镵拾茅吾不耻。","桃源洞天春色多，尔时刘阮今如何。"]},{"t":"慈竹引二首 其一","f":"七言律诗","c":["北堂慈竹连理枝，青阳含惠流绿滋。","堂中佳人云佩垂，霞冠鹤帔光陆离。","麻姑盈盈进紫觞，东方小儿翱且翔。","徐歌缓节宵未央，明星煌煌应寿昌。"]},{"t":"慈竹引二首 其二","f":"七言律诗","c":["芙蓉朱蕤兰紫芽，含风被露齐发花。","庭中象席连凤珈，流辉照耀麒麟车。","麻姑盈盈进紫觞，东方小儿翱且翔。","徐歌缓节宵未央，明星煌煌应寿昌。"]},{"t":"望夫石","f":"古风","c":["自君之出矣，日日望君归。","秋风吹紫塞，夜夜捣寒衣。","楼兰未灭君不归，含啼独自下重帏。","玉关西去路如棘，安得身随鸿雁飞。","食荼中自苦，食檗那忍食。","西风吹妾身，化作望夫石。","东海之水成丘山，公乎何时生入关。","年年风雨里，但见血痕班。","妾心匪石不可转，君身如璧当来还。"]},{"t":"太白山人歌","f":"古风","c":["吾闻太白之山横绝沙碛东，去天盈尺秦地雄。","阴厓古雪吹烈风，开辟以来如白龙。","赤日横半度，百草不发天无功。","山中之人冰雪容，餐霞吸露五内空。","绿云结交河上公，寿三千岁颜如童。","北招汗漫，南挟韩终。","椒丘县圃，直天几度，拊嘴扪毕天为通。","长髯下照沧海水，玄虬跋浪吹苍穹。","视彼守株之徒，奚啻黄鹄之与壤虫。","吾将乘元气与君游无穷。"]},{"t":"粤中元父歌","f":"七言古诗","c":["泉山老子金马仙，青阳温风春可怜。","鱼须奉帝三十年，角巾南首泉山前。","司徒起家青棘郎，娟娟寒素临秋霜。","炯如白凤从君王，瑞文冥举天地荒。","壶公山人见素子，频年三出还三已。","玄文突兀凌太华，峻节孤棱冠青史。","木兰江上弄烟水，豸角鸡香恶用尔。","中丞謇謇新斋公，丽如月露映梧桐。","白笔持裁陈素封，殿前斥奸气如虹。","苍蝇贝锦心不同，中丞解缨犹溃痈。","蚤岁称知犯公眼，酬知力共塘蒲晚。","齐州腥氛黯长夜，飞腾愿附冥鸿远。","玉龙手提不可成，长歌一夕云河倾。"]},{"t":"苦寒行二首 其一","f":"七言古诗","c":["刀兵之馀气不淑，立春一月寒犹酷。","东日微微背旸谷，西风猎猎遗华屋。","吴侬号饥拜人前，吴姬受冻啼门曲，去年冬雷折地轴。"]},{"t":"苦寒行二首 其二","f":"古风","c":["南冠丈人何偪仄，恶风吹云闭春色。","白梅阴多开苦迟，黄鹂口噤啼不得。","东方征轮断无迹，鸣呼彼苍未肯回天戎，翻令丝絮专元功。"]},{"t":"河上行","f":"七言古诗","c":["白雁噭噭思朔方，乌衣逐逐度河隍。","河间草树色焜黄，淮西二月春悲凉。","北风惨懔日无光，洪涛簸天不可航。","晨风不食百鸟藏，妖虬怒鲸连山长。","途遥日暮雨沾裳，临河欲渡愁无梁。","散发狂夫何郡郎，箜篌弦绝声不扬。","侧身天地夜未央，愁燕愁粤热中肠。"]},{"t":"发京邑迷路投宿黑庄","f":"五言律诗","c":["东省多年病，南冠百念灰。","关山一怅望，天汉独归来。","行野蒲稗晚，过村笳鼓哀。","迷途更几许，愁绝望乡台。"]},{"t":"放船","f":"五言律诗","c":["柂楼下急浪，去险在毫端。","已识篙师巧，方忧蜀道难。","此溪防罔象，何日避风湍。","颇羡玄真子，清时把钓竿。"]},{"t":"泗上","f":"五言律诗","c":["总总衣冠地，方冬生事繁。","牛羊散迥野，烟火接长村。","薙藿农人聚，分瓜稚子喧。","如何恶官府，凿破此淳源。"]},{"t":"对湖二首 其一","f":"五言律诗","c":["㬒㬒玄阴日，团团照水隈。","鲸波动霄汉，鼍鼓挟风雷。","地尽青山杳，天寒白鸟回。","轻帆未相失，自此访蓬莱。"]},{"t":"过彭城怀旧二首 其一","f":"五言律诗","c":["自有干戈后，年年向此过。","乾坤未解甲，江海且增波。","拊剑心逾壮，经时鬓易皤。","渭南无梦到，终是卧烟萝。"]},{"t":"过彭城怀旧二首 其二","f":"五言律诗","c":["忆昔此避地，诸君慰我多。","别来淹日月，望尔邈山河。","洒泪山阳笛，关心陇水歌。","犹闻杀长吏，飘泊复如何。"]},{"t":"吕梁","f":"五言律诗","c":["葱岭昆崙外，吕梁天地间。","淜腾终赴海，咆吼欲颓山。","力转鱼龙窟，秋生虎豹关。","平生历险阻，对此泪潸潸。"]},{"t":"悼刘宓","f":"五言律诗","c":["宓也归何处，营魂不可招。","只疑天地阔，竟作死生遥。","苦海风涛壮，炎方罔两骄。","伤心卧佛寺，秋雨自兰苕。"]},{"t":"得思道消息二首 其一","f":"五言律诗","c":["闻汝还家后，逢时俶扰初。","艰难仍被寇，墨绖却离居。","边徼犹多故，山园未可锄。","棠陵幸襄事，亦得慰区区。"]},{"t":"得思道消息二首 其二","f":"五言律诗","c":["近逢黄吏部，报尔在三衢。","志士伤泥滓，南州困猰㺄。","时危离索久，岁晚帛书无。","却忆吴门约，萧条愧病夫。"]},{"t":"牛首","f":"五言律诗","c":["牛首有佳致，方冬亦自奇。","同云封地轴，积雪糁松枝。","谷响传钟磬，山昏泣罔魑。","凭高俯王土，何意有旌旗。"]},{"t":"归来","f":"五言律诗","c":["不作东曹属，归来巾屦幽。","岂能效舐痔，聊且避牺牛。","玉木深防病，瓶罍未省忧。","此邦虾菜贱，家室暂淹留。"]},{"t":"进衣","f":"五言律诗","c":["何处避冰雪，频怀负日暄。","未衰筋力惫，独立布衣存。","列子愁居郑，袁安早闭门。","粤南多爽气，归去牧鸡豚。"]},{"t":"兵起","f":"五言律诗","c":["自有西江乱，流民起带刀。","操差尽孺弱，杀戮到耆髦。","敌馘时犹献，军需日更骚。","长缨未得请，无计罢鞬櫜。"]},{"t":"钱塘","f":"五言律诗","c":["万山赴海国，众水汇钱塘。","王气千年歇，湖声八月长。","世传浑罔两，天巧亦荒唐。","稍待凉风发，乘槎问彼苍。"]},{"t":"即事","f":"五言律诗","c":["即事春相近，回船日日操。","微阳留朔雪，久旱失溪毛。","衢府风烟改，常山斥堠高。","危途疲薾客，汨汨向蓬蒿。"]},{"t":"严州","f":"五言律诗","c":["小传清江并，孤城碧嶂防。","土宜多竹柏，民业但耕桑。","稻熟还官得，山深伐木长。","经过数州郡，淳朴见兹乡。"]},{"t":"梨关","f":"五言律诗","c":["梨关不可上，战格屹云端。","闽浙乾坤别，风烟道路难。","堤防莫暂废，戎马未全安。","谩想先皇日，车书达百蛮。"]},{"t":"送王参知赴阙","f":"五言律诗","c":["大参行赴阙，兴落富春前。","六月楼船雨，千山传马烟。","白云留故国，綵服媚南天。","知尔宁亲后，屏营金鉴篇。"]},{"t":"画鹰","f":"五言律诗","c":["似欲飞腾起，星眸势可招。","平生酣白战，远志碍青霄。","竹兔何愁得，林貙不敢骄。","无由配鸾凤，勿以比鸱枭。"]},{"t":"忆近夫","f":"五言律诗","c":["吴门相失后，书札各茫然。","巢父终东去，刘郎重北迁。","双凫赴魏阙，独鹤下青田。","未见风尘净，怀君涕泪边。"]},{"t":"汨汨","f":"五言律诗","c":["汨汨伤秋鬓，依依欲暮年。","钓矶沧海上，布被白湖边。","避地亲朋弃，忧时梦寐牵。","无家杜陵老，且结草堂缘。"]},{"t":"梧儿初学语","f":"五言律诗","c":["梧儿生六月，孩笑识人情。","得汝愁俱破，于人眼尽青。","暂时闻学语，何日见趋庭。","尔祖能看我，回头涕泗零。"]},{"t":"伏雨","f":"五言律诗","c":["沥沥犹鸣旦，凄凄欲作寒。","晚禾翻恶湿，后土故长乾。","敝屋久僵卧，凶年甘粝飧。","持觚向人世，未得脱艰难。"]},{"t":"至日","f":"五言律诗","c":["至日风色好，粤南霜信遥。","地卑饶瘴气，春近茁寒条。","汶水昔独往，淮南谁见招。","林栖岁华晏，难免鬓萧萧。"]},{"t":"冬日草堂小集","f":"五言律诗","c":["近郭风霜浅，寒天草木稠。","敝庐元僻野，高马漫淹留。","岂是草玄宅，能回访雪舟。","生逢圣明世，未敢杜交游。"]},{"t":"喜吾惟可访少谷兼怀方令","f":"五言律诗","c":["旧国冥心久，良朋见面初。","同为避地客，独叩草玄庐。","花鸟三春暮，乾坤百战馀。","迩来方拙牧，衰疾复何如。"]},{"t":"乌石惟可同游","f":"五言律诗","c":["道山秀盘石，春半更婵媛。","海水双江入，岩花二月繁。","衰容防草昧，故老问桃源。","怜尔南游思，风烟数断魂。"]},{"t":"寒食","f":"五言律诗","c":["至后百五日，堂斋风雨深。","越乡寒作食，溟海气长阴。","身事南阳役，神京北望心。","采薪缠日月，发已不胜簪。"]},{"t":"早秋龙门舟中","f":"五言律诗","c":["艓子小于叶，早秋江上行。","风波千古转，天地几时平。","病骨怜沧海，凡才耻圣明。","不眠闻短吹，故国亦飘零。"]},{"t":"宿象山西坞二首 其二","f":"五言律诗","c":["秋云不称意，肤寸每成霖。","漏日翻东壁，随风湿远岑。","腰镰野外急，燐火晚来深。","入夜增萧索，千林猿狖吟。"]},{"t":"寄潘逸老","f":"五言律诗","c":["东湖潘逸老，守晦十馀年。","久病文园枕，长贫杜曲田。","形骸非故我，天地有真诠。","愿汝支离德，閒居读内篇。"]},{"t":"海滨书所见","f":"五言律诗","c":["北里万馀户，渔樵更种田。","打鱼乘水得，伐木上山便。","禾黍栖南亩，牛羊被远阡。","生涯未为少，何意尽颠连。"]},{"t":"卧病少谷山中","f":"五言律诗","c":["伏枕东山晚，闭门黄叶幽。","竹书遗问岁，蝉语易深秋。","散地朋情见，明时家食羞。","唯应习农圃，草野得淹留。"]},{"t":"今夕","f":"五言律诗","c":["蓟门城下月，今夕定如何。","白骨凌沙砾，黄尘控骆驼。","羽书疲传置，边马失关河。","天子方宵旰，孤臣泪已多。"]},{"t":"授衣","f":"五言律诗","c":["秋草倏已歇，鸣蛩欲近床。","北风吹鬓发，九月进衣裳。","抱病仍多事，逃空未损光。","黑貂今久敝，摇落岁寒妨。"]},{"t":"岊上送时行赴阙二首 其一","f":"五言律诗","c":["王粲江湖兴，幡然为国谋。","故山随意去，残照尚谁留。","身事齐门怨，天家漆室忧。","萧条倍怜汝，岁晚拂吴钩。"]},{"t":"岊上送时行赴阙二首 其二","f":"五言律诗","c":["念尔复赴阙，迢迢思昔年。","鸡盟尽豪杰，天论老风烟。","病向沧江卧，书无白雁传。","平生鹦鹉赋，万一故人怜。"]},{"t":"草堂","f":"五言律诗","c":["岁事日将晏，草堂今苟完。","天风吟竹叶，海月皓柴门。","藜苋还高志，经纶有故园。","何能谢贫贱，氛祲在乾坤。"]},{"t":"寄林荆门","f":"五言律诗","c":["暮年沧洲客，恸哭向穷途。","春草生归思，秋风慰病夫。","青毡后命达，白发此身癯。","八月衡山去，期君出五潴。"]},{"t":"答安黄门","f":"五言律诗","c":["怜君下峡水，寄我郢中吟。","白雪音调远，黄牛风浪深。","林丘心独苦，岁月病长侵。","胶漆知何地，迢迢鸿鹄心。"]},{"t":"读鹦鹉赋","f":"五言律诗","c":["读罢鹦鹉赋，吾怜祢正平。","识机宁入网，远害转伤生。","名在心形累，时危鼎俎烹。","异时一掬泪，洒向武昌城。"]},{"t":"江上别道宗兼怀何仲默","f":"五言律诗","c":["却向江头别，潸然感物华。","林泉移岁月，霄汉变云霞。","伏剑亦骇俗，出门宁顾家。","寄言何水部，迟尔折梅花。"]},{"t":"挽王生","f":"五言律诗","c":["吾乡论后进，尔最擅词场。","十八人间世，三千弟子行。","辕驹未竟步，石火不馀光。","忆昔邢居实，秋风太惋伤。"]},{"t":"送伍方伯入觐","f":"五言律诗","c":["尊翁吾从祖，同第甲申年。","论世鲰生愿，通家令子贤。","春风虚木榻，王事重楼船。","命薄徐高士，栖栖不受怜。"]},{"t":"闻涛","f":"五言律诗","c":["涨海饶孤寐，春山淹去归。","鱼龙永夜急，波浪远天违。","孤志存舟楫，清时卧钓矶。","尘机久已息，何事白鸥飞。"]},{"t":"中秋同高宗吕传木虚城东步月有怀京华旧游","f":"五言律诗","c":["朗月团秋社，凉风薄岁寒。","故乡谁独健，永夜此同看。","邻篴伤今昔，山杯尽肺肝。","长安旧朋侣，搔首五云端。"]},{"t":"南关","f":"五言律诗","c":["度陇心忽折，殊方梅柳春。","兵戈近满眼，书剑老随身。","世有阮籍泪，道应原宪贫。","愁闻更选士，东土已风尘。"]},{"t":"金山纪游二首 其一","f":"五言律诗","c":["双眼无空阔，长江会百灵。","吴门对海定，淮树贴天青。","钟动鼋鼍窟，云生鹳鹤庭。","中流有孤志，鼓枻下沧溟。"]},{"t":"金山纪游二首 其二","f":"五言律诗","c":["㶁㶁中泠水，东游与散愁。","楼台通海雾，岁月送江流。","好事怜司马，逃空想惠休。","献花缘尚浅，心折过扬州。"]},{"t":"阻济上","f":"五言律诗","c":["叔伯何多日，关山烽火明。","病妨风土恶，身与岁时征。","丧乱怀先帝，艰危有我生。","向来刘越石，意气不能平。"]},{"t":"怀金山","f":"五言律诗","c":["我爱金山寺，洪波万顷开。","乾坤留柱石，沧海失蓬莱。","曝日鼋鼍出，抟风鹳鹤回。","中泠洗心处，极目意悠哉。"]},{"t":"此夕","f":"五言律诗","c":["时危长伏枕，月好自临关。","斥堠连吴越，烟尘犯海山。","民穷久欲乱，师老未成班。","此夕姑苏酒，酣歌不破颜。"]},{"t":"双雁","f":"五言律诗","c":["双雁为人得，阶前相向鸣。","已辞关塞远，犹带网罗惊。","宦情一片影，客泪五更声。","侧目窥秋隼，风烟异性情。"]},{"t":"对雪答太白山人","f":"五言律诗","c":["天地忽改色，六花风乱投。","翛然翠袖薄，加我草堂幽。","照水梅自媚，闭门君不忧。","玄机正无极，将汝醉乡游。"]},{"t":"岁暮哭近夫二首 其一","f":"五言律诗","c":["南国青琐闼，东山白板扉。","三年不相见，两地思依依。","遂有幽明隔，谁云夭寿微。","江东送望眼，空复暮云飞。"]},{"t":"岁暮哭近夫二首 其二","f":"五言律诗","c":["宁知是永别，七月有书来。","即死还忧国，皇天亦妒才。","世衰元气散，君逝玉山颓。","沧海垂纶客，冥心若死灰。"]},{"t":"海门","f":"五言律诗","c":["落日绵亭岭，茫茫何所之。","山川沦沆漭，天地撤藩篱。","脱屣未相失，放瓢聊自怡。","扶桑弱水外，东望拂虹蜺。"]},{"t":"将至鲤湖道上","f":"五言律诗","c":["瑶宇青峰顶，芒鞋白鸟边。","风泉轰九鲤，云木薄诸天。","尚子终当去，庞公最可怜。","玄房今夕里，謦咳接群仙。"]},{"t":"鲤湖三首 其一","f":"五言律诗","c":["到此意了了，春湖接未妨。","薄云长恋洞，名草不辞香。","月色寒侵阁，滩声夜近床。","神仙真可学，吾即傲陶唐。"]},{"t":"鲤湖三首 其二","f":"五言律诗","c":["铁嶂垂天堑，石门修水关。","古松蟠极地，小鸟立惊湍。","玉笛何由听，真乘未即安。","芝田会心处，漫忆紫金丹。"]},{"t":"鲤湖三首 其三","f":"五言律诗","c":["何处遁天韬，烟霄首独搔。","山川进奇崛，天地入萧骚。","病骨怜芳草，烦心愧白袍。","东隅紫气盛，偏薄上仙曹。"]},{"t":"春日经白沙王氏庄","f":"五言律诗","c":["王子躬耕处，柴门碧树团。","云松飞鹳鹤，风涧引波澜。","父老壶觞得，儿童礼数宽。","西坡水麦熟，麋鹿下安安。"]},{"t":"寄王时行佥宪二首 其一","f":"五言律诗","c":["隐约王佥宪，为官近越州。","久无烽火警，能把甲兵休。","清远神仙所，君王锡宴游。","时平占福地，不用觅丹丘。"]},{"t":"寄王时行佥宪二首 其二","f":"五言律诗","c":["囊山分手去，正值暮春时。","蒲柳看衰䬃，风尘且别离。","岭南人事少，海上雁书迟。","炎瘴还消息，无劳罢酒卮。"]},{"t":"寄充之华亭","f":"五言律诗","c":["鳌峰衰病至，岁月莽蹉跎。","不识松江曲，鲈莼意若何。","朋情音问阔，师道课程多。","预报经过日，秋风偃败荷。"]},{"t":"寄郑方伯山齐","f":"五言律诗","c":["昔日莆阳役，春山共采芝。","郑虔犹逐客，贾傅自明时。","潦倒莺花切，提携酒馔随。","难忘何氏宅，汎爱木兰陂。"]},{"t":"闻汀漳罢兵二首 其一","f":"五言律诗","c":["整整汀漳戍，群凶复听招。","频闻洗兵马，不见返渔樵。","猰㺄终难狎，貔貅漫独骄。","皇情近忧豁，氛䘲若为销。"]},{"t":"闻汀漳罢兵二首 其二","f":"五言律诗","c":["羽书传上国，牙帐拥诸侯。","别峒分戎马，前锋失火牛。","果谁知要害，漫尔历春秋。","只道书生策，能分主上忧。"]},{"t":"同林九高二傅二施二避暑越王城楼","f":"五言律诗","c":["长夏升炎䓇，高城遁郁蒸。","河隍虚雉堞，云日造松陵。","不去稽康达，同游贾岛能。","愧无邻舍酒，率尔集良朋。"]},{"t":"见二毛","f":"五言律诗","c":["去国星霜变，违时老惫成。","荒迷一身在，汨没二毛生。","世短思飞舄，途穷乞步兵。","昏尘干气象，沟壑未忘情。"]},{"t":"将别","f":"五言律诗","c":["多事晋安郡，浮生未息机。","草堂存下着，花径罢初衣。","江海形容在，君王梦寐稀。","隆中弃汝去，勋业愿无违。"]},{"t":"白袍","f":"五言律诗","c":["白袍存皎洁，傍尔竹林人。","安得绿玉杖，长随乌角巾。","庄生书是愤，阮瑀行能纯。","易俗吾奚敢，将无养道真。"]},{"t":"夜热次林九 其一","f":"五言律诗","c":["中宵犹酷热，初伏未秋风。","汲井分寒水，休灯散羽虫。","宦情深自损，肺气更相攻。","象魏天萧爽，衣冠日会同。"]},{"t":"夜热次林九 其二","f":"五言律诗","c":["雷霆悭小雨，岩谷断微风。","北雪阴山里，南州大火中。","迎秋草木异，爱月女儿同。","内热兼多病，赓歌愧未工。"]},{"t":"丹青阁","f":"五言律诗","c":["建州丹青阁，清切建城西。","云栈浮高壁，风松出逶溪。","水枯沙漠漠，秋晏树凄凄。","多垒关山里，销忧聊杖藜。"]},{"t":"登建州浮屠访僧道林","f":"五言律诗","c":["浮屠秋独立，千里见氛祲。","水阁风长盛，山城日易阴。","赤霞留鹤晚，黄叶住僧深。","世事宜高卧，空惭支遁林。"]},{"t":"再游陶园","f":"五言律诗","c":["太仆遗荣在，黄华晚见招。","凿池旋日月，洗竹直云霄。","宾客时能至，园林迹许遥。","高秋花杂沓，胜地不萧条。"]},{"t":"暮秋","f":"五言律诗","c":["旅情秋又暮，长路更旌旗。","王气平三极，兵尘黯四夷。","拙惭名已晚，病恐志将衰。","许国微躯在，崎危善自持。"]},{"t":"鸿雁","f":"五言律诗","c":["稻粱荒岁月，鸿雁散江湖。","避地风霜切，防身机辟俱。","不愁天旷绝，长恐事荣枯。","二月阴山暖，归心慰远途。"]},{"t":"北征","f":"五言律诗","c":["五年归少谷，万里赴燕台。","恋阙鬓毛改，感时鸿雁来。","鱼龙已寂寞，江汉尚喧豗。","远愧青莲士，君王爱尔才。"]},{"t":"章滩","f":"五言律诗","c":["九月章滩水，危于滟滪堆。","黄郎习波浪，白日犯风雷。","鸟兽曾何有，蛟龙或上来。","畏途荆棘暗，此地石门开。"]},{"t":"忆四弟二首 其一","f":"五言律诗","c":["出门忧汝病，清泪至今垂。","鸿雁莽相失，脊令空尔思。","未依南郭隐，真怪北山移。","夜雨灯明里，商歌一拊髀。"]},{"t":"忆四弟二首 其二","f":"五言律诗","c":["驽马心犹壮，龙驹产不虚。","吾衰今更去，汝病近何如。","烽火淹鱼素，关山沓羽书。","横门思一出，此意几踌躇。"]},{"t":"崙溪对芙蓉怀林九王七","f":"五言律诗","c":["脉脉崙溪雨，芙蓉傲远天。","时危花烂熳，岁晚叶逡巡。","对影会相忆，看他亦自怜。","秋容长不灭，吾欲赠佳人。"]},{"t":"寄宗吕","f":"五言律诗","c":["高适不早达，才多数亦奇。","名应造化忌，狂与世人疑。","妻子已同志，箪瓢长自怡。","箕山好风月，将汝结茅茨。"]},{"t":"寄林惟大","f":"五言律诗","c":["不了林和靖，遐心驻薜萝。","星文天上有，书法世间多。","独鹤闻清夜，疏梅渡暗波。","沧湾馀故宅，猿鸟近如何。"]},{"t":"忆道夫","f":"五言律诗","c":["玉山建亥月，漫忆十年前。","旧驿同吟雪，诸君尽着鞭。","客途犹战伐，南楚自风烟。","异域怀知己，沈沦尔最贤。"]},{"t":"寄木虚","f":"五言律诗","c":["吾弟知名早，锋棱不可当。","交情有端复，文体下齐梁。","霜骥时犹蹶，风鹰势必扬。","嵩山读书处，烟雨压茅堂。"]},{"t":"雨后陪周用宾杖策寻天目祖花","f":"五言律诗","c":["风雨于潜道，藤萝古殿阴。","祖花传近代，瑶草寄遐心。","应世吾能赋，探玄女独深。","形骸百鍊晚，未免二毛侵。"]},{"t":"山中对孙太初食黄精","f":"五言律诗","c":["山中黄精熟，作意向山人。","制法随蒸曝，灵根集鬼神。","腹心吾尚病，服食尔能纯。","有客乘云气，三尸不累身。"]},{"t":"十一月朔日登西天目看高峰中峰二神僧祖塔因晀千丈岩寻雷起处折古松枝扣巨石长啸天风蓬蓬从谷底起偃仆草木投宿张公洞枕上漫尔成诗","f":"五言律诗","c":["汨汨衰双鬓，迢迢向两峰。","一尘消未了，万劫入无穷。","昧谷蛟龙雨，玄冥草木风。","自惭增上慢，吁骇问崆峒。"]},{"t":"岁暮寻天台山水","f":"五言律诗","c":["桃源未可极，天台烟雾深。","行歌白雪调，坐见赤霞心。","草次千峰会，鸿蒙万壑阴。","藏身一大事，聊观世人音。"]},{"t":"台州观海二首 其一","f":"五言律诗","c":["独客长途破，孤城幽思多。","入山忘日月，观海失江河。","万事只垂钓，故园未偃戈。","平生挟弧矢，流落意如何。"]},{"t":"台州观海二首 其二","f":"五言律诗","c":["迷阳不自觉，春远此登楼。","落日鲲鹏运，一桴天地浮。","白波心不变，青鸟信何由。","八骏浮云里，平居端百忧。"]},{"t":"雁宕读壁间诗侯希召云此陈准卿之作也昔与准卿为月夜游仰观天柱诸峰岌岌如坠发狂大叫自以为奇观今兹已矣相顾欷歔赋此酹之","f":"五言律诗","c":["雁荡清猿夜，黯然读尔诗。","斯人竟短折，吾道日支离。","二谷看秋月，孤峰落酒卮。","细翻嘉树传，洒泣向临菑。"]},{"t":"观雁宕龙湫","f":"五言律诗","c":["瀑布飞不彻，大声空谷哀。","青山下河汉，白日莽风雷。","潭稳蛟龙定，岁深鸿雁来。","方岩倚天畔，吾志在崔嵬。"]},{"t":"潘令席上作军中乐","f":"五言律诗","c":["张筵潘岳县，笳鼓竞黄昏。","杨柳生南国，风云动塞垣。","挥戈情可念，击楫气犹存。","汉主白登道，甘心出玉门。"]},{"t":"赠顾华玉太守","f":"五言律诗","c":["客有飘飘者，朅来湖海游。","云端寻雁荡，雪里过台州。","白业藏贤达，浮槎近女牛。","丰干漫饶舌，太守是闾丘。"]},{"t":"郡斋燕集答华玉二首 其一","f":"五言律诗","c":["赤城天欲雪，岁暮客边心。","君子风骚远，良宵尊俎深。","旅怀新浩荡，时事向萧森。","作意依刘表，移家近汉阴。"]},{"t":"郡斋燕集答华玉二首 其二","f":"五言律诗","c":["梁园初授简，越客罢鸣琴。","节序梅花及，江湖鸿雁深。","雪歌难却和，醴酒若为斟。","何限山阴兴，幽居独许寻。"]},{"t":"春日发赤城","f":"五言律诗","c":["碧海春信至，赤城愁思深。","雪晴千涧疾，日落万方阴。","毕岁皆行役，凡躯故滞淫。","西归负良友，忽尔长蓬心。"]},{"t":"浙江别王崇贤","f":"五言律诗","c":["避乱安平镇，逢君永夜船。","何堪萍水迹，直落浙江边。","天子今巡幸，崆峒积岁年。","忧心正如捣，况听卜居篇。"]},{"t":"江上赠汝厉侍御之荆湖","f":"五言律诗","c":["浙水重逢地，闽州旧话稠。","雷霆喧独夜，风雨动三秋。","骐骥行堪见，鹰鹯击更优。","他时有谏草，知上岳阳楼。"]},{"t":"登太山日观峰","f":"五言律诗","c":["东岳乾坤定，黄河一缕分。","日排瀛海浪，天入蓟门云。","鲁道伤吾志，秦碑自夕曛。","未堪疏远目，万里正䘲氛。"]},{"t":"遣愁","f":"五言律诗","c":["问途青草坂，捩柂白榆林。","暑雨东方急，河泥五月深。","低回长弃马，淹泊未栖禽。","商调何悲切，从谁觅赏音。"]},{"t":"北风","f":"五言律诗","c":["北风天际下，舟楫夜相闻。","白草悬边月，黄沙长塞云。","鸾旂犹小队，虎旅尽高勋。","崖崿暌乖久，人今已勒文。"]},{"t":"隐忧","f":"五言律诗","c":["四海俱疲敝，中原且力支。","路难惟蹭蹬，心苦有栖迟。","草泽龙初斗，天山矢更遗。","无由济社稷，哽咽送年衰。"]},{"t":"出门","f":"五言律诗","c":["去国淹年岁，出门仍糺纷。","未回塞翁马，空有野人芹。","山海随黄纛，风云驻五军。","远惭东方朔，谈笑诤明君。"]},{"t":"大田篇二首 其一","f":"五言律诗","c":["内使调鹰犬，呼声动远陲。","万方多事后，千骑大田时。","关塞回金气，旌麾把健儿。","璜溪垂钓者，能载副车来。"]},{"t":"大田篇二首 其二","f":"五言律诗","c":["禁直三千士，长搴镇国旗。","甲戈迷塞月，缯帛款边师。","大礼初回跸，春原更打围。","后车载光宠，不数汉昭仪。"]},{"t":"梦惟可为余作山中草堂","f":"五言律诗","c":["天末梦君子，山中营我庐。","江湖无利涉，家室且安居。","梅福机事早，郑虔生计疏。","京尘今始便，骑马亦樵渔。"]},{"t":"送汪希会还武昌题得彭蠡","f":"五言律诗","c":["彭蠡何时定，康郎水尚多。","鱼龙冬不蛰，日月岁相摩。","楚客思芳草，江城未凯歌。","星樯候风色，安稳犯鲸波。"]},{"t":"黄岩黄宗贤为余筑室羽山招与共栖未果守官郁郁辄有东路之思奈故乡多难欲归不可行当赴其招矣记兴二首 其二","f":"五言律诗","c":["万事无何有，风云信所为。","此生依鲍叔，何处觅钟期。","騕袅怀长路，芙蓉惜后时。","嗣宗元玩世，不恨步兵迟。"]},{"t":"答孙太初","f":"五言律诗","c":["平生孙处士，云水谊难忘。","遁世思公辈，卜居真此乡。","名高多寂寞，道在亦翱翔。","徐福终入海，蓬莱意甚长。"]},{"t":"答林德敷","f":"五言律诗","c":["曼倩淹平世，扬云困太玄。","此生元濩落，夫子最相怜。","迹逐捐金市，心卑扣角篇。","鲵桓去不远，脱屣岁寒天。"]},{"t":"月下听王稚钦弹琴","f":"五言律诗","c":["昭文鼓绿绮，六气指间流。","王子梅花思，飘飘下陇头。","月华终胜雪，商意自成秋。","今夕西方梦，佳人不散忧。"]},{"t":"送陈生赴韶州戎幕三首 其一","f":"五言律诗","c":["闽海三山下，韶州五岭南。","东风鹢首去，长路马蹄谙。","蛮井歌堪听，军门剑可谈。","丹砂真易得，吾欲解朝簪。"]},{"t":"送陈生赴韶州戎幕三首 其二","f":"五言律诗","c":["月下栖乌树，天边过雁群。","生涯随逆旅，幽独倍怜君。","百粤兹多难，今时未尚文。","南游得蛮府，愁杀郝参军。"]},{"t":"送陈生赴韶州戎幕三首 其三","f":"五言律诗","c":["已息河间辔，仍麾岭外旌。","艰危一命寄，牢落二毛生。","铜柱时存汉，乌蛮岁厉兵。","凭将攻守策，忼慨说花卿。"]},{"t":"读魏钰诗","f":"五言律诗","c":["魏钰新声出，篇篇有古风。","夜珠光照乘，天马势行空。","邑宰深相识，经生本自穷。","昆城依隐地，秪忆鹿皮翁。"]},{"t":"边将","f":"五言律诗","c":["十月黄沙动，阴山白雪高。","边兵凭剽杀，汉马辟雄豪。","王道须无外，天戈自有操。","莫令耕稼地，岁岁泣弓刀。"]},{"t":"寄徐可大黄门","f":"五言律诗","c":["往年游白下，汎爱有徐卿。","令弟今相问，怜君久振缨。","岁星还自照，谏草未全行。","谢傅东山卧，秋风社稷情。"]},{"t":"寄汪令希舜","f":"五言律诗","c":["彭门当太白，剑阁带青城。","此地神仙窟，春风枳棘情。","桃花栽欲遍，蜀道去还平。","知尔丹成日，双凫凌紫清。"]},{"t":"送人游衡山","f":"五言律诗","c":["衡山开汉沔，高者祝融峰。","羡尔为官地，看云长道容。","斋居梦波浪，冬日见鱼龙。","定有冥栖客，巢君紫盖松。"]},{"t":"送龙相赴荣府","f":"五言律诗","c":["去为朱履客，潇洒向王门。","君有神仙质，官曹入故园。","乘风帝子阁，种术武陵源。","莫吊长沙傅，荆蛮处处猿。"]},{"t":"白鹤","f":"五言律诗","c":["广野声仍度，华轩意不忘。","只疑霄汉远，其奈网罗长。","宿处随鸳鹭，鸣时学凤凰。","终当蓬阙去，天路永翱翔。"]},{"t":"冬夜过王稚钦","f":"五言律诗","c":["禁木栖乌尽，城楼戍鼓催。","瞑移中散驾，时接仲宣才。","道术吾全未，词场力拟回。","清风广陵散，爱尔数能来。"]},{"t":"赠宋鸿","f":"五言律诗","c":["怜君羽翼晚，矫矫若惊鸿。","夜蹑燕山雪，春生楚泽风。","霄汉去不极，稻粱行当逢。","遐方倦飞鸟，犹自触樊笼。"]},{"t":"题夏仲昭画竹","f":"五言律诗","c":["苍梧春欲至，翠篁风雨深。","云梢洒不乱，流影下湘阴。","杳矣虞妃泪，悠哉君子心。","凤凰去已久，对尔想遗音。"]},{"t":"人日得诸友书六首 其一","f":"五言律诗","c":["岁晚通明阁，登临念我深。","故山归未得，丛桂蔚森森。","人日双鱼信，远天黄鸟音。","如何庄舄贵，翻动越乡吟。"]},{"t":"人日得诸友书六首 其二","f":"五言律诗","c":["闻尔浮南海，鲸波隔岁回。","翻将谢傅兴，转作步兵哀。","地到朱方尽，舟从日下来。","交州拾薏苡，谁识葛仙才。"]},{"t":"人日得诸友书六首 其三","f":"五言律诗","c":["吾爱方山老，岩崖湛世情。","成都卖卜久，不道是君平。","文陋齐梁体，音收正始名。","赤霄天骥步，他日与横行。"]},{"t":"人日得诸友书六首 其四","f":"五言律诗","c":["女方寻九鲤，余苦忆丹丘。","蓂荚生无尽，璚花采末由。","兔园枚叔侍，牛渚客星浮。","杳杳孤槎外，相思天汉流。"]},{"t":"人日得诸友书六首 其五","f":"五言律诗","c":["不跨山公马，春今薛老峰。","前时紫芝曲，尚绕白云中。","霄汉惭栖棘，泥沙想蛰龙。","明朝解组去，共醉薜萝丛。"]},{"t":"人日得诸友书六首 其六","f":"五言律诗","c":["尔同邺下士，染翰擅词场。","余岂东方朔，犹含汉署香。","放身沧海上，得句白莲塘。","迟暮思君子，春来数雁行。"]},{"t":"送人游邺下","f":"五言律诗","c":["邺城魏七子，文藻亦吾师。","四牡君今去，风流端在兹。","荒芜铜雀榭，寂寞武安祠。","独有韩陵石，黄沙岁岁吹。"]},{"t":"部直","f":"五言律诗","c":["春怀耿不寐，怅望宛京天。","鹤到中宵唳，星分万井悬。","燕云时少耗，郊禘日虚传。","常想南昌尉，先存谏诤笺。"]},{"t":"送张汝州","f":"五言律诗","c":["汝水元依洛，嵩山直配天。","今君簿领去，兼结水山缘。","世路黄尘里，官曹紫逻边。","谁能废组绶，跨鹤去翩翩。"]},{"t":"送陈思献赴金陵","f":"五言律诗","c":["昔慕蔡夫子，今知陈使君。","深居避矰弋，用志到羲文。","却向金台别，翻将宝剑分。","秣陵依隐地，养拙幸相闻。"]},{"t":"河陇","f":"五言律诗","c":["河陇时多事，兵车岁几奔。","犹闻遣太仆，长计向军门。","羌羯方酣战，骅骝尽不存。","西归报天子，已到渥洼源。"]},{"t":"西山杂诗三首 其一","f":"五言律诗","c":["春尽一到此，散愁幽意繁。","西湖草已绿，南国桂应蕃。","宫殿浮今日，山河控北门。","时艰羡飞锡，来往给孤园。"]},{"t":"西山杂诗三首 其二","f":"五言律诗","c":["昔日西湖钓，宣皇游幸来。","至今鲛室里，彷佛锦云开。","岁月芙蓉殿，关山龙虎台。","东巡志更远，谁挽八鸾回。"]},{"t":"西山杂诗三首 其三","f":"五言律诗","c":["西山五百寺，多傍北邙岑。","土木春岩尽，楼台海雾深。","僧皆传玉食，地更垒黄金。","纵目翻愁极，长安岁岁阴。"]},{"t":"送洪南安","f":"五言律诗","c":["平生洪大理，朴直古人心。","执法汉庭上，春风吹六阴。","一麾横浦去，相失庾山深。","他日逢梅使，听歌行路吟。"]},{"t":"伍中丞拟归田索题","f":"五言律诗","c":["伍公江海思，鱼鸟久相安。","拟逐鸱夷去，翻怜铁豸冠。","萝云药圃细，竹月锦堂寒。","矍铄风尘里，忧时且㨿鞍。"]},{"t":"周公器弘治初为庆符令赋诗追忆之","f":"五言律诗","c":["周君为邑日，江汉尽桑麻。","帝力谁知识，长安无狭斜。","但将九溪水，频灌庆符花。","遥想弹琴处，南风吹未涯。"]},{"t":"余侍御珊喜湖","f":"五言律诗","c":["柱史湖边宅，柴扉开皖峰。","晴天回鹳鹤，暮水迥鱼龙。","芰服身偏稳，渔竿意可慵。","眼中秋浩荡，为尔咏芙蓉。"]},{"t":"西山杂诗","f":"五言律诗","c":["落日春湖上，烟波正渺茫。","衣冠非敢倚，鱼鸟坐相忘。","痛饮还山简，招携有葛疆。","濯缨计未得，意气总沧浪。"]},{"t":"送人归渤海","f":"五言律诗","c":["尔去秦台上，秦台秋正繁。","城深渤海郡，草歇乐陵原。","蓬阁风云至，若华波浪翻。","看君有道气，早晚共腾骞。"]},{"t":"送人之宣州二首 其一","f":"五言律诗","c":["白也风流处，云山满意幽。","兹为宛水隐，况得敬亭游。","桃李含清夜，梧桐下素秋。","澄江净何日，转忆谢宣州。"]},{"t":"送人之宣州二首 其二","f":"五言律诗","c":["宣城仙圣地，山水作名州。","石控琴高鲤，江深谢眺楼。","白龙降已久，黄鹤唤何由。","尔去乘云月，飘飘过十洲。"]},{"t":"送屠文治侍御使苍梧","f":"五言律诗","c":["衰䬃仍乖别，羁栖几过从。","驽骀无熟路，鹰隼自秋空。","铜柱扶桑下，郁林沧海东。","南征且乡邑，大不类秋蓬。"]},{"t":"张子言家移旋覆草","f":"五言律诗","c":["旋覆知名草，秋斋不住花。","群芳尽摇落，此地且年华。","坐领幽人意，行辞处士家。","相看到霜雪，采掇辅丹沙。"]},{"t":"吾邦","f":"五言律诗","c":["丧乱秋风起，吾邦尔独回。","徒伤羁鸟赋，不见钓龙台。","少谷芝仍茁，南昌角正哀。","建安七子下，流落仲宣才。"]},{"t":"送蒋君佩视弟还谯","f":"五言律诗","c":["太丘二令子，伯也是难兄。","枥下垂骐骥，原头过鹡鸰。","燕关共卧后，亳社独归情。","万国今戎马，愁云日夜停。"]},{"t":"屏息","f":"五言律诗","c":["屏息经纶志，栖迟阊阖云。","风尘蒙不解，龙虎乱相闻。","秪有还山梦，空馀谏猎文。","长缨系越颈，感激汉终军。"]},{"t":"薛君采见过","f":"五言律诗","c":["薛稷过逢日，新诗向我传。","聊炊太仓米，一诵陜郊篇。","薄宦虚谈剑，危时合引年。","秋风下沧海，掷置广文毡。"]},{"t":"题虎溪三笑图","f":"五言律诗","c":["东林卓锡地，宛在昆崙西。","莲社谁堪入，庐峰不可梯。","一空无色相，三笑岂菩提。","便合攒眉去，酕醄过虎溪。"]},{"t":"送林以乘谪夷陵二首 其一","f":"五言律诗","c":["宜都三峡口，迁客意如何。","落日黄陵庙，秋风骇浪多。","巴蛮伐鼓祭，江女踏蹄歌。","莫唱渝州曲，猿声近汨罗。"]},{"t":"送林以乘谪夷陵二首 其二","f":"五言律诗","c":["水部青云志，忧君双鬓斑。","同时谏羽猎，独尔窜荆蛮。","波撼黄牛峡，天连白虎关。","栖迟下客食，直以长瑜还。"]},{"t":"秋月","f":"五言律诗","c":["秋月长安社，光清太液池。","蟾蜍终不灭，乌鹊竟何之。","铁骑喧今夜，金波及四夷。","关山正阻绝，却向篴中吹。"]},{"t":"思道约游西山病不赴漫答兼问宗林二首 其一","f":"五言律诗","c":["嗟尔棠陵客，乖期秋独归。","香山有夙诺，幽事忽相违。","木石机心损，云霞朔气微。","时时梦鱼鸟，未返薜萝衣。"]},{"t":"思道约游西山病不赴漫答兼问宗林二首 其二","f":"五言律诗","c":["昔游湖上寺，犹记释宗林。","语我菩提树，恒河深复深。","风沙晚识面，江海后知音。","白鹤翩翩去，青天何处寻。"]},{"t":"十日对酒姚氏园二首 其一","f":"五言律诗","c":["野老经时病，深秋出郭情。","辋川聊对酒，京洛未离荣。","小水行丹壑，馀花藉绮楹。","松阴立不倦，何限暮涛声。"]},{"t":"十日对酒姚氏园二首 其二","f":"五言律诗","c":["病跨山公马，秋过习氏池。","远天鸿雁尽，昨日菊花期。","棋局翻相恼，鸥群总不疑。","生涯抱瓮外，一任隐君为。"]},{"t":"上毗卢阁二首 其一","f":"五言律诗","c":["远上毗卢阁，崇高望不稀。","关山仍此地，城阙自斜晖。","羽檄流星过，行营万马围。","渔阳暮色至，引领翠华归。"]},{"t":"上毗卢阁二首 其二","f":"五言律诗","c":["阁迥临虚旷，秋高入渺茫。","燕歌动易水，骏骨望昭王。","日落城笳起，天寒塞草黄。","扬雄辍扈从，空自赋长杨。"]},{"t":"城戍","f":"五言律诗","c":["戍鼓长鸣夜，军容更入朝。","北风尘漠漠，南讨意迢迢。","秋有苍梧狩，能无黄泽谣。","遐方尽玉帛，八骏自应骄。"]},{"t":"陈执之宅同诸君酌菊二首 其一","f":"五言律诗","c":["秪抱霜雪姿，风沙怅独悲。","亲朋更此地，酩酊对花枝。","栗里归心远，潇湘秋事迟。","东君不相识，只自向华滋。"]},{"t":"陈执之宅同诸君酌菊二首 其二","f":"五言律诗","c":["绣衣都下宅，丛菊好花枝。","延客尊罍罢，良宵风露垂。","娉婷岂自媚，迟暮宛相宜。","故国鳌峰上，繁英今满篱。"]},{"t":"冬日顺门陪九卿请驾视牲","f":"五言律诗","c":["春曙复冬初，仍瞻白鹭车。","礼从郊庙损，天入震离虚。","江汉哀戎马，岩堂望谏书。","生惭百里子，去国意踌蹰。"]},{"t":"送苏侍御从仁使蜀","f":"五言律诗","c":["骢马今何去，玄冥岁已残。","风云行剑阁，钲鼓动松潘。","事在西戎部，功亏旧将坛。","怀柔亦边略，要识圣恩宽。"]},{"t":"依依","f":"五言律诗","c":["独有南冠客，依依郭氏台。","未酣燕市酒，翻惜陇头梅。","汉戍连城动，秦关千角哀。","县金买骏地，徒使壮心颓。"]},{"t":"梦与王阳明论学","f":"五言律诗","c":["美人入我梦，惠我白云词。","述作何多事，经纶非尔时。","空斋下鸟雀，深水伏龙螭。","尚愧瑶华赠，悠悠江汉思。"]},{"t":"柬顾华玉","f":"五言律诗","c":["在昔过逢日，天台山雪生。","何期易水上，同忆赤霞城。","杯动青春色，堂含沧海声。","终焉谢朱绂，㩗手石梁行。"]},{"t":"送人之赣州","f":"五言律诗","c":["西江兵乱后，作宦意悠悠。","秪爱青油幕，高横白鹭洲。","风尘鄱下战，岁月赣江流。","应羡陶皮隐，桃花开未休。"]},{"t":"赠方梅墅","f":"五言律诗","c":["方干乐道处，小墅野梅开。","对客翻高调，飞花片片来。","萝云蒙卧榻，陇日照行杯。","不耐王孙思，春深未却回。"]},{"t":"送人之惠州","f":"五言律诗","c":["名家参政下，独觉仲容贤。","宦辙今何往，毕栖此最便。","物情沧海俗，天气百蛮烟。","秪近啼猿树，乡心日夜县。"]},{"t":"马伯淳西归","f":"五言律诗","c":["与君同去国，别路各悠悠。","吾邑东海上，终南西雍州。","何时报缟带，于此解纾裘。","万事将慈母，长歌渭水流。"]},{"t":"春暮游城西寺","f":"五言律诗","c":["毗卢千佛阁，近在绿云中。","客到虚无岸，春归莺燕丛。","燕台望不及，古意渺何穷。","拟入东林社，殷勤向远公。"]},{"t":"山人","f":"五言律诗","c":["吕公嘉遁处，云鸟静相亲。","日与嵇中散，沈冥山水滨。","雁荡斜连海，桃源直避秦。","斋居玩易理，龙性可能驯。"]},{"t":"别林克相二首 其一","f":"五言律诗","c":["邺下传诗句，沧洲拂钓竿。","正思龙卧稳，翻惜雁归难。","燕壁云回合，闽关天郁盘。","飞腾最怜汝，慷慨一弹冠。"]},{"t":"别林克相二首 其二","f":"五言律诗","c":["汝复弹冠出，余今解绶回。","平生一掬泪，洒向黄金台。","戎马东南剧，鼓鼙城阙哀。","无能奏羽猎，翻愧子云才。"]},{"t":"赠吴生","f":"五言律诗","c":["稻粱荒楚塞，鸿雁尚安归。","秪避云中弹，冥冥天外飞。","子有鸾凤质，枋榆非所依。","风尘好自惜，莫损綵云衣。"]},{"t":"赠山人受封","f":"五言律诗","c":["念彼南山隐，南山郁自怡。","时闻春雨外，高倡紫芝词。","猿鹤心同远，裘羊径不缁。","莫嫌儿女笑，宫锦照庞眉。"]},{"t":"昆崙子","f":"五言律诗","c":["君本昆崙客，岩扉星汉连。","流沙拂袖去，述作为谁传。","紫芝秀可掇，青牛何当还。","异时求物色，萧䬃白驹篇。"]},{"t":"安陵阻风","f":"五言律诗","c":["落日安陵上，荒芜望蓟丘。","风沙无昼夜，家室此淹留。","江汉悲多故，干戈赋远游。","河清是何日，吾志欲东周。"]},{"t":"赠杭方伯兼柬东卿提学","f":"五言律诗","c":["邴原犹薄宦，疏广已遗荣。","无复周王猎，谁钦钓渭名。","余亦武夷去，探玄学久生。","逢君五湖畔，北眺有馀情。"]},{"t":"同晋陵诸子游水西二首 其一","f":"五言律诗","c":["共有烟霞想，言过西水浔。","薜萝迷远近，鱼鸟入高深。","花气含风满，山堂附郭阴。","宴酣忘主客，谁赋越乡吟。"]},{"t":"同晋陵诸子游水西二首 其二","f":"五言律诗","c":["喜到晋陵郡，行逢诸子招。","竹林初散帙，槐树已鸣蜩。","绕径驯朱鹤，通池接画桡。","遥思荷蓧者，去作羽山樵。"]},{"t":"陈遂初进士邀宿赪谷草堂夜观西湖渔火","f":"五言律诗","c":["税驾归闽土，寻山入浙中。","客情逢胜友，东路任飞蓬。","夜艇流渔火，秋杯折渚筒。","巢由圣世事，直北大明宫。"]},{"t":"过孙山人苕溪旧居","f":"五言律诗","c":["耿耿忆孙楚，溪边青竹门。","未同苕水月，竟失汉阴原。","寿天真诠外，风云孤梦存。","平生少谷榻，独下向谁论。"]},{"t":"寄施粤之侍御","f":"五言律诗","c":["南昌隐君子，寄迹绿云端。","念尔神交久，惭余色会难。","此时歌伐木，伊昔阻风湍。","何日下县榻，相看黄箨冠。"]},{"t":"碧岩下小憩望太湖","f":"五言律诗","c":["长夏碧岩好，萧萧千竹林。","看山白屋静，息驾古藤阴。","震泽惊波在，洞庭归鸟深。","楚臣新去国，漫有卜居吟。"]},{"t":"谒孙太初坟二首 其一","f":"五言律诗","c":["草堂琴瑟罢，羽化竟何如。","那复乌藤杖，空传白鹿车。","沙湍且鸥鸟，天地即蘧庐。","白首林君复，终无封禅书。"]},{"t":"谒孙太初坟二首 其二","f":"五言律诗","c":["伊昔丘园隐，风流谁似君。","谈诗振大雅，抗志入高云。","宅拟王官谷，山名太白坟。","寥寥广陵散，定向夜深闻。"]},{"t":"寄赤城诸子","f":"五言律诗","c":["自别赤城去，藏身金马门。","莼鲈心独苦，林壑道何尊。","万事风波过，三年魂梦存。","终焉共携手，采秀入桃源。"]},{"t":"赠张南陵","f":"五言律诗","c":["张翰风流在，南陵溪谷间。","一为香案吏，便得敬亭山。","饭饱鲈鱼味，身随鸥鸟班。","后期望星汉，知尔御风还。"]},{"t":"宿胜果寺","f":"五言律诗","c":["游吴复适越，漫宿赞公房。","小隐薜萝密，大观江海长。","钵龙蟠夜壑，云篴语秋堂。","稍觉菩提长，森森松橛凉。"]},{"t":"赠秀公","f":"五言律诗","c":["不作寻诗计，沉情日闭关。","牛车载上乘，锡杖拄空山。","玩世风尘外，放身花鸟间。","秋斋食橡栗，见尔好容颜。"]},{"t":"题潘山人水居","f":"五言律诗","c":["习静不出郭，著书长闭门。","烟霞结白日，薜芷避缁氛。","巾舄从吾好，钟彝有道存。","埋名爱蒋诩，多事陋扬云。"]},{"t":"荒村","f":"五言律诗","c":["荒村连日雨，散发不曾梳。","岁月报恩子，生涯种树书。","无因致故旧，岂是爱空虚。","门巷曈曈日，轻车恣所如。"]},{"t":"赠叶少府","f":"五言律诗","c":["吾闻隰城尉，通练更文章。","坐扫封狐雪，行开射鸭堂。","诗篇穷地秘，海水识风凉。","似尔纡黄绶，巢云意不忘。"]},{"t":"行宋宫故基","f":"五言律诗","c":["西门数顷地，旧是帝王宫。","复道清波没，妆台碧藓空。","王侯混丧狗，臣庶议从龙。","莫谩歌禾黍，山河涕泪中。"]},{"t":"吴山","f":"五言律诗","c":["吴山入阛阓，佳气自苍苍。","洞窈通仙隐，龙盘集吉祥。","犹宜雪后对，莫为岁寒妨。","所历多酸鼻，兹山耿不忘。"]},{"t":"凤林","f":"五言律诗","c":["凤林五百户，活计在山溪。","野碓远堤水，嵓田高治畦。","新年传糗饵，旧俗诵菩提。","生女无人育，男长少娶妻。"]},{"t":"屴崱峰","f":"五言律诗","c":["盘礴地灵在，东南天柱高。","三江转燕尾，百粤乱牛毛。","未出无生网，难忘大觉刀。","巢云定何日，万国且旌旄。"]},{"t":"九日方山登高","f":"五言律诗","c":["方山五片石，巉巀七千寻。","气象恒嵩敌，风云岁月深。","百年大梦寐，九日此登临。","愿卸红尘累，嵓栖长道心。"]},{"t":"耳鸣","f":"五言律诗","c":["官司忽失职，双耳自今聋。","尽日闻天鼓，何时听么虫。","向人艰应答，于世类冥蒙。","未老神俱耗，勋名涕泪中。"]},{"t":"寄华玉","f":"五言律诗","c":["潇洒顾吏部，为邦日渐多。","人心兴礼乐，世事入风波。","剡曲舟堪诵，濠梁道不磨。","向来巾子雪，堂构合如何。"]},{"t":"绣岭晓行","f":"五言律诗","c":["绣岭行不极，盘山霄汉长。","谁将钓渭意，同寄雁湖傍。","野宿雀芋饭，岩居木槿墙。","晨征莫相失，云气正茫茫。"]},{"t":"金山纪胜","f":"五言律诗","c":["扬子宅前水，东溟势欲吞。","乾坤真浩荡，岛屿尽儿孙。","石舞风波作，龙归日月昏。","平生爱飞动，长剑倚昆崙。"]},{"t":"集胜果寺分得眠字","f":"五言律诗","c":["寺阁兹辰会，宾朋尽世贤。","云山兼胜日，岩壑得高眠。","移席竹林晚，题诗花蕊妍。","燕鸿何意绪，来往各翩翩。"]},{"t":"游烂柯山同杨节使二首 其一","f":"五言律诗","c":["太末徐王国，青霞洞府名。","江山共吾子，风雨若平生。","锦树岩扉净，秋杯云鸟明。","应悲看棋者，柯烂未忘情。"]},{"t":"游烂柯山同杨节使二首 其二","f":"五言律诗","c":["岝㠋干峰下，天开姑蔑墟。","地灵蕃玉蕊，神至响云车。","未破人间局，先翻石室书。","茅靡入道术，岁晚莫踟蹰。"]},{"t":"风雨过南关","f":"五言律诗","c":["元亮东归日，长途菊正斑。","宁辞彭泽米，早得匡庐山。","雨势秋崩峡，云阴昼阨关。","回思凤凰阁，吾已得生还。"]},{"t":"赠姜建州","f":"五言律诗","c":["南迁为隐吏，山水兴难降。","客至丹青阁，时翻白玉缸。","谏书留御榻，惠政及邻邦。","若访汉阴老，知余是姓庞。"]},{"t":"送李曲江","f":"五言律诗","c":["李子新为令，南迁百粤州。","梅花过庾岭，吹满曲江头。","鹏运天池暮，槎停星汉秋。","丹砂好寄与，早晚上罗浮。"]},{"t":"寄倪南雄","f":"五言律诗","c":["京华相别后，闻尔亦南图。","笑解银鱼绶，坐分铜虎符。","山蟠五岭厚，俗到百蛮殊。","千里梅花使，春风好寄余。"]},{"t":"送王文辉游武夷","f":"五言律诗","c":["王郎不肯住，脱屣武夷山。","学道心长苦，寻仙鬓欲斑。","鱼龙淹海日，鹅鹳厉天关。","何限沧洲兴，希君共一扳。"]},{"t":"送公衡韶州省觐兼怀倪南雄李曲江二首 其一","f":"五言律诗","c":["尔往宁亲日，千花春未稀。","此行无道路，綵戏及庭闱。","王勃才名盛，孙登世事微。","如逢始兴守，道我钓鱼矶。"]},{"t":"送公衡韶州省觐兼怀倪南雄李曲江二首 其二","f":"五言律诗","c":["拟此过逢数，何期迅别愁。","青山问庾岭，沧海近韶州。","猿狖声堪听，桄榔叶正稠。","风烟易春暮，须及曲江楼。"]},{"t":"暮春湖上","f":"五言律诗","c":["沧溟春欲暮，湖上芳草生。","风烟吹不断，遥带凤凰城。","万事兵戈外，孤臣藜藿情。","何当拊神物，谈笑扫欃枪。"]},{"t":"詹文化","f":"五言律诗","c":["报尔龙头选，才名我昔闻。","凤凰今有象，骐骥直空群。","黄散经纶事，金縢礼乐文。","更期射三策，早晚奏明君。"]},{"t":"夏公谨","f":"五言律诗","c":["四海夏公谨，平生道未疏。","岂为青琐客，不问白菟裾。","帝业维新日，皇舆草昩初。","看君抱经济，献纳定何如。"]},{"t":"戴宗道","f":"五言律诗","c":["小戴青云器，明经正显行。","以兹先后甲，知尔庙廊情。","樗栎人俱弃，凰麟世必清。","经年无一字，何以慰平生。"]},{"t":"林克相","f":"五言律诗","c":["厓老本钓侣，经纶今若何。","自来科目选，秪为利名多。","江汉波初定，夔龙道不磨。","南冠有词赋，万古卿云歌。"]},{"t":"梁日孚","f":"五言律诗","c":["梁鸿终自洁，禄仕暂栖迟。","混世名为佛，修身早得师。","儿童送我意，俯仰别君时。","何日长安市，相过筇一枝。"]},{"t":"方思道","f":"五言律诗","c":["方郎天下士，慷慨古人稀。","刎颈交惟女，同心结到谁。","江湖同苦别，霄汉独雄飞。","远愧朝歌叟，中兴淹桂枝。"]},{"t":"汪希周","f":"五言律诗","c":["崇阳汪武选，识汝自京华。","拊剑平江汉，经年别室家。","飞云收虎帐，战马返龙沙。","长揖青门外，何人善种瓜。"]},{"t":"林德敷","f":"五言律诗","c":["圣后乘元化，江湖思致身。","君居财赋地，况作庙堂臣。","勋业时堪就，鲈莼兴莫新。","何当逐狐鼠，同看帝城春。"]},{"t":"郑伯兴","f":"五言律诗","c":["吾宗贤吏部，昔往鹿门山。","应世身难卧，探玄意自閒。","山公启事近，庞老㩦家还。","余亦隆中隐，接君床下颜。"]},{"t":"苏天秀","f":"五言律诗","c":["吾怜苏太乙，磊磈长安豪。","钓罢渭川猎，名驰天汉曹。","言余亦善士，拊己愧时髦。","徐稚平生义，还山解佩刀。"]},{"t":"姚元肖","f":"五言律诗","c":["接手燕昭国，倥偬十载前。","乌栖空绕树，鹏转自横天。","抚世缘知己，抡才后少年。","君看越石父，客礼竟虚传。"]},{"t":"顾九和","f":"五言律诗","c":["昆山顾学士，十载绾银鱼。","勋业天人策，行藏封禅书。","与君成去住，谋道竟何如。","先帝焚香在，皇情可但虚。"]},{"t":"陆子渊","f":"五言律诗","c":["成贤真此地，瑶席尔司成。","述作回中古，机云愧后生。","华亭鹤正唳，蓬海雁长征。","结谊风尘上，看君万里情。"]},{"t":"寄刘希尹吏部兼怀薛君采二首 其一","f":"五言律诗","c":["长安薛子宅，对尔诵骊驹。","云树怀良友，风尘愧腐儒。","看山费日月，忧国阻江湖。","方朔金门下，藏身道不孤。"]},{"t":"寄刘希尹吏部兼怀薛君采二首 其二","f":"五言律诗","c":["薛郎成小隐，旧宅定荒芜。","万事将双泪，经年无尺书。","身随梅福去，病与马卿殊。","白日调龙虎，飞腾意有馀。"]},{"t":"龙门西象顶望海","f":"五言律诗","c":["浩荡窥南纪，长天望正繁。","北风青啸海，高浪白浮山。","舟楫思兼济，云霄怅独还。","何当溯牛女，重扣紫皇关。"]},{"t":"岊江送黄伯固大理赴白下","f":"五言律诗","c":["大理平生友，相看涕泪存。","谏书君最切，往事我难论。","放逐心无尽，岩廊道已尊。","愿将金石志，长报圣明恩。"]},{"t":"送人之邺","f":"五言律诗","c":["浩荡夷亭意，经过邺下来。","王门占玉节，春日上铜台。","游子牵多梦，高堂候举杯。","蘼芜江畔草，应挽使船回。"]},{"t":"明妃曲","f":"五言律诗","c":["明妃初出塞，宛转意何穷。","上马琵琶曲，流悲入汉宫。","自言妾命薄，万里去和戎。","今日蘼芜草，青青向陇中。"]},{"t":"木虚过青野堂夜坐","f":"五言律诗","c":["小坐同吾子，荒斋寡四邻。","林鸺鸣近夜，山月迥随人。","太乙青藜杖，先生乌角巾。","中宵莫说剑，恐益鬓毛新。"]},{"t":"访吴山人隐所","f":"五言律诗","c":["脱屣吴居士，寻君江水遥。","云房生夜气，薜牖散春潮。","榻静闻空籁，情高梦九霄。","从兹毕灵宝，不赴小山招。"]},{"t":"答陈天游","f":"五言律诗","c":["淑气回南纪，文星傍省堂。","犹县沧海月，留照紫薇郎。","学道防衰晚，愁时应帝王。","思君直咫尺，一夕鬓毛苍。"]},{"t":"湖中寒食","f":"五言律诗","c":["湖上逢寒食，行行云日迷。","林花相映发，只似武陵溪。","远水清烟并，高杨黄鸟啼。","年年对芳草，古意满城西。"]},{"t":"答林贞孚主客","f":"五言律诗","c":["忆自秋风起，虚传奉使回。","未捐池上佩，翻失陇头梅。","尧舜垂衣日，班杨奏赋才。","黄金散朝士，知上礼贤台。"]},{"t":"送吴德翼佥宪赴阙","f":"五言律诗","c":["使君今赴阙，春兴定翛然。","江汉黄华动，风云锦䌫牵。","星移南斗下，路引北堂前。","愿有华封祝，天朝寿万年。"]},{"t":"夏夕青野堂卧月","f":"五言律诗","c":["海月团芳夜，园庐引绪风。","琴书栖榻晏，岩壑与人同。","尚泽南山雾，终怀北极枫。","黄虞忽到梦，伊郁卧隆中。"]},{"t":"入海","f":"五言律诗","c":["沧海鸥波外，云艘迥自航。","大江沉马腹，密雨湿鱼梁。","未及星槎远，那知天汉长。","渔竿变孤志，翻愧紫荷裳。"]},{"t":"答顾华玉参政","f":"五言律诗","c":["吾怜顾长康，吏隐近沧浪。","学道通元窍，蛟龙翊尔翔。","云回朱鸟国，花照紫薇堂。","授我冥筌意，相期天汉长。"]},{"t":"闭门","f":"五言律诗","c":["经岁避尘缘，时参道德篇。","柴门背海闭，鸥鸟受人怜。","桂树栽成实，松花采作团。","微官浑忘却，唯记孝皇年。"]},{"t":"闻荐","f":"五言律诗","c":["逋客晚知几，西山言采薇。","长安三丈雪，而我赏心违。","隐处无人识，荐书何事飞。","冥鸿天万里，空遣弋人归。"]},{"t":"早秋怀晋安诸子","f":"五言律诗","c":["摇落茭湖晚，湖边鶗鴂鸣。","秋风吹桂树，一伫越王城。","榻有南州重，人兼卫玠清。","还闻刷羽翮，看尔共蜚声。"]},{"t":"寄赠石室山人","f":"五言律诗","c":["安期持世界，挟策西入关。","吴老遵牛渚，乘槎钓不还。","行藏元气里，弓剑彩云间。","何时留玉舄，去入蓬莱山。"]},{"t":"病中","f":"五言律诗","c":["避地抛铜墨，风霜岁屡更。","那期凤鸟至，亦遣伏雌鸣。","久病丹心苦，中年白发生。","如何张仲蔚，却扫卧升平。"]},{"t":"出塞曲二首 其一","f":"五言律诗","c":["黄金雕鹊印，白马出榆林。","瀚海行人绝，阴山杀气深。","汉恩长北损，边骑日南侵。","一唱丁都护，三军泪满襟。"]},{"t":"出塞曲二首 其二","f":"五言律诗","c":["大王开绝域，上将喜边功。","塞外风烟异，军中苦乐同。","龙旂凋朔气，虎帐卧沙风。","未系单于颈，横戈意气雄。"]},{"t":"克相过草堂别去余病垂死诗来见怀呻吟中答之","f":"五言律诗","c":["喜女文章贵，相过成笑言。","追陪憎病骨，风雨别柴门。","会苦青衫湿，情多白发繁。","形骸已近死，谁复与招魂。"]},{"t":"病中哭伯固二首 其二","f":"五言律诗","c":["去年白下去，送汝芋原陂。","今日湖边问，俾余双泪垂。","终为谏议鬼，竟失帝王师。","已矣先朝事，伤哉此盛时。"]},{"t":"陈少府镧","f":"五言律诗","c":["吾怜陈少府，独抱明月珠。","五载官闽土，春风生向隅。","县知水薤意，频握玉麟符。","霄汉声名早，看君受剑车。"]},{"t":"张起溟约过草堂为传卒所误","f":"五言律诗","c":["君是峨眉秀，余惭南海琛。","并期歌白雪，何止断黄金。","接手难如此，浮生感独深。","闽关及漳水，鱼腹莫教沉。"]},{"t":"答林白石大参","f":"五言律诗","c":["归钓龙溪水，君胡亟失时。","岂因白石烂，竟赋绿衣诗。","拙抱江湖愧，贤于弼亮宜。","重华迹已远，吾道欲何之。"]},{"t":"七月望游水西白鹤寺乘月泛岘江","f":"五言律诗","c":["爱尔东林社，乘秋到蕊宫。","招邀满童冠，歌罢舞雩风。","鹳鹤黄庭莫，巾袍白露中。","西江上云月，归艇意何穷。"]},{"t":"送季明德应召赴阙二首 其一","f":"五言律诗","c":["接手为兄弟，交期共死生。","云逵易相失，三宿晋安城。","海内风尘切，秋边鸿雁鸣。","飞腾未时莫，万里好长征。"]},{"t":"送季明德应召赴阙二首 其二","f":"五言律诗","c":["相别无一语，相观情自閒。","风云感壮士，江海散秋颜。","道已干时禁，人须涉世艰。","去乡莫草草，迟尔阳明山。"]},{"t":"琅琊王墓下作","f":"五言律诗","c":["田文全盛日，泪下雍门弹。","王氏千秋后，劳歌玉树残。","寝园生兔穴，疑冢奠龙盘。","万仞莲花色，关河望已难。"]},{"t":"大田读伯固起溟见和之作怅然怀答二首 其一","f":"五言律诗","c":["读尔怀沙赋，潸然系我思。","当年分即死，此日已云迟。","社稷还唐介，江山哭子期。","才贤世有几，况及圣明时。"]},{"t":"大田读伯固起溟见和之作怅然怀答二首 其二","f":"五言律诗","c":["朅来张仲蔚，秀句日逾多。","岂不思君子，其如长路何。","商霖怜我在，谷口喜人过。","终愧箕山隐，无能守薜萝。"]},{"t":"南山赠林迁于比部","f":"五言律诗","c":["忆自随三釜，同歌沧海篇。","何期傍九日，得结碧山缘。","江汉兵戈外，风烟鱼雁前。","相看未忍别，更上木兰船。"]},{"t":"莆口之败福宁兵最无纪律大纵掠金以致肝脑涂地赋诗伤之","f":"五言律诗","c":["闽粤何多难，兴漳师未休。","虎豺行白日，天地泣清秋。","欲捣群凶穴，须枭败将头。","兵贪法半至，遗恨福宁州。"]},{"t":"剑州赠陈待用太守","f":"五言律诗","c":["郁彼神仙府，云骖迥莫扳。","言将五裤手，满弄九华山。","紫盖风尘表，黄堂霄汉间。","因君觅神物，剑水有龙蟠。"]},{"t":"鸂鶒","f":"五言律诗","c":["鸂鶒无拘碍，浮游锦石傍。","雌雄互饮啄，毛羽割阴阳。","已得沧洲趣，宁思天汉翔。","并生大化里，幽独阐文章。"]},{"t":"送罗复之","f":"五言律诗","c":["圣寿齐天地，臣衷效海山。","面陈安瘼疏，头耸触邪冠。","玉帛奔重译，衣裳济万官。","不胜恋阙处，时事尚多艰。"]},{"t":"春日怀南湖旧居","f":"五言律诗","c":["南湖不可到，幽事自涟漪。","田父春相遣，邻翁暮与期。","烟霞隐薜荔，风日晒鸬鹚。","岂待清商发，花时有所思。"]},{"t":"双凫","f":"五言律诗","c":["汎汎长依渚，飞飞不度岑。","却无黄鹄志，但有白鸥心。","烟水知音旧，鱼虾得食淫。","自从叶县令，来往五云深。"]},{"t":"向晓","f":"五言律诗","c":["河影忽不见，东方方小明。","晨鸡许市客，秋管海边营。","起舞者谁子，飘零独此生。","矇昽听金钥，封事转驰情。"]},{"t":"朝雨","f":"五言律诗","c":["若木光初判，玄云复积阴。","撼江风色劲，洒壁雨声淫。","泉室鲛人泣，天边越客吟。","馀情何处诉，燕雀处堂深。"]},{"t":"将旦","f":"五言律诗","c":["曙色浮东海，腾腾渐太清。","明霞低水槛，宿雾迥江城。","警柝已罢击，征人初启行。","豺狼今挈领，岂是乏长缨。"]},{"t":"与方质父登于山","f":"五言律诗","c":["巾舄动高兴，江山入大观。","烟霞几回首，天地一凭栏。","晴日千村晚，长风五月寒。","莫嫌踪迹远，石室在人间。"]},{"t":"雨夜","f":"五言律诗","c":["萧萧风振屋，汎汎雨鸣楼。","宿鸟惊巢堕，潜鲛出水游。","客床沾处湿，病枕听来愁。","颇羡清江上，风波不碍鸥。"]},{"t":"地上","f":"五言律诗","c":["雨霁临池好，桥平纵步宜。","湿泥勤燕子，新水乐鱼儿。","病叶风多下，团萍夕更移。","中吴消息恶，吟赏泪交垂。"]},{"t":"秋暮","f":"五言律诗","c":["秋色去不反，客心悲奈何。","病妨风土恶，愁感岁时过。","弟妹流离甚，江湖丧乱多。","沧洲十月雪，回首钓渔蓑。"]},{"t":"题南野旧居","f":"五言律诗","c":["南山百亩地，记得种瓜时。","风日蜻蜓下，犁锄布谷知。","辋川流水在，谷口主人非。","独鹤青天外，空亭自落晖。"]},{"t":"湖上","f":"五言律诗","c":["爱此湖上雨，共君湖上游。","乾坤双短鬓，江海一虚舟。","烟景初相见，春光不可求。","明朝下西崦，相望意悠悠。"]},{"t":"参文殊禅道上得栖字","f":"五言律诗","c":["移舟泊浅渚，风日便轮蹄。","不雨江声定，长阴野意齐。","香厨钟后饭，田舍午时鸡。","入山应未得，聊尔学禅栖。"]},{"t":"次刘德羲怀金山韵","f":"五言律诗","c":["记得金山顶，风烟八面开。","乾坤留柱石，沧海失蓬莱。","夜色京江水，春光般若台。","兵尘兼病眼，长望几徘徊。"]},{"t":"重游大石次刘德羲韵二首 其一","f":"五言律诗","c":["病夫泉石性，山雨健来过。","花濡回蛱蝶，松偃足藤萝。","隔岁青春别，同群白发多。","宦游殊慰此，高志未全讹。"]},{"t":"重游大石次刘德羲韵二首 其二","f":"五言律诗","c":["幽事住云泉，湖光远接连。","寺钟山意动，松雨涧声悬。","石壁开云窦，桃花隐洞天。","中原尚多垒，此地合逃禅。"]},{"t":"望武夷时与黄元质同赋","f":"五言律诗","c":["客路未千里，名山已万重。","歌传武夷曲，兴落幔亭峰。","密竹幽幽鸟，深溪隐隐舂。","黄生诗句好，吾得事游踪。"]},{"t":"有怀","f":"五言律诗","c":["独客路千里，美人天一方。","连宵入我梦，今日写新章。","白月犹故国，青山皆异乡。","不堪秋信至，梧叶下沧浪。"]},{"t":"谒屏山书院","f":"五言律诗","c":["隐隐屏山顶，悠然见考亭。","众星开分野，一水入沧溟。","礼乐今为盛，门墙世必经。","平生鸿鹄志，数问紫州城。"]},{"t":"谒考亭书院","f":"五言律诗","c":["西门犹阙里，平地见沧洲。","谋道无虚日，寻源直到头。","德言俱不朽，庙貌正须优。","欲济波涛阔，临流重涩羞。"]},{"t":"送王崇贤","f":"五言律诗","c":["黑云天未厌，清江船不开。","客情春草长，国事朔风来。","叹世长卿枕，疑人郭隗台。","看君回綵服，拜舞兴悠哉。"]},{"t":"赠吾隐君兼怀惟可","f":"五言律诗","c":["谁言道学者，正印自文山。","守黑惟空谷，潜身到大还。","声名百世下，交谊九垓间。","因尔怀君子，江湖好驻颜。"]},{"t":"棠陵家观释宗林诗画戏为一偈嘲之","f":"五言律诗","c":["莲社柢能入，林公许径过。","法衣乘獦獠，佛日动山河。","五蕴元空寂，三车亦障魔。","白牛载词藻，西去欲如何。"]},{"t":"冬日对白菊","f":"五言律诗","c":["白菊尘埃里，翛然涅不缁。","风霜忌太洁，桃李竞当时。","水德元如此，花神祗自私。","遐方对灯烛，聊副赏心期。"]},{"t":"怀人","f":"五言律诗","c":["客思苦作恶，美人长别离。","愁深九日菊，梦饱故山芝。","劫火明天地，秋声入鼓鼙。","销魂仍病骨，行止昩前知。"]},{"t":"题黄隐君水居二首 其一","f":"五言律诗","c":["人境不肯住，水居犹沧洲。","青山如对隐，白发本无愁。","春草诗魂合，秋风乐事求。","鲈莼兴不浅，聊定此生谋。"]},{"t":"题黄隐君水居二首 其二","f":"五言律诗","c":["水居意自得，海鸥来不妨。","老怀惟杖履，秋事在林塘。","桂桨依渔父，菱歌出女郎。","逃名非故尔，但恐失沧浪。"]},{"t":"钓台","f":"五言律诗","c":["文叔为天子，先生顾钓矶。","故人一夜话，星坐旧山归。","严濑无今古，羊裘有是非。","瓣香台下拜，素志尚依违。"]},{"t":"得闽中消息","f":"五言律诗","c":["闽中久无雨，百谷尽枯燋。","魃虐延诸郡，农工岂一朝。","何时免冻馁，吾邑更征徭。","避地翻愁思，馀生不自聊。"]},{"t":"对雪答太白山人","f":"五言律诗","c":["天地忽改色，六花风乱投。","因之翠袖薄，加我草堂幽。","照水梅自媚，衔泥燕有求。","一杯思共尔，日暮问行舟。"]},{"t":"哭龚道","f":"五言律诗","c":["海内君知我，闽中我失君。","云霄剑在壁，风雨榻扬尘。","龙见悲吾道，乌飞念此身。","艰危有壮志，南望重沾巾。"]},{"t":"旅夕逢所亲述怀","f":"五言律诗","c":["乍见却悲欢，相询语夜阑。","数年罢道路，诸弟泣饥寒。","井灶还多故，亲朋有永叹。","自怜飘泊甚，闻此屹忧端。"]},{"t":"下濑","f":"五言律诗","c":["回溪去似箭，乱石簇如鎗。","下濑扶招急，凌湍荡桨忙。","未妨临滟滪，翻喜得沧浪。","范蠡扁舟外，风波更渺茫。"]},{"t":"赠王双林游宦海门","f":"五言律诗","c":["振铎维扬去，堂斋俎豆幽。","岂为苍水使，与度海门秋。","三鳣随风至，群龙抱日游。","山阳篴可听，展转忆良俦。"]},{"t":"送彭少参进万寿表","f":"五言律诗","c":["离声言可恶，子去似登仙。","敬述诸侯职，欢呼圣主年。","青云缠礼服，白浪静楼船。","锡尔天闲马，黄金台下传。"]},{"t":"答方思道富阳见寄","f":"五言律诗","c":["浙水浩天涯，吴门意已乖。","三年方数字，半世渺孤怀。","萍梗犹能合，风尘未见偕。","富春霜雪里，却忆凤喈喈。"]},{"t":"木假山","f":"五言律诗","c":["已幸脱煨烬，漂零故不辞。","肌肤浑尽剥，丰骨坐称奇。","㟝嵝羞相学，云霞信所为。","从兹别林薮，深结主人知。"]},{"t":"宿七里潭","f":"五言律诗","c":["无数滩皆恶，安恬独此潭。","溯流心共澹，汲古味能甘。","永夜鱼龙定，空山鬼魅谈。","高秋进萧䬃，行役遍东南。"]},{"t":"小野堂对菊","f":"五言律诗","c":["小野堂前菊，相逢满意花。","诸君抱冰雪，散地有烟霞。","傍月神犹整，当歌影故斜。","异时追此夕，萧瑟向瑶华。"]},{"t":"答曹仲礼见赠","f":"五言律诗","c":["未暇曹刘体，逍遥了岁年。","聊应备土缶，岂敢冒朱弦。","情性人俱得，咸英世不传。","从兹习喑哑，作用在忘筌。"]},{"t":"题程时言侍御和溪谱","f":"五言律诗","c":["君家好乔木，远影郁婆娑。","桂树青霄上，桃花骇浪多。","高峰回日月，大地涌星河。","近阅篁墩谱，燕山岂啻过。"]},{"t":"题田给事一竹轩","f":"五言律诗","c":["羡尔云霄势，泠然冰玉姿。","空斋寄森爽，独立出喧卑。","尚阻潇湘对，终收淇澳诗。","幔亭霜雪盛，应长凤凰枝。"]},{"t":"病居读顾与新诗","f":"五言律诗","c":["伏枕殊方客，秋风岁载阴。","鍊形功不就，抵病意何深。","稍出词章网，翻为著作淫。","头风顿觉愈，吾只爱陈琳。"]},{"t":"林沧洲下第赴荆门","f":"五言律诗","c":["怜君不得意，归鬓忽成丝。","更下荆门棹，还闻巫峡悲。","礼严徐孺榻，义重象山祠。","应念投竿客，终为帝者师。"]},{"t":"惠山酌第二泉","f":"五言律诗","c":["惠山好泉品，清切锡城隅。","松石阴堪结，莲蓉翠不孤。","寺虚流夜气，沙润长秋菰。","笑挈二三子，朔风近舞雩。"]},{"t":"忆思道","f":"五言律诗","c":["近忆棠陵子，还朝定此时。","肯为黄歇客，兴在白云司。","意气吾能共，江山君最奇。","夔龙格心事，天意要人为。"]},{"t":"读备遗录","f":"五言律诗","c":["神尧无信史，谁纪革除年。","龙虎风云上，山河涕泪边。","夷齐偏守死，王魏总知权。","三复春秋传，微词今不传。"]},{"t":"望雁宕","f":"五言律诗","c":["雁宕青到眼，天南秋复凉。","宁辞北山屐，来傍水仙王。","越鸟随风化，瓯童触雾黄。","未须悲道路，前是武陵乡。"]},{"t":"再哭近夫","f":"五言律诗","c":["近夫吾益友，失汝自吴江。","末世英雄短，平生涕泪双。","参乎真悟道，回也未为邦。","不见牛刀试，青田俗尽庞。"]},{"t":"刘实夫静观楼","f":"五言律诗","c":["刘子吾邦秀，高楼元气边。","定心还到眼，慧日正行天。","风物无拘碍，江山且岁年。","平生腾踏志，终要九潘渊。"]},{"t":"白将军","f":"五言律诗","c":["将军出武威，仗剑镇东陲。","气压风云阵，秋生熊虎姿。","长挥白羽扇，岂羡锐头儿。","数载伤多垒，云台及盛时。"]},{"t":"咄咄","f":"五言律诗","c":["咄咄长廊下，倡歌谁为闻。","世人皆梦寐，之子独风云。","土净菩提路，天垂星斗文。","犹存顶神咒，至语未曾分。"]},{"t":"赠欧阳崇道","f":"五言律诗","c":["使君廊庙器，秪惜颖川名。","世事忧无尽，吾邦兆已行。","况逢王者作，要使海波平。","倘及莘中隐，深耕自性情。"]},{"t":"哭仲默","f":"五言律诗","c":["去年孙复死，今复哭何休。","霄汉冥交尽，嵩邙正气收。","操戈吾岂敢，怀宝尔终投。","秪益文章价，年年照斗牛。"]},{"t":"谒紫阳精舍","f":"五言律诗","c":["山水奇如此，乾坤气所储。","昔贤遗笋蜕，异代俨门庐。","岁晏芝苓长，天高风露馀。","蹉跎逐簪笏，尚愧紫阳居。"]},{"t":"三陟","f":"五言律诗","c":["怜君忧思剧，三上白云山。","风树吹无尽，鸰原望不还。","堂阶抱古恨，松柏变秋颜。","莫以歌终曲，人生涕泪繁。"]},{"t":"春日怀京华诸友","f":"五言律诗","c":["闻说神龙起，群贤一网提。","中原刑白马，南国且黄鹂。","夜楫谁同击，春江他自迷。","无能逐公子，锡宴上林西。"]},{"t":"寄容台旧僚友","f":"五言律诗","c":["上德符元命，南宫列隽才。","周王郊祀毕，汉日辟雍开。","法驾新承幸，芝坛定数陪。","百年大礼乐，述作意悠哉。"]},{"t":"秋日寄赤城诸友","f":"五言律诗","c":["几载不相见，天台叶又飞。","行藏归一是，尧桀自相非。","江海完吾志，星霜变客衣。","风期与云会，莫遣道心微。"]},{"t":"夏雨","f":"五言律诗","c":["南天春苦旱，咎在岁星沉。","四月禾苗歇，三农雨望深。","油云肤寸合，一似雨黄金。","君王社稷主，要识上天心。"]},{"t":"张起溟得子","f":"五言律诗","c":["闻得充闾庆，青天眼不孤。","君犹倚桐树，此是凤凰雏。","昔日三苏出，眉山万木枯。","乡书日暮至，定报有嘉符。"]},{"t":"元夕登鳌峰绝顶","f":"五言律诗","c":["共尔寻芳酌，复从鳌顶行。","风烟有元夕，星汉下孤城。","石祖他年梦，山公一笑迎。","高歌倚梅树，瞻注有馀情。"]},{"t":"答陈鉴","f":"五言律诗","c":["武原陈仲举，惠我古苔篇。","读罢生阴籁，知君玄又玄。","高贤惠远社，归客洞庭船。","何日寻芳约，蓬山种玉田。"]},{"t":"除夕二首 其一","f":"五言律诗","c":["忽忽屠苏夕，匆匆吴楚春。","岁华无奈守，酒盏可怜频。","世短聊看斗，时艰复问津。","剑文差不翳，犹得慰情亲。"]},{"t":"除夕二首 其二","f":"五言律诗","c":["丧乱满天地，风烟无古今。","吴门又除夕，粤客未投簪。","灯晕他年梦，椒花故国心。","翻怜痴儿女，嬉笑夜堂深。"]},{"t":"秋月","f":"五言律诗","c":["初昏见秋月，耿耿即西倾。","河汉留光景，关山入杳冥。","众星森北向，一鸟浩南征。","莫遣微云起，渠能秽太清。"]},{"t":"吕梁","f":"五言律诗","c":["数载河为患，怅然思禹功。","源从西极下，水到吕梁雄。","天堑长淮北，地维沧海东。","应悲箜篌曲，宛转意何穷。"]},{"t":"王南渠隐居","f":"五言律诗","c":["冠山龙卧处，流水近沧洲。","形胜东南地，堂斋烟雨秋。","谏书存事业，逐客且林丘。","只看桐溪上，星文动斗牛。"]},{"t":"大田篇","f":"五言律诗","c":["君王提一旅，礼法用三驱。","木落鸿能矫，天寒虎在嵎。","风尘收猛士，骑射局文儒。","锐首谁家子，人间大丈夫。"]},{"t":"得友人书","f":"五言律诗","c":["每逢闽地客，数问尔沧洲。","摇落意如此，烟波去无繇。","传楫还长击，高柴未损忧。","因风寄幽独，蚤晚大刀头。"]},{"t":"再送李曲江","f":"五言律诗","c":["曲江山水县，暇日好弹琴。","要将流水意，遍作颖川唫。","王风周末异，瘴色日南深。","更点分明处，县知令尹心。"]},{"t":"怀思道","f":"五言律诗","c":["闻君留阙里，勾当未曾还。","五月过泗水，何时登太山。","道存夫子室，礼接鲁生颜。","星驾飘飘去，云天迥莫扳。"]},{"t":"寄小野","f":"五言律诗","c":["倪侯隐南国，食禄二千钟。","谁识神仙骨，长栖富贵丛。","梅花行岭外，雁字过蛮中。","何日飞寻女，而将黄鹤同。"]},{"t":"剑州","f":"五言古诗","c":["溪声下黯淡，山意会延平。","激漩当天险，横霄极地形。","黄堂严上界，廛舍倚高城。","龙剑真能合，虹桥本易成。","茶菰流土物，粳秫得人生。","李子濂伊嫡，刘滋卓鲁勍。","士多通古学，民不废春耕。","何处深传檄，兹邦乃苦兵。","方将采竹箭，奚暇糁藜羹。","正赖贤官府，艰虞系物情。"]},{"t":"除夕二首 其一","f":"五言古诗","c":["百战无宁日，穷年作宦情。","故山惟梦到，异域独灯明。","冰雪淹公子，风尘掩客星。","无家杜陵老，经乱郑康成。","北望关河固，东游岁月更。","安危仗王室，鼎食愧升平。"]},{"t":"除夕二首 其二","f":"五言古诗","c":["三元今夕到，群盗几时平。","河洛新流血，齐梁日请兵。","羽书连乐国，鞞鼓动神京。","大将真无敌，元凶未就烹。","地悲杀气盛，天苦岁功成。","进退吾何据，椒盘空复情。"]},{"t":"送司徒孙公归安陆五十韵","f":"古风","c":["国步多艰日，黄图八叶时。","正人俱逊避，冥运莽推移。","在昔先皇世，明公早典司。","菁华临騕袅，瞻听下须弥。","德业周王佐，贤劳汉度支。","坐舒千里足，遍察万方眉。","时值中原扰，频徵北鄙师。","向非筹百万，安得活疮痍。","理剧虚投刃，回淳重执规。","赤心医国石，白首向阳葵。","朝著留清望，廷争抗直词。","杜公良不忝，樊子岂无奇。","禄秩方登俊，儿童不免饥。","少焉看短鬓，率尔问青芝。","恳切封中疏，阗淤梦里思。","王言温莫挽，传马去犹驰。","肱股定虚旷，麒麟难系羁。","韦年宁待暮，常版却应谁。","允矣修初服，忻然集故知。","养真同在洛，忧世类还睢。","荜辂北宫子，鹿裘荣启期。","钓溪人罕识，游岳鹤长随。","信是劳筋息，其如柱石衰。","嵓堂喧燕雀，城社保鼷狸。","黔首歼金气，旄头直玉墀。","岂惟馀狡儿，遽使有鸱夷。","浩荡南溟徙，差池北斗垂。","帝能忘反侧，天未欲雍熙。","前席追才子，高轩沓健儿。","汾阳终复起，回纥定深疑。","世道今如此，言余何所之。","狂?通剑术，愤激撤书帷。","猥作龙门客，载歌淇澳诗。","未缘经品藻，窃幸受炉锤。","食忝侏儒粟，才妨寝庙牺。","役形酬顾遇，镂骨为嘘吹。","永愿参徒御，犹希附鼎彝。","此心何觊豁，人事竟离披。","贡禹情堪吊，任安义匪疵。","几能容傲吏，奚止失师资。","悢悢悲鸣铗，奄奄叹守雌。","肩随遑点染，影吊趣磷缁。","便作开笼鸟，还惭掉尾龟。","即寻鸥鹭好，甘与簿书辞。","采药灵源洞，纫荪少谷陂。","静便粗布褐，安稳小茆茨。","述作刑司马，冠缨薄李斯。","嵩高尘不杂，来挹九峰姿。"]},{"t":"闻吾廷介避乱客死藁?道隅","f":"五言古诗","c":["识面胥台夕，论心浒墅时。","功名非尔辈，文藻是吾师。","命薄长遗世，才高更忍饥。","天如产麟凤，王不梦熊罴。","久着东山屐，频歌濮水词。","邴原明进退，杜甫昩生涯。","已是哀黄发，仍兼陷赤眉。","修身浑欲到，得祸一何奇。","寂寞榱楹折，荒芜气运衰。","人皆牖下死，子有道傍疑。","叔宝时多惜，嵇康我独悲。","君门数行泪，不但致吾私。"]},{"t":"寿林大司马四十韵","f":"五言古诗","c":["当代论耆德，先生第一人。","行年老益壮，浴已日犹新。","九牧衣冠胄，三朝柱石臣。","时流立标准，前辈想丰神。","伊昔遭平世，超然充大宾。","东寮注柳肃，内史倒陈遵。","奇思过常调，修能异等伦。","一生随日驭，十载在成均。","古学薰移俗，名贤类受甄。","牵裾留短草，启事起枯鳞。","琼佩辞仙仗，金陵秉大钧。","岂无云锦线，可补舜衣鹑。","鸿运丁天厌，元龟卜世屯。","文狸翔粉堞，玉玦下枫宸。","温国言归洛，宣尼罢问津。","岁功成者退，初服誓当伸。","几杖苍生慕，松筠白发亲。","起居全矍铄，容色愈温纯。","不论临卑幼，都如饮酪醇。","达尊人代少，幽意岁华频。","寄癖泉山麓，移舟越水滨。","犹能作小楷，亦称戴高巾。","奚用推洪范，终然比大椿。","寿临文彦博，子得范纯仁。","极北陈情切，滇南税驾真。","言将欢菽水，不是忆鲈莼。","臣父深思子，臣儿愿委身。","明王念勋旧，温语蔼丝纶。","李密近还蜀，张良未谢秦。","银鱼绾房杜，玉树集陈荀。","莱綵偏宜晚，潘舆每及晨。","风吹绿野暮，花发锦堂春。","刺史宣前烈，春官振后尘。","品题惟凤鸟，图画必麒麟。","二月山川丽，全闽气象臻。","嵩乎钟匪物，甫也降兹辰。","度曲来鹓鹤，称杯拜缙绅。","龙门登尚忝，骥尾附何因。","感激吾将仕，沾濡俗到淳。","太平若有象，早晚下蒲轮。"]},{"t":"送周方伯入楚五十六韵","f":"五言古诗","c":["南来日月浅，歘作洞庭游。","宦达多离坼，旌麾还阻修。","人情乌石雨，仙路豫章舟。","树直黄陵庙，花明白鹭洲。","攀轩啼老少，拥彗振王侯。","毒草祠能久，濂溪井尚留。","贤声望宰辅，伊昔盛才猷。","八辟参邦典，群疑反楚囚。","青莲分黑白，丹笔斡宸旒。","退食惟书卷，攒眉视贵游。","坐兹不速化，宁自向明投。","先帝需梁栋，春官杂枓樛。","匪材随鉴澈，是岁辱甄收。","分忝门生列，知悬孺子酬。","青云长契阔，白帝正岣嵧。","公去安边徼，余归滞故丘。","数年鳞杳杳，两地鬓飕飕。","诸葛绥西土，文翁化益州。","夷酋达礼乐，武弁冠貔貅。","自古贤人远，殊方圣主诹。","朔风吹鸟道，春雨下龙湫。","天共滇池远，人兼泮水幽。","两川思几杖，六诏赖怀柔。","僰俗元来野，华风今始流。","文鹓既翙翙，鸣鹿亦呦呦。","欲见唐虞理，何烦猿狖愁。","几时卿月照，复尔使星浮。","三晋悲歌切，中原盗贼稠。","徬徨家室走，感激岁时遒。","道在无荆棘，时艰任寇雠。","终焉脱虎口，直拟谢蝇头。","天欲昌王室，帝能追马周。","风高沙塞暮，草歇雁门秋。","十二事皆举，权豪势不勾。","食刍无款段，出牧尽骅骝。","世待英雄急，公宜物色求。","无诸所胙土，马亮载鸣驺。","玉节沾应得，风谣采未休。","先声靖强禦，能事属歌讴。","霄汉瞻洪翮，泥涂非好仇。","狄笼充实忝，徐榻下何绸。","愿縳南山虎，翻惊北海鸥。","倚风悲骀荡，望斗念伛偻。","贫贷邻人粟，寒披季子裘。","热中闻舐痔，毕意避牺牛。","名位争相笑，悲歌不自由。","谁能见客意，何以解吾忧。","夜雨听希旷，春波转缪悠。","大廷稽职业，南服趣恩庥。","江汉雄藩镇，夔龙注庙谋。","双旌一以远，千里秪须抠。","即欲随黄鹄，终知愧秃鹙。","草深鹦鹉冢，天迥岳阳楼。","范老端忧乐，祢衡招咎尤。","独醒心缕缕，北面意慺慺。","公若登三事，须张竟野罘。"]},{"t":"铅山书事十二韵","f":"五言古诗","c":["闻道坎山里，群豪挠信州。","仇家县胆在，死士散金收。","赵厕机关重，秦庭报复稠。","执言修大怼，负固震诸侯。","落日闾阎恐，悲风井径愁。","抚绥须早计，变乱未干休。","赤子元无罪，红巾揆所由。","至诚驯虎豹，极处动貔貅。","六邑疲供应，三农讼咎尤。","风尘将不靖，土地尔何求。","即鉴前车覆，母贻后事忧。","朝廷讳首恶，贤相合深筹。"]},{"t":"东游","f":"五言古诗","c":["已是闭关月，漫游何处邦。","北风帆势直，南纪岁华妨。","负胜轻河岳，哀时挹伯王。","衣冠明葬处，俎豆盛蛮方。","忽忆春秋际，兼怀种蠡良。","图王功己巳，去国意茫茫。","万事空搔首，诸贤足断肠。","东征效蘋藻，大观出玄黄。","雨蚀曹娥庙，山疑谢傅堂。","洑波平愤懑，旧燕落寻常。","忼慨吾能赋，风流谁更狂。","飘飘王逸少，磊磊贺知章。","真帖兰亭秘，遗荣剡水光。","鉴湖秦望近，云寺若耶荒。","皓齿此溪女，紫骝何郡郎。","隔花相问姓，采菲欲遗芳。","未逐支公隐，能无许掾藏。","雪舟行独远，禹穴探尤长。","木客胡麻饭，山夔薜荔裳。","桃花源不昩，野鸟恨难忘。","自此升台岳，骑驴过石梁。","仙风去若脱，八极信翱翔。"]},{"t":"得家信","f":"五言古诗","c":["未觉今为是，田园报已荒。","蛮云深结白，朔日迥含黄。","社稷已如此，公卿犹病狂。","冠裳风一变，战伐意何长。","爵可加天位，勋兼拟法王。","甘泉久抗疏，不得达明光。"]},{"t":"野江为舒国裳父作","f":"五言古诗","c":["徐稚藏身在，南州卧不妨。","经年歌白石，乘月下沧浪。","江抱洪都府，堂开辋口庄。","蓝田种有玉，磻水钓惟璜。","会见蛟龙起，俄惊鹳鹤翔。","无由相高志，把赠芰荷裳。"]},{"t":"乡人","f":"五言古诗","c":["令叔吾兄弟，仲容贤侄行。","宦情游里闬，人事近阴阳。","何路通闽徼，中原入战场。","应怜起草石，竟失浣花堂。","太乙长迁次，搀抢转耀芒。","山河醉眼底，别尔思茫茫。"]},{"t":"与思道叙别四十八韵","f":"五言古诗","c":["忆昔勾吴日，相逢云水乡。","于时最孤寂，得汝共翱翔。","岂倦登临费，兼存药石良。","三春谢氏屐，十度远公堂。","大石留腰带，阳山接羽觞。","秋风白莲赋，落日洞庭航。","坐听吴趋曲，行歌子夜央。","时时动星象，处处有文章。","雨夕舟偏讨，公庭事不妨。","投胶情最密，丽泽意何长。","作赋相如病，弹琴宓子臧。","君才当十倍，为宰仅三霜。","备见嘉禾出，胡云贝锦张。","邑皆怀范宁，人只妒邹阳。","日月难终掩，声名转益扬。","几时停谷鸟，独往钓溪鲂。","人事尤参错，兵戈逐丧亡。","尔归频洒血，余去苦回肠。","百粤风尘色，三衢荆棘场。","棠陵居独稳，太末势堪伤。","消息传谁健，艰难到女旁。","鸿飞多不及，豹隐但相望。","已分生无日，何期此对床。","精神宁少壮，鬓发各沧浪。","骤见犹疑梦，翻思秪欲狂。","人情更怜并，天意遂行藏。","妻子尽相信，形骸真所忘。","缁尘心少称，青眼慰多方。","管鲍平时义，雷陈后代光。","旷怀卑藻饰，素业略侯王。","葵藿元同志，雷霆讵有常。","赐环怜是月，持节向何邦。","太液秋风落，桑乾木叶黄。","翛然改节物，自此判参商。","向秀悲无奈，杜陵忧未遑。","汉皇惟好武，尧德本垂裳。","欲折淮南馘，行穿涿鹿杨。","迢迢思汲黯，隐隐忌姚苌。","万骑虚边戍，深宵引御幢。","恒山穷鸟兽，上党泣壶浆。","征伐名虽正，巡游志莫荒。","秪须移北极，况已复南昌。","福德知何处，欃枪屡耀芒。","顿能忧绝域，翻不备萧墙。","儒术元迂阔，华裾载祸殃。","申屠甘绝迹，大邴尚为郎。","江汉情何极，鲈莼兴可偿。","归期晚自计，分手各茫茫。"]},{"t":"台上","f":"五言古诗","c":["塞水波声杳，宫墙木叶深。","君王载戎服，岁晚过汾阴。","白纛风云气，玄冥鸿雁音。","稻粱犹有分，轩冕竟何心。","秪放中原鹿，翻田上苑禽。","忧时谁向道，端合早投簪。"]},{"t":"送人之金陵","f":"五言古诗","c":["金陵吏隐去，结绶兴悠哉。","沧海东南奠，长江巴蜀来。","白门万柳树，袅袅接行杯。","晋室风流在，犹传谢傅才。","花繁佳丽地，天近凤凰台。","秪忆鲈鱼美，乡书旦暮回。"]},{"t":"送李川父赴沔阳","f":"五言古诗","c":["一杯燕市酒，别尔意难平。","嵩岳冥栖客，沅湘游宦情。","南风吹锦旆，遥度竟陵城。","吴楚兵初解，邹枚道自行。","如何歌郢曲，秪以触猿声。","宣室思才子，能无召贾生。"]},{"t":"卫河集别","f":"五言古诗","c":["去国心仍苦，风尘病未休。","六飞淹岁月，八极想遨游。","水动鱼龙夕，云盘鹳鹗秋。","江山回紫气，沙塞度青牛。","秪有簪萍恋，聊为文字留。","遐心渺无尽，寄与卫河流。"]},{"t":"吴隐君山居","f":"五言古诗","c":["吾慕汉阴老，清修难具论。","儿童少机事，麋鹿到柴门。","备见幽人吉，还闻静者尊。","高贤床下拜，龙虎鼎中喧。","古道日已远，仙风今罕存。","县知出世意，接手入湘源。"]},{"t":"永阳方广岩观从儿戏入灵羊谷","f":"五言古诗","c":["共有方岩志，鸣桡入永阳。","山疑子午谷，水是武陵乡。","石室罗星汉，风泉积混茫。","直寻前代迹，多见昔人狂。","龙德存幽侧，神功大晦藏。","会须乘白鹿，莫倚过灵羊。","采秀青林杳，看云白业长。","傥逢蔡道者，为彼出迷方。"]},{"t":"赠郑中丞二十韵","f":"五言古诗","c":["皇道中兴日，关河气郁盘。","卿云回柏殿，麟趾出人间。","帝用徵良弼，人今起谢安。","玄纁到沧海，夫子罢黄冠。","眷注时难得，才贤印不刓。","洪都开大府，节钺抚诸蛮。","举目旬宣地，知君涕泪繁。","囚梁脱虎口，归汉远龙颜。","颠倒多方试，悲悽九返丹。","匡庐留嶪屼，彭蠡厌波澜。","况值荆吴变，何论土地残。","主忧宁俟驾，君出岂移山。","岊水思钧候，茶溪接露翰。","白头吟不断，青眼迥犹看。","末分虚县榻，新词议筑坛。","同含九鲤日，并考木兰槃。","栎社堪长弃，龙沙会起蟠。","霞裾余独引，霄鬣尔难攀。","茅拔多连茹，时明且钓磻。","烟波去无极，相报一纶竿。"]},{"t":"送林待用司空四十韵","f":"五言古诗","c":["海岳开灵秘，东南孕隽畸。","公才惊代出，吾道要人为。","鸑鷟时希有，珊瑚世共知。","郢斤森在手，刚斧斫先枝。","王业寻常就，天朝际会迟。","乃婴喉下阨，转听陇头悲。","脉脉餐元命，踆踆饰履綦。","经过盘错遍，展转庙廊思。","直道淹黄发，馀生随白鹥。","经纶一以卷，霄汉欲何之。","霞外修灵气，槎边立钓丝。","众星还识斗，百草秪如芝。","蜀道忧多垒，王言召子仪。","星奔赴国难，虚捣拔枭旗。","云鸟元相法，风尘不自夷。","千秋诛白帝，一笑下峨嵋。","物态疲衣狗，年华变意鸸。","留侯乃辟谷，尼父退修辞。","兰渚烟波定，云庄岁月驰。","宁云近耄耋，忽漫致雍熙。","紫气流金阙，黄龙下玉墀。","君王是尧舜，辅弼必皋夔。","三统收今日，群贤网在兹。","丹青得舟楫，畋猎岂熊罴。","只简先生去，频传帝语来。","玄圭表锡望，黔首视安危。","如此中兴主，那看后命推。","意成鱼水合，道在凤麟羁。","钟鼎人能铸，栋梁今不衰。","愿闻歌帝力，直拟察氓眉。","勋业青冥润，文章后辈师。","眼青相见日，心赤索居时。","鱼绶身三伛，龙泉手一提。","不成赴沟壑，讵敢息镃基。","岊水青阳逼，沧溟锦䌫移。","永怀登藻鉴，况惜别师资。","幽独行将暮，娉婷迥自怡。","长空古意澹，落日壮心飞。","抱室谁同调，弹冠此作期。","因风送黄鹄，目尽五云涯。"]},{"t":"寄时行宪副","f":"五言古诗","c":["闻君靖百粤，閒拥节旄游。","铙吹军门静，云山开府幽。","飞书报谷口，邀我入罗浮。","一自沧溟别，长惊碧树秋。","乾坤今始泰，勋业尔应留。","傥遂丹砂计，相寻海上洲。"]},{"t":"书情十二韵","f":"五言古诗","c":["毛生辞辟命，王绩遁人群。","贤者讵可测，醉乡聊自云。","抗情干木石，著论逼河汾。","而我风尘质，依依愧所闻。","碧山随旧业，白日近浮云。","殷道求伊傅，周王化汝坟。","古风何契阔，吾志底辛勤。","耻掉留侯舌，羞称管氏勋。","民穷思圣世，身远恋明君。","落日天西梦，幽忧记不分。","龙蟠时必作，鹏息气方殷。","此意终难就，吾将迈紫氛。"]},{"t":"答人问沧海","f":"五言古诗","c":["久作持竿客，沧洲话独真。","潮声雄度浙，海势侧分闽。","星汉涵无地，风云变有神。","蜃楼开弱水，鳌极断河津。","失意歌渔父，离群忆古人。","惟应白鸥鸟，浩淼得相亲。"]},{"t":"寄题七峰隐居十韵","f":"五言古诗","c":["棠陵书问至，命我七峰歌。","我今双鬓改，其柰七峰何。","忆避吴趋寇，会遵孟渎河。","眼深孙楚宅，心激鲁阳戈。","霜镝干云日，霞居享薜萝。","犹闻钓蛟蜃，宁复畏湖波。","浩啸苏门诵，名方海上科。","贤豪似尔少，膏馥及人多。","芝菌盘霝洞，山川抱曲阿。","吾将济汝汉，初路为经过。"]},{"t":"岊山留别诸子","f":"五言古诗","c":["握手情何尽，为郎鬓已秋。","那为岊上别，转作秣陵游。","贾傅狂唯甚，王阳道必优。","时犹遇舜禹，志窃慕伊周。","风断黄金市，云愁白鹭洲。","从容赴散地，一似卧林丘。","宝剑缘轻试，明珠岂暗投。","经纶晚自计，只漫钓鱼舟。"]},{"t":"哭朱侍御","f":"五言古诗","c":["哭友魂初返，兄今复讣音。","杞忧元不寐，颜乐秪须寻。","江海投胶意，乾坤揽辔心。","成言俱寂寞，胜事竟销沉。","邦国贤豪尽，关河涕泪深。","瓣香与絮酒，咫尺到山阴。"]},{"t":"忆昔","f":"五言古诗","c":["忆昔先皇帝，黄金高筑台。","剧辛自赵往，邹衍复齐来。","今日风波事，谁当砥柱材。","金鸡还浩荡，黄雀总㳙埃。","久见文昌厄，何论国士灾。","君看党锢传，千古使人哀。"]},{"t":"亭上","f":"七言律诗","c":["少谷峰头草亭好，清秋原衍争繁芬。","石上昌阳尽九节，笋根稚子皆此君。","放言何求了物意，恼世不彻参天文。","平生最爱陶弘景，青山百年怡白云。"]}]};